CREATE OR REPLACE FUNCTION public._attempt_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.payment_group_id <> OLD.payment_group_id
     OR NEW.canonical_request_hash <> OLD.canonical_request_hash
     OR NEW.request_schema_version <> OLD.request_schema_version
     OR (OLD.stripe_checkout_session_id IS NOT NULL AND NEW.stripe_checkout_session_id IS DISTINCT FROM OLD.stripe_checkout_session_id) THEN
    RAISE EXCEPTION 'payment_attempt identity is immutable';
  END IF;
  IF OLD.stripe_payment_intent_id IS NOT NULL AND NEW.stripe_payment_intent_id IS DISTINCT FROM OLD.stripe_payment_intent_id THEN
    RAISE EXCEPTION 'payment_attempt PI is null-to-value only';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._booker_authorize(p_member_id uuid, p_brand_id uuid, p_retailer_id uuid, p_default_demo text, p_default_cancel text, p_tos_version text)
 RETURNS brand_members
 LANGUAGE plpgsql
AS $function$
DECLARE v_m brand_members%ROWTYPE; v_r record; v_hash text; v_a record;
BEGIN
  SELECT * INTO v_m FROM brand_members WHERE id = p_member_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'booker_not_a_member' USING errcode = 'check_violation'; END IF;
  IF v_m.brand_id <> p_brand_id OR v_m.status <> 'accepted' THEN RAISE EXCEPTION 'booker_not_a_member' USING errcode = 'check_violation'; END IF;
  IF v_m.role = 'booker' THEN
    SELECT id, demo_policy, cancellation_policy INTO v_r FROM retailers WHERE id = p_retailer_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'retailer_not_found' USING errcode = 'check_violation'; END IF;
    v_hash := agreement_policy_hash(v_r.demo_policy, v_r.cancellation_policy, p_default_demo, p_default_cancel, p_tos_version);
    SELECT id, policy_hash, expires_at INTO v_a FROM brand_retailer_agreements
     WHERE brand_id = p_brand_id AND retailer_id = p_retailer_id AND superseded_at IS NULL
     ORDER BY signed_at DESC LIMIT 1 FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'agreement_required_owner:never_signed' USING errcode = 'check_violation'; END IF;
    IF v_a.expires_at IS NOT NULL AND v_a.expires_at < now() THEN RAISE EXCEPTION 'agreement_required_owner:expired' USING errcode = 'check_violation'; END IF;
    IF v_a.policy_hash IS DISTINCT FROM v_hash THEN RAISE EXCEPTION 'agreement_required_owner:policy_changed' USING errcode = 'check_violation'; END IF;
  END IF;
  RETURN v_m;
END $function$

CREATE OR REPLACE FUNCTION public._cancellation_resolution_finalize(p_booking_id uuid)
 RETURNS booking_cancellation_resolutions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_res public.booking_cancellation_resolutions%ROWTYPE; v_rq_status text; v_money_done boolean;
BEGIN
  SELECT * INTO v_res FROM public.booking_cancellation_resolutions WHERE booking_id = p_booking_id;
  IF NOT FOUND OR v_res.state = 'completed' THEN RETURN v_res; END IF;
  IF v_res.decision = 'no_refund' THEN
    v_money_done := true;
  ELSE
    v_money_done := false;
    IF v_res.refund_request_id IS NOT NULL AND v_res.refund_submitted_at IS NOT NULL THEN
      SELECT rq.status INTO v_rq_status FROM public.refund_requests rq WHERE rq.id = v_res.refund_request_id;
      v_money_done := v_rq_status IN ('submitted', 'pending', 'succeeded');
    END IF;
  END IF;
  IF v_money_done AND v_res.case_closed_at IS NOT NULL AND v_res.brand_notified_at IS NOT NULL THEN
    UPDATE public.booking_cancellation_resolutions
       SET state = 'completed', escalation_cleared_at = CASE WHEN escalated_at IS NOT NULL THEN coalesce(escalation_cleared_at, now()) ELSE escalation_cleared_at END, last_error = NULL, updated_at = now()
     WHERE booking_id = p_booking_id RETURNING * INTO v_res;
    UPDATE public.reconciliation_cases SET status = 'resolved', resolved_by = coalesce(v_res.operator, 'refund-review'), resolved_at = now()
     WHERE (id = v_res.escalated_case_id OR dedupe_key = 'resolution-failed:' || p_booking_id::text) AND status <> 'resolved';
  END IF;
  RETURN v_res;
END $function$

CREATE OR REPLACE FUNCTION public._catalog_snapshot(p_brand_id uuid, p_item_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE v_products jsonb; v_out jsonb := '[]'::jsonb; v_id text; v_item jsonb; v_seen text[] := '{}';
BEGIN
  IF p_item_ids IS NULL OR array_length(p_item_ids, 1) IS NULL THEN RAISE EXCEPTION 'products_required' USING errcode = 'check_violation'; END IF;
  IF array_length(p_item_ids, 1) > 40 THEN RAISE EXCEPTION 'too_many_items' USING errcode = 'check_violation'; END IF;
  SELECT products INTO v_products FROM brands WHERE id = p_brand_id FOR SHARE;
  IF v_products IS NULL OR jsonb_typeof(v_products) <> 'array' THEN RAISE EXCEPTION 'items_not_in_catalog' USING errcode = 'check_violation'; END IF;
  FOREACH v_id IN ARRAY p_item_ids LOOP
    IF v_id = ANY (v_seen) THEN RAISE EXCEPTION 'duplicate_item' USING errcode = 'check_violation'; END IF;
    v_seen := v_seen || v_id;
    SELECT e INTO v_item FROM jsonb_array_elements(v_products) e WHERE e->>'id' = v_id AND coalesce(e->>'name', '') <> '' LIMIT 1;
    IF v_item IS NULL THEN RAISE EXCEPTION 'items_not_in_catalog' USING errcode = 'check_violation'; END IF;
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'id', v_item->>'id', 'name', v_item->>'name', 'size', coalesce(v_item->>'size', ''), 'sku', coalesce(v_item->>'sku', ''), 'upc', coalesce(v_item->>'upc', ''),
      'distributor', coalesce(v_item->>'distributor', ''), 'distributor_other', coalesce(v_item->>'distributor_other', ''), 'distributor_item_number', coalesce(v_item->>'distributor_item_number', ''),
      'case_pack', CASE WHEN jsonb_typeof(v_item->'case_pack') = 'number' THEN v_item->'case_pack' ELSE 'null'::jsonb END, 'notes', coalesce(v_item->>'notes', '')));
  END LOOP;
  RETURN v_out;
END $function$

CREATE OR REPLACE FUNCTION public._open_case(p_kind text, p_dedupe text, p_reason text, p_group uuid, p_request uuid, p_operation uuid, p_session text, p_pi text, p_charge text, p_refund text, p_amount integer, p_currency text, p_details jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF p_dedupe IS NOT NULL THEN
    SELECT id INTO v_id FROM reconciliation_cases WHERE dedupe_key = p_dedupe;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  END IF;
  BEGIN
    INSERT INTO reconciliation_cases(kind, dedupe_key, reason, payment_group_id, refund_request_id, refund_operation_id,
        stripe_checkout_session_id, stripe_payment_intent_id, stripe_charge_id, stripe_refund_id, amount, currency, details)
      VALUES (p_kind, p_dedupe, p_reason, p_group, p_request, p_operation, p_session, p_pi, p_charge, p_refund, p_amount, p_currency, p_details)
      RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_id FROM reconciliation_cases WHERE dedupe_key = p_dedupe;   -- concurrent opener won
  END;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public._pa_currency_matches_group()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE g_cur text;
BEGIN
  SELECT currency INTO g_cur FROM payment_groups WHERE id = NEW.payment_group_id;
  IF g_cur IS NOT NULL AND lower(NEW.currency) <> lower(g_cur) THEN
    RAISE EXCEPTION 'allocation currency % <> group currency %', NEW.currency, g_cur;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._pa_refuse_fee_waived()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM bookings b WHERE b.id = NEW.booking_id AND b.fee_waived) THEN
    RAISE EXCEPTION 'booking_fee_waived: booking % is free and cannot enter checkout', NEW.booking_id USING errcode = 'check_violation';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._pg_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.brand_id <> OLD.brand_id OR NEW.retailer_id <> OLD.retailer_id
     OR NEW.currency <> OLD.currency OR NEW.platform_keeps_all <> OLD.platform_keeps_all
     OR coalesce(NEW.connect_account_id,'') <> coalesce(OLD.connect_account_id,'')
     OR NEW.fee_policy_version <> OLD.fee_policy_version THEN
    RAISE EXCEPTION 'payment_group financial snapshot is immutable';
  END IF;
  IF NEW.total_customer_amount <> OLD.total_customer_amount AND OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'payment_group total is immutable once out of pending';
  END IF;
  -- write-once Stripe identity
  IF OLD.stripe_checkout_session_id IS NOT NULL AND NEW.stripe_checkout_session_id IS DISTINCT FROM OLD.stripe_checkout_session_id THEN RAISE EXCEPTION 'session id write-once'; END IF;
  IF OLD.stripe_payment_intent_id   IS NOT NULL AND NEW.stripe_payment_intent_id   IS DISTINCT FROM OLD.stripe_payment_intent_id   THEN RAISE EXCEPTION 'pi id write-once'; END IF;
  IF OLD.stripe_charge_id           IS NOT NULL AND NEW.stripe_charge_id           IS DISTINCT FROM OLD.stripe_charge_id           THEN RAISE EXCEPTION 'charge id write-once'; END IF;
  IF OLD.stripe_transfer_id         IS NOT NULL AND NEW.stripe_transfer_id         IS DISTINCT FROM OLD.stripe_transfer_id         THEN RAISE EXCEPTION 'transfer id write-once'; END IF;
  IF OLD.stripe_application_fee_id  IS NOT NULL AND NEW.stripe_application_fee_id  IS DISTINCT FROM OLD.stripe_application_fee_id  THEN RAISE EXCEPTION 'app fee id write-once'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._refund_booking_matches_alloc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_alloc_booking uuid;
BEGIN
  SELECT booking_id INTO v_alloc_booking FROM payment_allocations WHERE id = NEW.payment_allocation_id;
  IF v_alloc_booking IS NULL OR v_alloc_booking <> NEW.booking_id THEN
    RAISE EXCEPTION 'refund booking_id must match allocation booking_id';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._refund_linkage_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.booking_id <> OLD.booking_id OR NEW.payment_allocation_id <> OLD.payment_allocation_id THEN
    RAISE EXCEPTION 'refund booking/allocation linkage is immutable';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.accept_reschedule(p_booking_id uuid, p_brand_id uuid, p_proposal_version integer)
 RETURNS TABLE(ok boolean, reason text, schedule_revision integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_b        bookings%ROWTYPE;
  v_d        demos%ROWTYPE;
  v_brand    brands%ROWTYPE;
  v_tz       text;
  v_today    date;
  v_new_date date;
  v_new_time text;
  v_old_rev  integer;
  v_new_rev  integer;
  v_new_dur  integer;
  v_covered  boolean;
BEGIN
  SELECT * INTO v_b FROM bookings b WHERE b.id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found'::text, NULL::integer; RETURN; END IF;
  SELECT * INTO v_d FROM demos d WHERE d.booking_id = p_booking_id ORDER BY d.created_at LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'no_demo'::text, v_b.schedule_revision; RETURN; END IF;
  IF p_brand_id IS NULL OR coalesce(v_b.brand_id, v_d.brand_id) IS DISTINCT FROM p_brand_id THEN
    RETURN QUERY SELECT false, 'forbidden'::text, v_b.schedule_revision; RETURN;
  END IF;
  IF coalesce(v_b.status, 'pending') NOT IN ('pending', 'confirmed') OR coalesce(v_d.status, '') NOT IN ('confirmed', 'scheduled') THEN
    RETURN QUERY SELECT false, 'cancelled'::text, v_b.schedule_revision; RETURN;
  END IF;
  -- RM-1 (0095): no schedule change while a declined / lapsed move is being settled.
  IF v_b.pending_move_settlement IS NOT NULL OR v_b.cancellation_pending_at IS NOT NULL THEN   -- 0106: a recorded cancellation is a barrier too
    RETURN QUERY SELECT false, 'cancellation_pending'::text, v_b.schedule_revision; RETURN;
  END IF;
  IF v_d.reschedule_to_date IS NULL THEN RETURN QUERY SELECT false, 'no_proposal'::text, v_b.schedule_revision; RETURN; END IF;
  IF p_proposal_version IS NULL OR v_b.reschedule_proposal_version <> p_proposal_version THEN
    RETURN QUERY SELECT false, 'stale_proposal'::text, v_b.schedule_revision; RETURN;
  END IF;
  v_new_date := v_d.reschedule_to_date;
  v_new_time := coalesce(nullif(btrim(v_d.reschedule_to_time), ''), v_b.demo_time, v_d.demo_time);
  SELECT r.timezone INTO v_tz FROM retailers r WHERE r.id = v_b.retailer_id;
  v_tz := coalesce(nullif(btrim(v_tz), ''), 'America/Los_Angeles');
  v_today := (now() AT TIME ZONE v_tz)::date;
  IF v_new_date < v_today THEN RETURN QUERY SELECT false, 'date_in_past'::text, v_b.schedule_revision; RETURN; END IF;
  SELECT * INTO v_brand FROM brands br WHERE br.id = p_brand_id;
  v_covered := (v_b.coi_waived_at IS NOT NULL)
            OR (v_brand.default_coi_url IS NOT NULL
                AND lower(coalesce(v_brand.coi_verification_status, '')) IN ('passed', 'approved')
                AND v_brand.default_coi_expires IS NOT NULL
                AND v_brand.default_coi_expires >= v_new_date);
  IF NOT coalesce(v_covered, false) THEN RETURN QUERY SELECT false, 'coi_not_covered'::text, v_b.schedule_revision; RETURN; END IF;
  v_old_rev := v_b.schedule_revision;
  BEGIN
    UPDATE bookings
       SET demo_date = v_new_date,
           demo_time = v_new_time,
           schedule_revision = bookings.schedule_revision + 1
     WHERE id = p_booking_id
    RETURNING bookings.schedule_revision, bookings.duration_hours INTO v_new_rev, v_new_dur;
  EXCEPTION WHEN check_violation THEN
    IF SQLERRM LIKE 'slot_full%' THEN RETURN QUERY SELECT false, 'slot_full'::text, v_old_rev; RETURN; END IF;
    IF SQLERRM LIKE 'slot_not_offered%' THEN RETURN QUERY SELECT false, 'slot_not_offered'::text, v_old_rev; RETURN; END IF;
    IF SQLERRM LIKE 'slot_outside_hours%' THEN RETURN QUERY SELECT false, 'slot_outside_hours'::text, v_old_rev; RETURN; END IF;
    IF SQLERRM LIKE 'date_blackout%' THEN RETURN QUERY SELECT false, 'date_blackout'::text, v_old_rev; RETURN; END IF;
    IF SQLERRM LIKE 'venue_closed%' THEN RETURN QUERY SELECT false, 'venue_closed'::text, v_old_rev; RETURN; END IF;
    IF SQLERRM LIKE 'slot_config_invalid%' THEN RETURN QUERY SELECT false, 'slot_config_invalid'::text, v_old_rev; RETURN; END IF;
    IF SQLERRM LIKE 'venue_hours_not_set%' THEN RETURN QUERY SELECT false, 'venue_hours_not_set'::text, v_old_rev; RETURN; END IF;
    IF SQLERRM LIKE 'invalid_local_time%' THEN RETURN QUERY SELECT false, 'invalid_local_time'::text, v_old_rev; RETURN; END IF;
    RAISE;
  END;
  UPDATE demos
     SET demo_date = v_new_date, demo_time = v_new_time,
         duration_hours = coalesce(v_new_dur, demos.duration_hours),
         reschedule_to_date = NULL, reschedule_to_time = NULL, reschedule_requested_at = NULL
   WHERE id = v_d.id;
  -- RM-1 (0095): a valid newer schedule retires any unanswered retailer move atomically.
  UPDATE booking_moves SET status = 'superseded', updated_at = now()
   WHERE booking_moves.booking_id = p_booking_id AND booking_moves.status = 'pending';
  INSERT INTO notification_events (retailer_id, booking_id, brand_id, kind, transition_id, payload)
  VALUES (v_b.retailer_id, p_booking_id, coalesce(v_b.brand_id, v_d.brand_id), 'demo_rescheduled',
          p_booking_id::text || ':rescheduled:' || v_new_rev::text,
          jsonb_build_object('old_date', v_b.demo_date, 'old_time', v_b.demo_time, 'old_schedule_revision', v_old_rev,
                             'new_date', v_new_date, 'new_time', v_new_time, 'schedule_revision', v_new_rev,
                             'venue_id', v_b.venue_id, 'timezone', v_tz, 'proposal_version', p_proposal_version))
  ON CONFLICT (kind, transition_id) DO NOTHING;
  UPDATE notification_deliveries
     SET status = 'skipped', skip_reason = 'rescheduled', updated_at = now()
   WHERE occurrence_key = p_booking_id::text || ':' || v_old_rev::text
     AND status IN ('pending', 'claimed');
  RETURN QUERY SELECT true, NULL::text, v_new_rev;
END $function$

CREATE OR REPLACE FUNCTION public.agreement_sign(p_brand_id uuid, p_retailer_id uuid, p_signed_email text, p_signed_name text, p_signed_ip text, p_user_agent text, p_expected_hash text, p_default_demo text, p_default_cancel text, p_tos_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_r retailers%ROWTYPE; v_hash text; v_prior brand_retailer_agreements%ROWTYPE; v_new_id uuid; v_demo text; v_cancel text;
BEGIN
  IF p_brand_id IS NULL OR p_retailer_id IS NULL THEN RAISE EXCEPTION 'agreement_sign: brand and retailer required' USING errcode = 'check_violation'; END IF;
  IF coalesce(btrim(p_signed_name), '') = '' OR length(btrim(p_signed_name)) < 2 THEN RETURN jsonb_build_object('outcome', 'signed_name_required'); END IF;
  IF coalesce(btrim(p_expected_hash), '') = '' THEN RETURN jsonb_build_object('outcome', 'policy_hash_required'); END IF;
  -- one signer at a time per brand+store; the store's text held stable while we compare and write
  PERFORM pg_advisory_xact_lock(hashtext('agreement_sign:' || p_brand_id::text || ':' || p_retailer_id::text));
  SELECT * INTO v_r FROM retailers WHERE id = p_retailer_id FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'retailer_not_found'); END IF;
  v_hash := agreement_policy_hash(v_r.demo_policy, v_r.cancellation_policy, p_default_demo, p_default_cancel, p_tos_version);
  IF lower(btrim(p_expected_hash)) <> v_hash THEN
    RETURN jsonb_build_object('outcome', 'policy_changed', 'current_hash', v_hash);
  END IF;
  SELECT * INTO v_prior FROM brand_retailer_agreements
   WHERE brand_id = p_brand_id AND retailer_id = p_retailer_id AND superseded_at IS NULL
   ORDER BY signed_at DESC LIMIT 1 FOR UPDATE;
  IF FOUND AND v_prior.policy_hash = v_hash AND v_prior.expires_at > now() THEN
    RETURN jsonb_build_object('outcome', 'already_current', 'agreement_id', v_prior.id, 'policy_hash', v_hash, 'signed_at', v_prior.signed_at);
  END IF;
  v_demo := coalesce(nullif(v_r.demo_policy, ''), p_default_demo);
  v_cancel := coalesce(nullif(v_r.cancellation_policy, ''), p_default_cancel);
  IF FOUND THEN
    UPDATE brand_retailer_agreements SET superseded_at = now() WHERE id = v_prior.id;   -- the partial unique index allows one live row
  END IF;
  INSERT INTO brand_retailer_agreements (brand_id, retailer_id, signed_name, signed_email, signed_ip, signed_user_agent, demo_policy_snapshot, cancellation_policy_snapshot, policy_hash)
  VALUES (p_brand_id, p_retailer_id, left(btrim(p_signed_name), 200), lower(coalesce(p_signed_email, '')), p_signed_ip, p_user_agent, v_demo, v_cancel, v_hash)
  RETURNING id INTO v_new_id;
  IF v_prior.id IS NOT NULL THEN
    UPDATE brand_retailer_agreements SET superseded_by = v_new_id WHERE id = v_prior.id;
  END IF;
  RETURN jsonb_build_object('outcome', 'ok', 'agreement_id', v_new_id, 'policy_hash', v_hash, 'superseded', v_prior.id);
END $function$

CREATE OR REPLACE FUNCTION public.apply_authorization_canceled(p_payment_intent text, p_target_status text DEFAULT 'expired'::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_att record; v_grp record; v_ids uuid[]; v_case uuid;
BEGIN
  IF p_payment_intent IS NULL THEN RAISE EXCEPTION 'payment_intent_required'; END IF;
  IF p_target_status NOT IN ('expired','declined','cancelled') THEN RAISE EXCEPTION 'invalid_target_status %', p_target_status; END IF;
  SELECT * INTO v_att FROM payment_attempts
    WHERE stripe_payment_intent_id = p_payment_intent ORDER BY created_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome','unknown_pi','payment_intent',p_payment_intent);
  END IF;
  SELECT * INTO v_grp FROM payment_groups WHERE id = v_att.payment_group_id FOR UPDATE;
  SELECT * INTO v_att FROM payment_attempts WHERE id = v_att.id FOR UPDATE;
  IF v_grp.status = 'auth_canceled' THEN
    SELECT array_agg(booking_id) INTO v_ids FROM payment_allocations WHERE payment_group_id = v_grp.id;
    RETURN jsonb_build_object('outcome','idempotent','payment_group_id',v_grp.id,'booking_ids',to_jsonb(v_ids));
  END IF;
  -- a canceled PI on a paid/refunded group would mean Stripe canceled a captured payment — impossible
  -- by API contract; record it rather than trusting either side.
  IF v_grp.status IN ('paid','partially_refunded','refunded') THEN
    v_case := _open_case('payment_contradiction','cancel-after-capture:'||p_payment_intent,'auth_canceled_on_paid_group',
                         v_grp.id,NULL,NULL,v_att.stripe_checkout_session_id,p_payment_intent,NULL,NULL,NULL,NULL,
                         jsonb_build_object('status',v_grp.status,'reason',p_reason));
    RETURN jsonb_build_object('outcome','contradiction','reason','auth_canceled_on_paid_group','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  IF v_grp.status <> 'authorized' THEN
    -- PI canceled before the auth ever applied (or a frozen group): terminalize the attempt only.
    UPDATE payment_attempts SET status = 'canceled', last_error = coalesce(p_reason,'pi_canceled_pre_auth') WHERE id = v_att.id AND status IN ('open','authorized');
    RETURN jsonb_build_object('outcome','attempt_canceled','payment_group_id',v_grp.id,'group_status',v_grp.status);
  END IF;
  UPDATE payment_groups SET status = 'auth_canceled' WHERE id = v_grp.id;
  UPDATE payment_attempts SET status = 'canceled', last_error = coalesce(p_reason, last_error) WHERE id = v_att.id;
  -- release: authorized -> unpaid, and ONLY a still-held booking takes the target status
  UPDATE bookings b SET payment_status = 'unpaid',
      status = CASE WHEN b.status = 'held' THEN p_target_status ELSE b.status END
    FROM payment_allocations a
    WHERE a.payment_group_id = v_grp.id AND b.id = a.booking_id AND b.payment_status = 'authorized';
  SELECT array_agg(booking_id) INTO v_ids FROM payment_allocations WHERE payment_group_id = v_grp.id;
  RETURN jsonb_build_object('outcome','applied','payment_group_id',v_grp.id,'booking_ids',to_jsonb(v_ids),'target_status',p_target_status);
END $function$

CREATE OR REPLACE FUNCTION public.apply_payment_success(p_payment_intent_id text, p_charge_id text, p_amount integer, p_currency text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_grp record; v_alloc_count int; v_flippable int;
BEGIN
  SELECT * INTO v_grp FROM payment_groups WHERE stripe_payment_intent_id = p_payment_intent_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'no_group_for_pi %', p_payment_intent_id; END IF;
  -- idempotent replay of an already-paid group (only if charge id is null-or-same)
  IF v_grp.status = 'paid' THEN
    IF p_charge_id IS NOT NULL AND v_grp.stripe_charge_id IS NOT NULL AND v_grp.stripe_charge_id <> p_charge_id THEN RAISE EXCEPTION 'charge_mismatch'; END IF;
    RETURN 0;
  END IF;
  IF v_grp.status NOT IN ('pending','session_created') THEN RAISE EXCEPTION 'group_not_payable %', v_grp.status; END IF;  -- reject refunded/frozen/failed
  IF p_amount IS NOT NULL AND p_amount <> v_grp.total_customer_amount THEN RAISE EXCEPTION 'amount_mismatch % <> %', p_amount, v_grp.total_customer_amount; END IF;
  IF p_currency IS NOT NULL AND lower(p_currency) <> lower(v_grp.currency) THEN RAISE EXCEPTION 'currency_mismatch'; END IF;
  SELECT count(*) INTO v_alloc_count FROM payment_allocations WHERE payment_group_id = v_grp.id;
  SELECT count(*) INTO v_flippable FROM bookings b JOIN payment_allocations a ON a.booking_id = b.id
    WHERE a.payment_group_id = v_grp.id AND b.payment_status = 'unpaid' AND b.status = 'pending_payment';
  IF v_flippable <> v_alloc_count THEN
    UPDATE payment_groups SET status = 'frozen' WHERE id = v_grp.id;   -- captured but not fully applicable -> freeze + reconcile
    RETURN -1;
  END IF;
  UPDATE bookings b SET payment_status = 'paid', payment_intent_id = p_payment_intent_id, paid_at = now()
    FROM payment_allocations a WHERE a.payment_group_id = v_grp.id AND b.id = a.booking_id;
  UPDATE payment_groups SET status = 'paid', stripe_charge_id = coalesce(p_charge_id, stripe_charge_id) WHERE id = v_grp.id;
  RETURN v_alloc_count;
END $function$

CREATE OR REPLACE FUNCTION public.apply_refund_event(p_refund_id text, p_status text, p_amount integer, p_currency text, p_pi text, p_charge text, p_meta_request_id uuid, p_event_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_req record; v_alloc record; v_all boolean; v_case uuid; v_status text; v_found boolean := false; v_gate text;
BEGIN
  IF p_refund_id IS NULL OR p_amount IS NULL OR p_currency IS NULL OR p_pi IS NULL OR p_charge IS NULL THEN
    v_case := _open_case('payment_contradiction','refund-missing-fields:'||coalesce(p_refund_id,p_event_id,'unknown'),
                         'refund_event_missing_required_fields', NULL, NULL, NULL, NULL, p_pi, p_charge, p_refund_id,
                         p_amount, p_currency, jsonb_build_object('event_id',p_event_id));
    RETURN jsonb_build_object('outcome','contradiction','reason','missing_required_fields','case_id',v_case);
  END IF;
  v_status := lower(coalesce(p_status,''));
  IF v_status NOT IN ('succeeded','failed','canceled','pending','requires_action') THEN
    v_case := _open_case('payment_contradiction','refund-bad-status:'||p_refund_id, 'unrecognized_refund_status',
                         NULL, NULL, NULL, NULL, p_pi, p_charge, p_refund_id, p_amount, p_currency,
                         jsonb_build_object('status',p_status));
    RETURN jsonb_build_object('outcome','contradiction','reason','unrecognized_status','case_id',v_case);
  END IF;
  IF p_meta_request_id IS NOT NULL THEN
    SELECT * INTO v_req FROM refund_requests WHERE id = p_meta_request_id FOR UPDATE; v_found := FOUND;
  END IF;
  IF NOT v_found THEN
    SELECT * INTO v_req FROM refund_requests WHERE stripe_refund_id = p_refund_id FOR UPDATE; v_found := FOUND;
  END IF;
  IF NOT v_found THEN RETURN jsonb_build_object('outcome','unmatched'); END IF;
  SELECT a.*, g.stripe_payment_intent_id AS pi, g.stripe_charge_id AS charge_id, g.id AS gid
    INTO v_alloc FROM payment_allocations a JOIN payment_groups g ON g.id = a.payment_group_id
    WHERE a.id = v_req.payment_allocation_id FOR UPDATE;
  IF v_alloc.pi IS NULL OR p_pi <> v_alloc.pi THEN
    v_case := _open_case('payment_contradiction','refund-pi:'||p_refund_id,'refund_pi_mismatch', v_alloc.gid, v_req.id, v_req.parent_operation_id,
                         NULL, p_pi, p_charge, p_refund_id, p_amount, p_currency,
                         jsonb_build_object('event_pi',p_pi,'group_pi',v_alloc.pi));
    RETURN jsonb_build_object('outcome','contradiction','reason','pi_mismatch','case_id',v_case);
  END IF;
  IF v_alloc.charge_id IS NULL OR p_charge <> v_alloc.charge_id THEN
    v_case := _open_case('payment_contradiction','refund-charge:'||p_refund_id,'refund_charge_mismatch', v_alloc.gid, v_req.id, v_req.parent_operation_id,
                         NULL, p_pi, p_charge, p_refund_id, p_amount, p_currency, NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','charge_mismatch','case_id',v_case);
  END IF;
  IF p_amount <> v_req.amount THEN
    v_case := _open_case('payment_contradiction','refund-amount:'||p_refund_id,'refund_amount_mismatch', v_alloc.gid, v_req.id, v_req.parent_operation_id,
                         NULL, p_pi, p_charge, p_refund_id, p_amount, p_currency,
                         jsonb_build_object('expected',v_req.amount,'got',p_amount));
    RETURN jsonb_build_object('outcome','contradiction','reason','amount_mismatch','case_id',v_case);
  END IF;
  IF lower(p_currency) <> lower(v_req.currency) THEN
    v_case := _open_case('payment_contradiction','refund-currency:'||p_refund_id,'refund_currency_mismatch', v_alloc.gid, v_req.id, v_req.parent_operation_id,
                         NULL, p_pi, p_charge, p_refund_id, p_amount, p_currency, NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','currency_mismatch','case_id',v_case);
  END IF;
  IF v_req.stripe_refund_id IS NOT NULL AND v_req.stripe_refund_id <> p_refund_id THEN
    v_case := _open_case('payment_contradiction','refund-id-disagree:'||p_refund_id,'refund_id_disagreement', v_alloc.gid, v_req.id, v_req.parent_operation_id,
                         NULL, p_pi, p_charge, p_refund_id, p_amount, p_currency, NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','refund_id_disagreement','case_id',v_case);
  END IF;
  -- ---- terminal handling with correct out-of-order semantics ----
  IF v_req.status IN ('succeeded','failed_terminal','failed','canceled') THEN
    v_gate := _refund_terminal_gate(v_req.status, v_status);
    IF v_gate = 'noop' THEN RETURN jsonb_build_object('outcome','already_terminal'); END IF;
    v_case := _open_case('payment_contradiction','refund-terminal:'||p_refund_id,'terminal_contradiction', v_alloc.gid, v_req.id, v_req.parent_operation_id,
                         NULL, p_pi, p_charge, p_refund_id, p_amount, p_currency,
                         jsonb_build_object('was',v_req.status,'got',v_status));
    RETURN jsonb_build_object('outcome','contradiction','reason','terminal_contradiction','case_id',v_case);
  END IF;
  IF v_req.stripe_refund_id IS NULL THEN
    UPDATE refund_requests SET stripe_refund_id = p_refund_id WHERE id = v_req.id;
  END IF;
  IF v_status IN ('succeeded','failed','canceled') AND v_alloc.reserved_refund_amount < v_req.amount THEN
    v_case := _open_case('payment_contradiction','refund-underflow:'||p_refund_id,'reservation_underflow', v_alloc.gid, v_req.id, v_req.parent_operation_id,
                         NULL, p_pi, p_charge, p_refund_id, p_amount, p_currency,
                         jsonb_build_object('reserved',v_alloc.reserved_refund_amount,'needed',v_req.amount));
    RETURN jsonb_build_object('outcome','contradiction','reason','reservation_underflow','case_id',v_case);
  END IF;
  IF v_status = 'succeeded' THEN
    UPDATE payment_allocations SET reserved_refund_amount = reserved_refund_amount - v_req.amount,
                                   refunded_amount = refunded_amount + v_req.amount WHERE id = v_alloc.id;
    UPDATE refund_requests SET status = 'succeeded', customer_refund_status = 'succeeded' WHERE id = v_req.id;
    UPDATE refund_operations SET status = 'succeeded' WHERE id = v_req.parent_operation_id;
    UPDATE bookings SET payment_status = CASE WHEN (v_alloc.refunded_amount + v_req.amount) >= v_alloc.customer_amount THEN 'refunded' ELSE 'partial_refund' END,
                        refund_id = p_refund_id, refunded_at = now() WHERE id = v_req.booking_id;
  ELSIF v_status IN ('failed','canceled') THEN
    UPDATE payment_allocations SET reserved_refund_amount = reserved_refund_amount - v_req.amount WHERE id = v_alloc.id;
    UPDATE refund_requests SET status = 'failed_terminal', customer_refund_status = v_status WHERE id = v_req.id;
    UPDATE refund_operations SET status = 'failed' WHERE id = v_req.parent_operation_id;
    v_case := _open_case('failed_refund','refund-failed:'||p_refund_id,'stripe_refund_'||v_status, v_alloc.gid, v_req.id, v_req.parent_operation_id,
                         NULL, p_pi, p_charge, p_refund_id, v_req.amount, v_req.currency, NULL);
    RETURN jsonb_build_object('outcome','failed','request_id',v_req.id,'case_id',v_case);
  ELSE
    UPDATE refund_requests SET status = CASE WHEN v_status = 'requires_action' THEN 'requires_action' ELSE 'pending' END,
                               customer_refund_status = v_status WHERE id = v_req.id;
    RETURN jsonb_build_object('outcome','pending_persisted','status',v_status);
  END IF;
  SELECT bool_and(refunded_amount >= customer_amount) INTO v_all FROM payment_allocations WHERE payment_group_id = v_alloc.gid;
  UPDATE payment_groups SET status = CASE WHEN v_all THEN 'refunded'
      WHEN EXISTS (SELECT 1 FROM payment_allocations WHERE payment_group_id = v_alloc.gid AND refunded_amount > 0) THEN 'partially_refunded'
      ELSE status END
    WHERE id = v_alloc.gid AND status IN ('paid','partially_refunded');
  RETURN jsonb_build_object('outcome','applied','request_id',v_req.id,'status',v_status);
END $function$

CREATE OR REPLACE FUNCTION public.apply_verified_authorization(p_session_id text, p_payment_intent text, p_charge text, p_amount integer, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_att record; v_grp record; v_alloc_count int; v_flippable int; v_sum int; v_ids uuid[]; v_case uuid;
BEGIN
  IF p_session_id IS NULL THEN RAISE EXCEPTION 'session_required'; END IF;
  IF p_payment_intent IS NULL OR p_amount IS NULL OR p_currency IS NULL THEN
    v_case := _open_case('payment_contradiction','auth-missing:'||p_session_id,'missing_pi_amount_or_currency',
                         NULL,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','missing_required_fields','case_id',v_case);
  END IF;
  SELECT * INTO v_att FROM payment_attempts WHERE stripe_checkout_session_id = p_session_id;
  IF NOT FOUND THEN
    v_case := _open_case('unknown_session','unknown-session:'||p_session_id,'authorized_session_not_bound_to_any_attempt',
                         NULL,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','unknown_session','session_id',p_session_id,'case_id',v_case);
  END IF;
  SELECT * INTO v_grp FROM payment_groups WHERE id = v_att.payment_group_id FOR UPDATE;
  SELECT * INTO v_att FROM payment_attempts WHERE id = v_att.id FOR UPDATE;
  IF p_amount <> v_grp.total_customer_amount THEN
    v_case := _open_case('payment_contradiction','auth-amount:'||p_session_id,'amount_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('expected',v_grp.total_customer_amount,'got',p_amount));
    RETURN jsonb_build_object('outcome','contradiction','reason','amount_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  IF lower(p_currency) <> lower(v_grp.currency) THEN
    v_case := _open_case('payment_contradiction','auth-currency:'||p_session_id,'currency_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','currency_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  IF NOT v_grp.platform_keeps_all THEN
    v_case := _open_case('payment_contradiction','auth-connected:'||p_session_id,'connected_auth_not_in_pilot',
                         v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','connected_not_in_pilot','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  IF v_grp.stripe_payment_intent_id IS NOT NULL AND v_grp.stripe_payment_intent_id <> p_payment_intent THEN
    v_case := _open_case('payment_contradiction','auth-pi-mismatch:'||p_session_id,'pi_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','pi_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  -- idempotent replay: the auth (or anything after it) already applied with matching identity
  IF v_grp.status IN ('authorized','paid','partially_refunded','refunded','auth_canceled') THEN
    SELECT array_agg(booking_id) INTO v_ids FROM payment_allocations WHERE payment_group_id = v_grp.id;
    RETURN jsonb_build_object('outcome','idempotent','payment_group_id',v_grp.id,'group_status',v_grp.status,'booking_ids',to_jsonb(v_ids));
  END IF;
  IF v_grp.status = 'frozen' THEN
    RETURN jsonb_build_object('outcome','frozen','payment_group_id',v_grp.id,'applied_count',0);
  END IF;
  IF v_grp.status NOT IN ('pending','session_created','failed') THEN
    v_case := _open_case('payment_contradiction','auth-status:'||p_session_id,'group_not_authorizable',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('status',v_grp.status));
    RETURN jsonb_build_object('outcome','contradiction','reason','group_not_authorizable','status',v_grp.status,'payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  IF v_att.status <> 'open' THEN
    v_case := _open_case('payment_contradiction','auth-attempt:'||p_session_id,'attempt_not_open',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('attempt_status',v_att.status));
    RETURN jsonb_build_object('outcome','contradiction','reason','attempt_not_open','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  SELECT count(*), coalesce(sum(customer_amount),0) INTO v_alloc_count, v_sum FROM payment_allocations WHERE payment_group_id = v_grp.id;
  IF v_alloc_count = 0 OR v_sum <> v_grp.total_customer_amount THEN
    UPDATE payment_groups SET status = 'frozen' WHERE id = v_grp.id;
    v_case := _open_case('frozen_payment','auth-sum:'||p_session_id,'allocation_sum_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('alloc_count',v_alloc_count,'alloc_sum',v_sum,'group_total',v_grp.total_customer_amount));
    RETURN jsonb_build_object('outcome','frozen','reason','allocation_sum_mismatch','payment_group_id',v_grp.id,'applied_count',0,'case_id',v_case);
  END IF;
  -- every booking must be a held, unpaid provisional — an auth landing on a normal cart is a
  -- contradiction (checkout only sets capture_method=manual for held bookings)
  SELECT count(*) INTO v_flippable FROM bookings b JOIN payment_allocations a ON a.booking_id = b.id
    WHERE a.payment_group_id = v_grp.id AND b.payment_status = 'unpaid' AND b.status = 'held';
  IF v_flippable <> v_alloc_count THEN
    UPDATE payment_groups SET status = 'frozen',
           stripe_payment_intent_id = coalesce(stripe_payment_intent_id, p_payment_intent),
           stripe_charge_id = coalesce(stripe_charge_id, p_charge) WHERE id = v_grp.id;
    UPDATE payment_attempts SET status = 'failed', last_error = 'group_frozen_auth_on_non_held_bookings' WHERE id = v_att.id;
    v_case := _open_case('frozen_payment','auth-frozen:'||p_session_id,'authorized_but_not_all_bookings_held',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('alloc_count',v_alloc_count,'flippable',v_flippable));
    RETURN jsonb_build_object('outcome','frozen','payment_group_id',v_grp.id,'applied_count',0,'case_id',v_case);
  END IF;
  UPDATE payment_groups SET status = 'authorized',
      stripe_checkout_session_id = coalesce(stripe_checkout_session_id, p_session_id),
      stripe_payment_intent_id  = coalesce(stripe_payment_intent_id,  p_payment_intent),
      stripe_charge_id          = coalesce(stripe_charge_id,          p_charge)
    WHERE id = v_grp.id;
  UPDATE payment_attempts SET status = 'authorized', stripe_payment_intent_id = coalesce(stripe_payment_intent_id, p_payment_intent)
    WHERE id = v_att.id;
  -- the 24h clock (re)starts at AUTH time — held_expires_at set at booking creation was only
  -- covering the never-checked-out case. payment_status 'authorized' = funds held, $0 charged.
  UPDATE bookings b SET payment_status = 'authorized', payment_intent_id = p_payment_intent,
      held_expires_at = now() + interval '24 hours'
    FROM payment_allocations a WHERE a.payment_group_id = v_grp.id AND b.id = a.booking_id;
  -- durable 'held' fulfilment: sends the hold-placed email (no demo). Re-uses the outbox so a
  -- crash between auth-apply and email can never lose the notification.
  INSERT INTO booking_fulfillments(booking_id, payment_group_id, target_status, status)
    SELECT a.booking_id, v_grp.id, 'held', 'pending'
      FROM payment_allocations a WHERE a.payment_group_id = v_grp.id
    ON CONFLICT (booking_id) DO NOTHING;
  SELECT array_agg(booking_id) INTO v_ids FROM payment_allocations WHERE payment_group_id = v_grp.id;
  RETURN jsonb_build_object('outcome','applied','payment_group_id',v_grp.id,'applied_count',v_alloc_count,
                            'booking_ids',to_jsonb(v_ids),'target_status','held');
END $function$

CREATE OR REPLACE FUNCTION public.apply_verified_payment(p_session_id text, p_payment_intent text, p_charge text, p_amount integer, p_currency text, p_connect_dest text, p_on_behalf_of text, p_application_fee integer, p_transfer_id text, p_fee_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_att record; v_grp record; v_alloc_count int; v_flippable int; v_sum int; v_ids uuid[]; v_case uuid; v_auto boolean; v_fee_sum int;
BEGIN
  IF p_session_id IS NULL THEN RAISE EXCEPTION 'session_required'; END IF;
  IF p_payment_intent IS NULL OR p_charge IS NULL OR p_amount IS NULL OR p_currency IS NULL THEN
    v_case := _open_case('payment_contradiction','pi-missing:'||p_session_id,'missing_pi_charge_amount_or_currency',
                         NULL,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','missing_required_fields','case_id',v_case);
  END IF;
  SELECT * INTO v_att FROM payment_attempts WHERE stripe_checkout_session_id = p_session_id;
  IF NOT FOUND THEN
    v_case := _open_case('unknown_session','unknown-session:'||p_session_id,'paid_session_not_bound_to_any_attempt',
                         NULL,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','unknown_session','session_id',p_session_id,'case_id',v_case);
  END IF;
  SELECT * INTO v_grp FROM payment_groups WHERE id = v_att.payment_group_id FOR UPDATE;
  SELECT * INTO v_att FROM payment_attempts WHERE id = v_att.id FOR UPDATE;
  IF p_amount <> v_grp.total_customer_amount THEN
    v_case := _open_case('payment_contradiction','amount:'||p_session_id,'amount_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('expected',v_grp.total_customer_amount,'got',p_amount));
    RETURN jsonb_build_object('outcome','contradiction','reason','amount_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  IF lower(p_currency) <> lower(v_grp.currency) THEN
    v_case := _open_case('payment_contradiction','currency:'||p_session_id,'currency_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','currency_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  IF v_grp.platform_keeps_all THEN
    -- keeps-all: NO Connect field may be present (0036 P0-3 #9, unchanged)
    IF p_connect_dest IS NOT NULL OR p_on_behalf_of IS NOT NULL OR p_application_fee IS NOT NULL
       OR p_transfer_id IS NOT NULL OR p_fee_id IS NOT NULL THEN
      v_case := _open_case('payment_contradiction','connect-on-keepsall:'||p_session_id,'unexpected_connect_fields_on_keeps_all',
                           v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                           jsonb_build_object('dest',p_connect_dest,'obo',p_on_behalf_of,'fee',p_application_fee,'transfer',p_transfer_id,'fee_id',p_fee_id));
      RETURN jsonb_build_object('outcome','contradiction','reason','unexpected_connect_fields','payment_group_id',v_grp.id,'case_id',v_case);
    END IF;
  ELSE
    -- 0116: connected. The money routing Stripe reports must equal the immutable snapshot taken at claim time:
    -- the destination and the settlement merchant are the store's connected account, and the application fee is
    -- exactly the sum of the platform fee legs. The transfer id and application fee id are NOT required here:
    -- Stripe fills charge.transfer and charge.application_fee a moment after capture (rehearsed 2026-10-30: the
    -- checkout.session.completed retrieval can see them still empty), so they are recorded when present, write-once,
    -- and a later replay that carries them fills them in (the idempotent branch below).
    SELECT coalesce(sum(platform_fee_amount),0) INTO v_fee_sum FROM payment_allocations WHERE payment_group_id = v_grp.id;
    IF coalesce(v_grp.connect_account_id,'') = ''
       OR coalesce(p_connect_dest,'') <> v_grp.connect_account_id
       OR coalesce(p_on_behalf_of,'') <> v_grp.connect_account_id
       -- 0118 (Codex round 4, small correction 1): a destination charge created with no application fee carries no
       -- application_fee_amount at all; that is a zero fee, and it must equal the allocations' zero fee sum.
       OR coalesce(p_application_fee,0) <> v_fee_sum THEN
      v_case := _open_case('payment_contradiction','connect-routing:'||p_session_id,'connect_routing_mismatch',
                           v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                           jsonb_build_object('dest',p_connect_dest,'obo',p_on_behalf_of,'app_fee',p_application_fee,'transfer',p_transfer_id,'fee_id',p_fee_id,
                                              'expected_dest',v_grp.connect_account_id,'expected_fee',v_fee_sum));
      RETURN jsonb_build_object('outcome','contradiction','reason','connect_routing_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
    END IF;
  END IF;
  IF v_grp.stripe_payment_intent_id IS NOT NULL AND v_grp.stripe_payment_intent_id <> p_payment_intent THEN
    v_case := _open_case('payment_contradiction','pi-mismatch:'||p_session_id,'pi_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','pi_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  -- [0065] an authorized group may already carry the UNCAPTURED charge id from auth time; capture re-delivers the
  -- same charge id, so equality holds.
  IF v_grp.stripe_charge_id IS NOT NULL AND v_grp.stripe_charge_id <> p_charge THEN
    v_case := _open_case('payment_contradiction','charge-mismatch:'||p_session_id,'charge_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,NULL);
    RETURN jsonb_build_object('outcome','contradiction','reason','charge_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  -- 0116: the settlement identifiers are write-once as well
  IF v_grp.stripe_transfer_id IS NOT NULL AND p_transfer_id IS NOT NULL AND v_grp.stripe_transfer_id <> p_transfer_id THEN
    v_case := _open_case('payment_contradiction','transfer-mismatch:'||p_session_id,'transfer_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('recorded',v_grp.stripe_transfer_id,'got',p_transfer_id));
    RETURN jsonb_build_object('outcome','contradiction','reason','transfer_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  -- 0117 (Codex CC-3): the application fee id is write-once too, symmetric with the transfer id
  IF v_grp.stripe_application_fee_id IS NOT NULL AND p_fee_id IS NOT NULL AND v_grp.stripe_application_fee_id <> p_fee_id THEN
    v_case := _open_case('payment_contradiction','fee-mismatch:'||p_session_id,'application_fee_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('recorded',v_grp.stripe_application_fee_id,'got',p_fee_id));
    RETURN jsonb_build_object('outcome','contradiction','reason','application_fee_mismatch','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  IF v_grp.status IN ('paid','partially_refunded','refunded') THEN
    -- 0116: a replay of a connected payment that now carries the settlement ids fills them in, write-once (the
    -- routing above already matched the snapshot; a different transfer id was refused above).
    IF NOT v_grp.platform_keeps_all AND (v_grp.stripe_transfer_id IS NULL OR v_grp.stripe_application_fee_id IS NULL) THEN
      UPDATE payment_groups SET stripe_transfer_id = coalesce(stripe_transfer_id, p_transfer_id),
                                stripe_application_fee_id = coalesce(stripe_application_fee_id, p_fee_id) WHERE id = v_grp.id;
    END IF;
    SELECT array_agg(booking_id) INTO v_ids FROM payment_allocations WHERE payment_group_id = v_grp.id;
    RETURN jsonb_build_object('outcome','idempotent','payment_group_id',v_grp.id,'group_status',v_grp.status,'booking_ids',to_jsonb(v_ids));
  END IF;
  IF v_grp.status = 'frozen' THEN
    RETURN jsonb_build_object('outcome','frozen','payment_group_id',v_grp.id,'applied_count',0);
  END IF;
  -- [0065] (a) 'authorized' joins the payable set: capture is the second half of a manual-capture payment
  IF v_grp.status NOT IN ('pending','session_created','failed','authorized') THEN
    v_case := _open_case('payment_contradiction','status:'||p_session_id,'group_not_payable',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('status',v_grp.status));
    RETURN jsonb_build_object('outcome','contradiction','reason','group_not_payable','status',v_grp.status,'payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  -- [0065] (c) an 'authorized' attempt is the expected pre-capture state
  IF v_att.status NOT IN ('open','authorized') THEN
    v_case := _open_case('payment_contradiction','attempt-not-open:'||p_session_id,'attempt_not_open',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('attempt_status',v_att.status));
    RETURN jsonb_build_object('outcome','contradiction','reason','attempt_not_open','payment_group_id',v_grp.id,'case_id',v_case);
  END IF;
  SELECT count(*), coalesce(sum(customer_amount),0) INTO v_alloc_count, v_sum FROM payment_allocations WHERE payment_group_id = v_grp.id;
  IF v_alloc_count = 0 OR v_sum <> v_grp.total_customer_amount THEN
    UPDATE payment_groups SET status = 'frozen' WHERE id = v_grp.id;
    v_case := _open_case('frozen_payment','sum:'||p_session_id,'allocation_sum_mismatch',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('alloc_count',v_alloc_count,'alloc_sum',v_sum,'group_total',v_grp.total_customer_amount));
    RETURN jsonb_build_object('outcome','frozen','reason','allocation_sum_mismatch','payment_group_id',v_grp.id,'applied_count',0,'case_id',v_case);
  END IF;
  -- [0065] (b) flippable = normal unpaid checkout OR a held authorization being captured
  SELECT count(*) INTO v_flippable FROM bookings b JOIN payment_allocations a ON a.booking_id = b.id
    WHERE a.payment_group_id = v_grp.id
      AND ((b.payment_status = 'unpaid' AND b.status = 'pending_payment')
        OR (b.payment_status = 'authorized' AND b.status = 'held'));
  IF v_flippable <> v_alloc_count THEN
    UPDATE payment_groups SET status = 'frozen',
           stripe_payment_intent_id = coalesce(stripe_payment_intent_id, p_payment_intent),
           stripe_charge_id = coalesce(stripe_charge_id, p_charge) WHERE id = v_grp.id;
    UPDATE payment_attempts SET status = 'failed', last_error = 'group_frozen_incomplete_apply' WHERE id = v_att.id;
    v_case := _open_case('frozen_payment','frozen:'||p_session_id,'captured_but_not_all_bookings_applyable',v_grp.id,NULL,NULL,p_session_id,p_payment_intent,p_charge,NULL,p_amount,p_currency,
                         jsonb_build_object('alloc_count',v_alloc_count,'flippable',v_flippable));
    RETURN jsonb_build_object('outcome','frozen','payment_group_id',v_grp.id,'applied_count',0,'case_id',v_case);
  END IF;
  SELECT coalesce(r.auto_confirm_bookings,false) INTO v_auto FROM retailers r WHERE r.id = v_grp.retailer_id;
  UPDATE payment_groups SET status = 'paid',
      stripe_checkout_session_id = coalesce(stripe_checkout_session_id, p_session_id),
      stripe_payment_intent_id  = coalesce(stripe_payment_intent_id,  p_payment_intent),
      stripe_charge_id          = coalesce(stripe_charge_id,          p_charge),
      -- 0116: the settlement identifiers of a destination charge (NULL on a keeps-all group, refused above otherwise)
      stripe_transfer_id        = coalesce(stripe_transfer_id,        p_transfer_id),
      stripe_application_fee_id = coalesce(stripe_application_fee_id, p_fee_id)
    WHERE id = v_grp.id;
  UPDATE payment_attempts SET status = 'paid', stripe_payment_intent_id = coalesce(stripe_payment_intent_id, p_payment_intent), paid_at = now()
    WHERE id = v_att.id;
  UPDATE bookings b SET payment_status = 'paid', payment_intent_id = p_payment_intent, paid_at = now()
    FROM payment_allocations a WHERE a.payment_group_id = v_grp.id AND b.id = a.booking_id;
  -- [0065] (d) a captured hold re-opens its 'held' outbox row with the real target (demo+emails);
  -- finished non-held rows keep their DO NOTHING replay-idempotency. [0078] C1: generation fencing.
  INSERT INTO booking_fulfillments(booking_id, payment_group_id, target_status, status)
    SELECT a.booking_id, v_grp.id, CASE WHEN v_auto THEN 'confirmed' ELSE 'pending' END, 'pending'
      FROM payment_allocations a WHERE a.payment_group_id = v_grp.id
    ON CONFLICT (booking_id) DO UPDATE
      SET target_status = EXCLUDED.target_status, status = 'pending',
          demo_created = false, emails_sent = false, completed_at = NULL, last_error = NULL,
          generation = booking_fulfillments.generation + 1,
          lease_owner = NULL, lease_expires_at = NULL, attempts = 0
      WHERE booking_fulfillments.target_status = 'held';
  SELECT array_agg(booking_id) INTO v_ids FROM payment_allocations WHERE payment_group_id = v_grp.id;
  RETURN jsonb_build_object('outcome','applied','payment_group_id',v_grp.id,'applied_count',v_alloc_count,
                            'booking_ids',to_jsonb(v_ids),'target_status', CASE WHEN v_auto THEN 'confirmed' ELSE 'pending' END);
END $function$

CREATE OR REPLACE FUNCTION public.booker_accept(p_token_hash text, p_code_hash text, p_session_token text, p_terms_version text, p_terms_digest text DEFAULT NULL::text, p_session_days integer DEFAULT 30, p_max_attempts integer DEFAULT 6)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_i brand_booker_invites%ROWTYPE; v_m brand_members%ROWTYPE; v_exp timestamptz;
BEGIN
  IF coalesce(p_token_hash, '') = '' OR coalesce(p_code_hash, '') = '' OR coalesce(p_session_token, '') = '' THEN RETURN jsonb_build_object('outcome', 'invalid'); END IF;
  IF coalesce(btrim(p_terms_version), '') = '' THEN RETURN jsonb_build_object('outcome', 'terms_required'); END IF;
  SELECT member_id INTO v_i.member_id FROM brand_booker_invites WHERE token_hash = p_token_hash;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'invalid'); END IF;
  SELECT * INTO v_m FROM brand_members WHERE id = v_i.member_id FOR UPDATE;                       -- membership first
  SELECT * INTO v_i FROM brand_booker_invites WHERE token_hash = p_token_hash FOR UPDATE;          -- then the invitation
  IF v_i.used_at IS NOT NULL THEN RETURN jsonb_build_object('outcome', 'already_used'); END IF;
  IF v_i.superseded_at IS NOT NULL THEN RETURN jsonb_build_object('outcome', 'superseded'); END IF;
  IF v_i.expires_at <= now() THEN RETURN jsonb_build_object('outcome', 'expired'); END IF;
  IF v_m.role <> 'booker' OR v_m.brand_id <> v_i.brand_id OR lower(v_m.email) <> lower(v_i.email) THEN RETURN jsonb_build_object('outcome', 'invalid'); END IF;
  IF v_m.status = 'revoked' THEN RETURN jsonb_build_object('outcome', 'revoked'); END IF;
  IF v_m.status = 'accepted' THEN RETURN jsonb_build_object('outcome', 'already_accepted'); END IF;
  IF v_i.code_hash IS NULL OR v_i.code_expires_at IS NULL OR v_i.code_expires_at <= now() THEN RETURN jsonb_build_object('outcome', 'code_expired'); END IF;
  IF v_i.code_attempts >= p_max_attempts THEN
    UPDATE brand_booker_invites SET superseded_at = now() WHERE id = v_i.id;
    RETURN jsonb_build_object('outcome', 'too_many_attempts');
  END IF;
  IF v_i.code_hash <> p_code_hash THEN
    UPDATE brand_booker_invites SET code_attempts = code_attempts + 1 WHERE id = v_i.id;
    IF v_i.code_attempts + 1 >= p_max_attempts THEN UPDATE brand_booker_invites SET superseded_at = now() WHERE id = v_i.id; RETURN jsonb_build_object('outcome', 'too_many_attempts'); END IF;
    RETURN jsonb_build_object('outcome', 'invalid_code', 'attempts_left', p_max_attempts - (v_i.code_attempts + 1));
  END IF;
  UPDATE brand_booker_invites SET used_at = now() WHERE id = v_i.id;
  UPDATE brand_booker_invites SET superseded_at = now() WHERE member_id = v_m.id AND id <> v_i.id AND used_at IS NULL AND superseded_at IS NULL;
  UPDATE brand_members SET status = 'accepted', accepted_at = now(), terms_accepted_at = now(), terms_version = btrim(p_terms_version), terms_digest = nullif(btrim(coalesce(p_terms_digest, '')), '') WHERE id = v_m.id;
  v_exp := now() + make_interval(days => greatest(1, coalesce(p_session_days, 30)));
  INSERT INTO brand_account_sessions (brand_id, session_token, email, expires_at) VALUES (v_m.brand_id, p_session_token, lower(v_m.email), v_exp);
  RETURN jsonb_build_object('outcome', 'ok', 'brand_id', v_m.brand_id, 'member_id', v_m.id, 'expires_at', v_exp, 'terms_version', btrim(p_terms_version));
END $function$

CREATE OR REPLACE FUNCTION public.booker_invite_code_set(p_token_hash text, p_code_hash text, p_ttl_minutes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_i brand_booker_invites%ROWTYPE; v_m brand_members%ROWTYPE; v_brand record;
BEGIN
  SELECT member_id INTO v_i.member_id FROM brand_booker_invites WHERE token_hash = p_token_hash;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'invalid'); END IF;
  SELECT * INTO v_m FROM brand_members WHERE id = v_i.member_id FOR UPDATE;                       -- membership first
  SELECT * INTO v_i FROM brand_booker_invites WHERE token_hash = p_token_hash FOR UPDATE;          -- then the invitation
  IF v_i.used_at IS NOT NULL THEN RETURN jsonb_build_object('outcome', 'already_used'); END IF;
  IF v_i.superseded_at IS NOT NULL THEN RETURN jsonb_build_object('outcome', 'superseded'); END IF;
  IF v_i.expires_at <= now() THEN RETURN jsonb_build_object('outcome', 'expired'); END IF;
  IF v_m.role <> 'booker' OR v_m.status <> 'pending' OR v_m.brand_id <> v_i.brand_id THEN RETURN jsonb_build_object('outcome', 'invalid'); END IF;
  UPDATE brand_booker_invites SET code_hash = p_code_hash, code_expires_at = now() + make_interval(mins => greatest(5, coalesce(p_ttl_minutes, 30))), code_attempts = 0 WHERE id = v_i.id;
  SELECT company_name INTO v_brand FROM brands WHERE id = v_i.brand_id;
  RETURN jsonb_build_object('outcome', 'ok', 'brand_name', v_brand.company_name, 'email', v_i.email, 'booker_name', v_m.name);
END $function$

CREATE OR REPLACE FUNCTION public.booker_invite_issue(p_member_id uuid, p_brand_id uuid, p_token_hash text, p_ttl_hours integer, p_by_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_m brand_members%ROWTYPE; v_id uuid; v_exp timestamptz;
BEGIN
  SELECT * INTO v_m FROM brand_members WHERE id = p_member_id AND brand_id = p_brand_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'not_found'); END IF;
  IF v_m.role <> 'booker' THEN RETURN jsonb_build_object('outcome', 'not_a_booker'); END IF;
  IF v_m.status <> 'pending' THEN RETURN jsonb_build_object('outcome', 'not_pending', 'status', v_m.status); END IF;
  UPDATE brand_booker_invites SET superseded_at = now() WHERE member_id = v_m.id AND used_at IS NULL AND superseded_at IS NULL;
  v_exp := now() + make_interval(hours => greatest(1, coalesce(p_ttl_hours, 24)));
  INSERT INTO brand_booker_invites (member_id, brand_id, email, token_hash, expires_at, created_by_email)
  VALUES (v_m.id, v_m.brand_id, v_m.email, p_token_hash, v_exp, lower(btrim(p_by_email))) RETURNING id INTO v_id;
  RETURN jsonb_build_object('outcome', 'ok', 'invite_id', v_id, 'email', v_m.email, 'expires_at', v_exp);
END $function$

CREATE OR REPLACE FUNCTION public.booker_revoke(p_brand_id uuid, p_member_id uuid, p_by_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_m brand_members%ROWTYPE; n int;
BEGIN
  SELECT * INTO v_m FROM brand_members WHERE id = p_member_id AND brand_id = p_brand_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'not_found'); END IF;
  IF v_m.role <> 'booker' THEN RETURN jsonb_build_object('outcome', 'not_a_booker'); END IF;
  IF v_m.status = 'revoked' THEN RETURN jsonb_build_object('outcome', 'already_revoked'); END IF;
  UPDATE brand_members SET status = 'revoked', revoked_at = now(), revoked_by_email = lower(btrim(p_by_email)) WHERE id = v_m.id;
  UPDATE brand_booker_invites SET superseded_at = now() WHERE member_id = v_m.id AND used_at IS NULL AND superseded_at IS NULL;
  DELETE FROM brand_account_sessions WHERE brand_id = p_brand_id AND lower(email) = lower(v_m.email);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN jsonb_build_object('outcome', 'ok', 'sessions_ended', n);
END $function$

CREATE OR REPLACE FUNCTION public.booking_cancellation_claim(p_booking_id uuid, p_retailer_id uuid, p_decision text, p_operator text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_bk record; v_dec public.booking_cancellations%ROWTYPE; v_res public.booking_cancellation_resolutions%ROWTYPE; v_case uuid;
BEGIN
  IF p_decision NOT IN ('refund_granted', 'no_refund') THEN RETURN jsonb_build_object('outcome', 'invalid_decision'); END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RETURN jsonb_build_object('outcome', 'reason_required'); END IF;
  SELECT id, retailer_id, status, payment_status INTO v_bk FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'no_booking'); END IF;
  IF v_bk.retailer_id IS DISTINCT FROM p_retailer_id THEN RETURN jsonb_build_object('outcome', 'forbidden'); END IF;
  SELECT * INTO v_res FROM public.booking_cancellation_resolutions WHERE booking_id = p_booking_id;
  IF FOUND THEN RETURN jsonb_build_object('outcome', 'existing', 'existing', true, 'resolution', to_jsonb(v_res)); END IF;
  IF v_bk.status NOT IN ('cancelled', 'declined') THEN RETURN jsonb_build_object('outcome', 'not_cancelled', 'status', v_bk.status); END IF;
  SELECT * INTO v_dec FROM public.booking_cancellations WHERE booking_id = p_booking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'no_decision'); END IF;
  IF v_dec.refund = true THEN RETURN jsonb_build_object('outcome', 'already_refunding', 'decision', to_jsonb(v_dec)); END IF;
  IF v_dec.status = 'not_paid' AND v_bk.payment_status IS DISTINCT FROM 'paid' THEN RETURN jsonb_build_object('outcome', 'nothing_to_refund', 'decision', to_jsonb(v_dec)); END IF;
  SELECT id INTO v_case FROM public.reconciliation_cases WHERE dedupe_key = 'refund-eligibility:' || p_booking_id::text LIMIT 1;
  INSERT INTO public.booking_cancellation_resolutions (booking_id, retailer_id, decision, operator, reason, case_id, state, notice_key, attempts, updated_at)
  VALUES (p_booking_id, p_retailer_id, p_decision, p_operator, left(btrim(p_reason), 500), v_case, 'claimed', 'cancellation-resolution:' || p_booking_id::text || ':' || p_decision, 0, now())
  RETURNING * INTO v_res;
  RETURN jsonb_build_object('outcome', 'claimed', 'existing', false, 'resolution', to_jsonb(v_res), 'decision', to_jsonb(v_dec));
END $function$

CREATE OR REPLACE FUNCTION public.booking_cancellation_progress(p_booking_id uuid, p_retailer_id uuid, p_mark text, p_refund_request_id uuid DEFAULT NULL::uuid, p_error text DEFAULT NULL::text, p_case_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_bk record; v_res public.booking_cancellation_resolutions%ROWTYPE; v_rq record; v_grp_retailer uuid; v_closed integer := 0; v_event uuid; v_dec record;
BEGIN
  SELECT id, retailer_id, brand_id INTO v_bk FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'no_booking'); END IF;
  IF v_bk.retailer_id IS DISTINCT FROM p_retailer_id THEN RETURN jsonb_build_object('outcome', 'forbidden'); END IF;
  SELECT * INTO v_res FROM public.booking_cancellation_resolutions WHERE booking_id = p_booking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'no_resolution'); END IF;
  IF p_mark IN ('refund_submitted', 'refund_pending') THEN
    IF v_res.decision <> 'refund_granted' THEN RETURN jsonb_build_object('outcome', 'not_a_grant', 'resolution', to_jsonb(v_res)); END IF;
    IF p_refund_request_id IS NULL THEN RETURN jsonb_build_object('outcome', 'refund_request_required'); END IF;
    SELECT rq.id, rq.booking_id, rq.payment_allocation_id, rq.status INTO v_rq FROM public.refund_requests rq WHERE rq.id = p_refund_request_id;
    IF NOT FOUND OR v_rq.booking_id IS DISTINCT FROM p_booking_id THEN RETURN jsonb_build_object('outcome', 'refund_request_mismatch'); END IF;
    SELECT g.retailer_id INTO v_grp_retailer FROM public.payment_allocations a JOIN public.payment_groups g ON g.id = a.payment_group_id WHERE a.id = v_rq.payment_allocation_id;
    IF v_grp_retailer IS DISTINCT FROM p_retailer_id THEN RETURN jsonb_build_object('outcome', 'refund_request_mismatch'); END IF;
    IF v_res.refund_request_id IS NOT NULL AND v_res.refund_request_id <> p_refund_request_id THEN RETURN jsonb_build_object('outcome', 'refund_request_mismatch', 'resolution', to_jsonb(v_res)); END IF;
    IF v_rq.status IN ('requires_review', 'failed', 'failed_terminal', 'canceled', 'superseded') THEN
      RETURN jsonb_build_object('outcome', 'refund_request_terminal', 'request_status', v_rq.status, 'resolution', to_jsonb(v_res));
    END IF;
    IF p_mark = 'refund_submitted' AND v_rq.status NOT IN ('submitted', 'pending', 'succeeded') THEN
      RETURN jsonb_build_object('outcome', 'refund_request_not_submitted', 'request_status', v_rq.status, 'resolution', to_jsonb(v_res));
    END IF;
    UPDATE public.booking_cancellation_resolutions
       SET refund_request_id = p_refund_request_id,
           refund_submitted_at = CASE WHEN p_mark = 'refund_submitted' THEN coalesce(refund_submitted_at, now()) ELSE refund_submitted_at END,
           state = CASE WHEN state = 'completed' THEN state ELSE p_mark END, last_error = NULL, updated_at = now()
     WHERE booking_id = p_booking_id RETURNING * INTO v_res;
  ELSIF p_mark = 'case_closed' THEN
    UPDATE public.reconciliation_cases SET status = 'resolved', resolved_by = coalesce(v_res.operator, 'refund-review'), resolved_at = now()
     WHERE dedupe_key = 'refund-eligibility:' || p_booking_id::text AND status <> 'resolved';
    GET DIAGNOSTICS v_closed = ROW_COUNT;
    UPDATE public.booking_cancellation_resolutions SET case_closed_at = coalesce(case_closed_at, now()), updated_at = now(), last_error = NULL WHERE booking_id = p_booking_id RETURNING * INTO v_res;
  ELSIF p_mark = 'brand_notified' THEN
    SELECT * INTO v_dec FROM public.booking_cancellations WHERE booking_id = p_booking_id;
    INSERT INTO public.notification_events (retailer_id, booking_id, brand_id, kind, transition_id, payload)
    VALUES (v_bk.retailer_id, p_booking_id, v_bk.brand_id, 'refund_resolution', p_booking_id::text || ':resolution',
            jsonb_build_object('decision', v_res.decision, 'reason', v_res.reason, 'operator', v_res.operator, 'resolved_at', v_res.resolved_at,
                               'refund_request_id', v_res.refund_request_id, 'refund_submitted_at', v_res.refund_submitted_at,
                               'initial_status', v_dec.status, 'initial_reason', v_dec.reason, 'category', v_dec.category))
    ON CONFLICT (kind, transition_id) DO NOTHING;
    SELECT id INTO v_event FROM public.notification_events WHERE kind = 'refund_resolution' AND transition_id = p_booking_id::text || ':resolution';
    UPDATE public.booking_cancellation_resolutions SET brand_notified_at = coalesce(brand_notified_at, now()), notice_event_id = coalesce(notice_event_id, v_event), updated_at = now(), last_error = NULL WHERE booking_id = p_booking_id RETURNING * INTO v_res;
  ELSIF p_mark = 'escalated' THEN
    IF p_case_id IS NULL THEN RETURN jsonb_build_object('outcome', 'case_required'); END IF;
    IF p_refund_request_id IS NOT NULL AND v_res.refund_request_id IS DISTINCT FROM p_refund_request_id THEN
      RETURN jsonb_build_object('outcome', 'stale_escalation', 'resolution', to_jsonb(v_res));
    END IF;
    UPDATE public.booking_cancellation_resolutions SET escalated_at = now(), escalation_cleared_at = NULL, escalated_case_id = p_case_id, state = CASE WHEN state = 'completed' THEN state ELSE 'failed' END, last_error = coalesce(left(p_error, 300), last_error), updated_at = now()
     WHERE booking_id = p_booking_id RETURNING * INTO v_res;
    RETURN jsonb_build_object('outcome', 'marked', 'resolution', to_jsonb(v_res));
  ELSIF p_mark = 'failed' THEN
    UPDATE public.booking_cancellation_resolutions SET state = CASE WHEN state = 'completed' THEN state ELSE 'failed' END, attempts = attempts + 1, last_error = left(p_error, 300), updated_at = now()
     WHERE booking_id = p_booking_id RETURNING * INTO v_res;
    RETURN jsonb_build_object('outcome', 'marked', 'resolution', to_jsonb(v_res));
  ELSIF p_mark = 'finalize' THEN
    NULL;   -- nothing but the shared completion rule below
  ELSE
    RETURN jsonb_build_object('outcome', 'invalid_mark');
  END IF;
  v_res := public._cancellation_resolution_finalize(p_booking_id);
  RETURN jsonb_build_object('outcome', 'marked', 'cases_closed', v_closed, 'resolution', to_jsonb(v_res));
END $function$

CREATE OR REPLACE FUNCTION public.booking_cancellation_record(p_booking_id uuid, p_retailer_id uuid, p_decision jsonb, p_expect jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_bk public.bookings%ROWTYPE; v_rt record; v_row public.booking_cancellations%ROWTYPE; v_now timestamptz; v_current jsonb;
BEGIN
  SELECT * INTO v_bk FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'no_booking'); END IF;
  IF v_bk.retailer_id IS DISTINCT FROM p_retailer_id THEN RETURN jsonb_build_object('outcome', 'forbidden'); END IF;
  v_now := clock_timestamp();
  SELECT * INTO v_row FROM public.booking_cancellations WHERE booking_id = p_booking_id;
  IF FOUND THEN
    -- a retry continues the recorded operation; the barrier is (re)asserted while the booking is still active
    IF v_bk.status IN ('pending', 'confirmed', 'held') AND v_bk.cancellation_pending_at IS NULL THEN
      UPDATE public.bookings SET cancellation_pending_at = v_now WHERE id = p_booking_id;
    END IF;
    RETURN jsonb_build_object('outcome', 'existing', 'existing', true, 'decision', to_jsonb(v_row));
  END IF;
  IF v_bk.status NOT IN ('pending', 'confirmed', 'held') THEN
    RETURN jsonb_build_object('outcome', 'state_conflict', 'status', v_bk.status);
  END IF;
  SELECT cancellation_mode, timezone INTO v_rt FROM public.retailers WHERE id = p_retailer_id;
  v_current := jsonb_build_object(
    'schedule_revision', v_bk.schedule_revision, 'demo_date', v_bk.demo_date, 'demo_time', v_bk.demo_time,
    'payment_status', v_bk.payment_status, 'fee_waived', coalesce(v_bk.fee_waived, false),
    'cancellation_mode', v_rt.cancellation_mode, 'timezone', v_rt.timezone, 'status', v_bk.status);
  -- the decision was computed from these inputs; if the row moved on, it is not recorded
  IF p_expect IS NOT NULL THEN
    IF (p_expect ? 'schedule_revision' AND (p_expect->>'schedule_revision')::integer IS DISTINCT FROM v_bk.schedule_revision)
       OR (p_expect ? 'demo_date' AND (p_expect->>'demo_date')::date IS DISTINCT FROM v_bk.demo_date)
       OR (p_expect ? 'demo_time' AND (p_expect->>'demo_time') IS DISTINCT FROM v_bk.demo_time)
       OR (p_expect ? 'payment_status' AND (p_expect->>'payment_status') IS DISTINCT FROM v_bk.payment_status)
       OR (p_expect ? 'fee_waived' AND (p_expect->>'fee_waived')::boolean IS DISTINCT FROM coalesce(v_bk.fee_waived, false))
       OR (p_expect ? 'cancellation_mode' AND (p_expect->>'cancellation_mode') IS DISTINCT FROM v_rt.cancellation_mode)
       OR (p_expect ? 'timezone' AND (p_expect->>'timezone') IS DISTINCT FROM v_rt.timezone) THEN
      RETURN jsonb_build_object('outcome', 'stale', 'current', v_current);
    END IF;
  END IF;
  INSERT INTO public.booking_cancellations (booking_id, retailer_id, category, requested_at, actor, cancellation_mode, cutoff_hours,
      start_at, start_source, hours_before_demo, refund, status, reason, force_refund, override_reason, backdate_note, note)
  VALUES (p_booking_id, p_retailer_id, p_decision->>'category', (p_decision->>'requested_at')::timestamptz, p_decision->>'actor',
      p_decision->>'cancellation_mode', (p_decision->>'cutoff_hours')::integer,
      NULLIF(p_decision->>'start_at', '')::timestamptz, p_decision->>'start_source', NULLIF(p_decision->>'hours_before_demo', '')::numeric,
      (p_decision->>'refund')::boolean, p_decision->>'status', p_decision->>'reason', coalesce((p_decision->>'force_refund')::boolean, false),
      p_decision->>'override_reason', p_decision->>'backdate_note', p_decision->>'note')
  RETURNING * INTO v_row;
  UPDATE public.bookings SET cancellation_pending_at = v_now WHERE id = p_booking_id;
  RETURN jsonb_build_object('outcome', 'recorded', 'existing', false, 'decision', to_jsonb(v_row), 'current', v_current);
END $function$

CREATE OR REPLACE FUNCTION public.booking_cancellation_relink(p_booking_id uuid, p_retailer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_bk record; v_res public.booking_cancellation_resolutions%ROWTYPE; v_old record; v_new record; v_grp_retailer uuid; v_submitted boolean;
BEGIN
  SELECT id, retailer_id INTO v_bk FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'no_booking'); END IF;
  IF v_bk.retailer_id IS DISTINCT FROM p_retailer_id THEN RETURN jsonb_build_object('outcome', 'forbidden'); END IF;
  SELECT * INTO v_res FROM public.booking_cancellation_resolutions WHERE booking_id = p_booking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'no_resolution'); END IF;
  IF v_res.decision <> 'refund_granted' OR v_res.refund_request_id IS NULL THEN RETURN jsonb_build_object('outcome', 'not_linked', 'resolution', to_jsonb(v_res)); END IF;
  IF v_res.state = 'completed' THEN RETURN jsonb_build_object('outcome', 'completed', 'resolution', to_jsonb(v_res)); END IF;
  SELECT rq.id, rq.status, rq.parent_operation_id, rq.payment_allocation_id, rq.booking_id, rq.attempt_version INTO v_old FROM public.refund_requests rq WHERE rq.id = v_res.refund_request_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'linked_request_missing'); END IF;
  IF v_old.status <> 'superseded' THEN RETURN jsonb_build_object('outcome', 'not_superseded', 'request_status', v_old.status, 'resolution', to_jsonb(v_res)); END IF;
  SELECT rq.id, rq.status, rq.attempt_version INTO v_new
    FROM public.refund_requests rq
   WHERE rq.parent_operation_id = v_old.parent_operation_id
     AND rq.booking_id = p_booking_id
     AND rq.payment_allocation_id = v_old.payment_allocation_id
     AND rq.attempt_version > v_old.attempt_version
     AND rq.status NOT IN ('superseded', 'canceled')
     AND EXISTS (SELECT 1 FROM public.refund_review_actions ra WHERE ra.refund_request_id = rq.id AND ra.action = 'replace' AND ra.retailer_id = p_retailer_id)
   ORDER BY rq.attempt_version DESC LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'no_successor', 'resolution', to_jsonb(v_res)); END IF;
  SELECT g.retailer_id INTO v_grp_retailer FROM public.payment_allocations a JOIN public.payment_groups g ON g.id = a.payment_group_id WHERE a.id = v_old.payment_allocation_id;
  IF v_grp_retailer IS DISTINCT FROM p_retailer_id THEN RETURN jsonb_build_object('outcome', 'forbidden'); END IF;
  v_submitted := v_new.status IN ('submitted', 'pending', 'succeeded');
  UPDATE public.booking_cancellation_resolutions
     SET refund_request_id = v_new.id,
         refund_submitted_at = CASE WHEN v_submitted THEN now() ELSE NULL END,
         state = CASE WHEN v_submitted THEN 'refund_submitted' ELSE 'refund_pending' END,
         escalation_cleared_at = CASE WHEN escalated_at IS NOT NULL THEN now() ELSE escalation_cleared_at END,
         attempts_baseline = attempts, recovery_generation = recovery_generation + 1,   -- R6-2: a validated replacement restores the budget
         last_error = NULL, updated_at = now()
   WHERE booking_id = p_booking_id RETURNING * INTO v_res;
  v_res := public._cancellation_resolution_finalize(p_booking_id);   -- R6-1: completes at once when nothing else is owed
  RETURN jsonb_build_object('outcome', 'relinked', 'previous_request_id', v_old.id, 'request_id', v_new.id, 'request_status', v_new.status, 'attempt_version', v_new.attempt_version, 'resolution', to_jsonb(v_res));
END $function$

CREATE OR REPLACE FUNCTION public.booking_code_attempt(p_brand_id uuid, p_retailer_id uuid, p_net_hash text)
 RETURNS TABLE(allowed boolean, retry_after_seconds integer, brand_attempts integer, net_attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_b int; v_n int; v_win interval := interval '15 minutes'; v_oldest_b timestamptz; v_oldest_n timestamptz; v_limiting timestamptz;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('booking_code_attempt:brand:' || coalesce(p_brand_id::text, '') || ':' || coalesce(p_retailer_id::text, '')));
  IF p_net_hash IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtext('booking_code_attempt:net:' || p_net_hash)); END IF;
  DELETE FROM booking_code_attempts WHERE at < now() - interval '1 day' AND random() < 0.05;
  SELECT count(*), min(at) INTO v_b, v_oldest_b FROM booking_code_attempts WHERE brand_id = p_brand_id AND retailer_id = p_retailer_id AND at >= now() - v_win;
  SELECT count(*), min(at) INTO v_n, v_oldest_n FROM booking_code_attempts WHERE p_net_hash IS NOT NULL AND net_hash = p_net_hash AND at >= now() - v_win;
  IF v_b >= 12 OR v_n >= 40 THEN
    v_limiting := CASE WHEN v_b >= 12 THEN v_oldest_b ELSE v_oldest_n END;
    RETURN QUERY SELECT false, greatest(30, extract(epoch FROM (coalesce(v_limiting, now()) + v_win - now()))::int), v_b, v_n; RETURN;
  END IF;
  INSERT INTO booking_code_attempts (brand_id, retailer_id, net_hash) VALUES (p_brand_id, p_retailer_id, p_net_hash);
  RETURN QUERY SELECT true, 0, v_b + 1, v_n + 1;
END $function$

CREATE OR REPLACE FUNCTION public.booking_code_check(p_code text, p_retailer_id uuid)
 RETURNS TABLE(ok boolean, reason text, code_id uuid, waives_fee boolean, waives_lead_time boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c booking_codes%ROWTYPE;
BEGIN
  SELECT * INTO v_c FROM booking_codes c WHERE c.code = upper(trim(coalesce(p_code, ''))) AND c.retailer_id = p_retailer_id;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'code_not_found'::text, NULL::uuid, false, false; RETURN; END IF;
  IF NOT v_c.active THEN RETURN QUERY SELECT false, 'code_inactive'::text, v_c.id, false, false; RETURN; END IF;
  IF v_c.expires_at IS NOT NULL AND v_c.expires_at <= now() THEN RETURN QUERY SELECT false, 'code_expired'::text, v_c.id, false, false; RETURN; END IF;
  IF v_c.max_uses IS NOT NULL AND v_c.use_count >= v_c.max_uses THEN RETURN QUERY SELECT false, 'code_used_up'::text, v_c.id, false, false; RETURN; END IF;
  RETURN QUERY SELECT true, NULL::text, v_c.id, v_c.waives_fee, v_c.waives_lead_time;
END $function$

CREATE OR REPLACE FUNCTION public.booking_code_redeem(p_code text, p_retailer_id uuid, p_booking_id uuid, p_brand_id uuid)
 RETURNS TABLE(ok boolean, reason text, code_id uuid, waived_fee boolean, waived_lead_time boolean, target_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c booking_codes%ROWTYPE; v_b bookings%ROWTYPE; v_auto boolean; v_target text;
BEGIN
  SELECT * INTO v_c FROM booking_codes c WHERE c.code = upper(trim(coalesce(p_code, ''))) AND c.retailer_id = p_retailer_id FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'code_not_found'::text, NULL::uuid, false, false, NULL::text; RETURN; END IF;
  IF NOT v_c.active THEN RETURN QUERY SELECT false, 'code_inactive'::text, v_c.id, false, false, NULL::text; RETURN; END IF;
  IF v_c.expires_at IS NOT NULL AND v_c.expires_at <= now() THEN RETURN QUERY SELECT false, 'code_expired'::text, v_c.id, false, false, NULL::text; RETURN; END IF;
  IF v_c.max_uses IS NOT NULL AND v_c.use_count >= v_c.max_uses THEN RETURN QUERY SELECT false, 'code_used_up'::text, v_c.id, false, false, NULL::text; RETURN; END IF;
  SELECT * INTO v_b FROM bookings b WHERE b.id = p_booking_id AND b.retailer_id = p_retailer_id FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'booking_not_found'::text, v_c.id, false, false, NULL::text; RETURN; END IF;
  IF v_b.brand_id IS DISTINCT FROM p_brand_id THEN RETURN QUERY SELECT false, 'booking_brand_mismatch'::text, v_c.id, false, false, NULL::text; RETURN; END IF;
  IF v_b.booking_code_id IS NOT NULL THEN RETURN QUERY SELECT false, 'booking_already_has_code'::text, v_c.id, false, false, NULL::text; RETURN; END IF;
  -- a fee waiver needs an unpaid pending_payment booking; a short-notice-only code may also stamp a provisional
  -- (held) booking, whose hold is captured or released exactly as before.
  -- Codex review 2 item 4: this release accepts codes only on an unpaid pending_payment booking. A provisional
  -- (held) booking takes no code: the short-notice + hold-deadline combination is not proven yet.
  IF coalesce(v_b.status, '') <> 'pending_payment' OR coalesce(v_b.payment_status, 'unpaid') <> 'unpaid' THEN
    RETURN QUERY SELECT false, 'booking_not_redeemable'::text, v_c.id, false, false, NULL::text; RETURN;
  END IF;
  IF EXISTS (SELECT 1 FROM payment_allocations a WHERE a.booking_id = p_booking_id) THEN
    RETURN QUERY SELECT false, 'booking_in_checkout'::text, v_c.id, false, false, NULL::text; RETURN;
  END IF;
  INSERT INTO booking_code_redemptions (code_id, booking_id, retailer_id, brand_id, brand_name, waived_fee, waived_lead_time)
    VALUES (v_c.id, p_booking_id, p_retailer_id, p_brand_id, v_b.brand_name, v_c.waives_fee, v_c.waives_lead_time);
  UPDATE booking_codes SET use_count = use_count + 1 WHERE id = v_c.id;
  IF v_c.waives_fee THEN
    SELECT coalesce(r.auto_confirm_bookings, false) INTO v_auto FROM retailers r WHERE r.id = p_retailer_id;
    v_target := CASE WHEN v_auto THEN 'confirmed' ELSE 'pending' END;
    UPDATE bookings SET booking_code_id = v_c.id, fee_waived = true, payment_status = 'waived', amount_paid = 0, paid_at = now()
      WHERE id = p_booking_id;
    -- The same outbox the paid path uses (0038/0065/0078), with no payment group: the worker promotes
    -- pending_payment -> target via booking_transition 'promote_paid' and sends the normal notices.
    INSERT INTO booking_fulfillments (booking_id, payment_group_id, target_status, status)
      VALUES (p_booking_id, NULL, v_target, 'pending')
      ON CONFLICT (booking_id) DO NOTHING;
  ELSE
    UPDATE bookings SET booking_code_id = v_c.id WHERE id = p_booking_id;
  END IF;
  RETURN QUERY SELECT true, NULL::text, v_c.id, v_c.waives_fee, v_c.waives_lead_time, v_target;
END $function$

CREATE OR REPLACE FUNCTION public.booking_create_as_member(p_op_key text, p_fingerprint text, p_member_id uuid, p_brand_id uuid, p_retailer_id uuid, p_item_ids text[], p_payload jsonb, p_default_demo text, p_default_cancel text, p_tos_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_op booking_operations%ROWTYPE; v_m brand_members%ROWTYPE; v_snap jsonb; v_b bookings%ROWTYPE; v_res jsonb;
BEGIN
  IF coalesce(p_op_key, '') = '' OR coalesce(p_fingerprint, '') = '' THEN RAISE EXCEPTION 'op_key_required' USING errcode = 'check_violation'; END IF;
  -- durable identity for this request (0085 pattern): insert, then lock. A concurrent twin waits here and replays.
  INSERT INTO booking_operations (op_key, brand_id, member_id, fingerprint) VALUES (p_op_key, p_brand_id, p_member_id, p_fingerprint) ON CONFLICT (op_key) DO NOTHING;
  SELECT * INTO v_op FROM booking_operations WHERE op_key = p_op_key FOR UPDATE;
  IF v_op.brand_id <> p_brand_id OR v_op.member_id IS DISTINCT FROM p_member_id OR v_op.fingerprint <> p_fingerprint THEN
    RAISE EXCEPTION 'op_key_reused' USING errcode = 'check_violation';
  END IF;
  IF v_op.result IS NOT NULL THEN RETURN v_op.result || jsonb_build_object('replay', true); END IF;
  v_m := _booker_authorize(p_member_id, p_brand_id, p_retailer_id, p_default_demo, p_default_cancel, p_tos_version);
  v_snap := _catalog_snapshot(p_brand_id, p_item_ids);
  INSERT INTO bookings (retailer_id, venue_id, brand_id, brand_name, contact_name, contact_email, contact_phone, demo_date, demo_time, duration_hours,
                        product, notes, product_skus, needs_electricity, status, held_expires_at, payment_status, amount_paid,
                        booked_by_member_id, booked_by_email, booked_by_name)
  VALUES (p_retailer_id, (p_payload->>'venue_id')::uuid, p_brand_id, p_payload->>'brand_name', p_payload->>'contact_name', p_payload->>'contact_email', p_payload->>'contact_phone',
          (p_payload->>'demo_date')::date, p_payload->>'demo_time', (p_payload->>'duration_hours')::numeric,
          p_payload->>'product', p_payload->>'notes', v_snap, (p_payload->>'needs_electricity')::boolean, p_payload->>'status',
          (p_payload->>'held_expires_at')::timestamptz, coalesce(p_payload->>'payment_status', 'unpaid'), coalesce((p_payload->>'amount_paid')::int, 0),
          v_m.id, v_m.email, coalesce(nullif(p_payload->>'booked_by_name', ''), v_m.name))
  RETURNING * INTO v_b;
  v_res := jsonb_build_object('ok', true, 'booking_id', v_b.id, 'status', v_b.status, 'items', jsonb_array_length(v_snap));
  UPDATE booking_operations SET booking_id = v_b.id, result = v_res WHERE op_key = p_op_key;
  RETURN v_res || jsonb_build_object('replay', false);
END $function$

CREATE OR REPLACE FUNCTION public.booking_create_with_code(p_op_key text, p_fingerprint text, p_brand_id uuid, p_retailer_id uuid, p_payload jsonb, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_op booking_operations%ROWTYPE; v_b bookings%ROWTYPE; v_r record; v_res jsonb; v_member uuid; v_m brand_members%ROWTYPE; v_items jsonb; v_ids text[];
BEGIN
  v_member := nullif(p_payload->>'booked_by_member_id', '')::uuid;
  INSERT INTO booking_operations (op_key, brand_id, member_id, fingerprint) VALUES (p_op_key, p_brand_id, v_member, p_fingerprint) ON CONFLICT (op_key) DO NOTHING;
  SELECT * INTO v_op FROM booking_operations WHERE op_key = p_op_key FOR UPDATE;
  IF v_op.brand_id <> p_brand_id OR v_op.fingerprint <> p_fingerprint OR (v_op.member_id IS NOT NULL AND v_op.member_id IS DISTINCT FROM v_member) THEN RAISE EXCEPTION 'op_key_reused' USING errcode = 'check_violation'; END IF;
  IF v_op.result IS NOT NULL THEN RETURN v_op.result || jsonb_build_object('replay', true); END IF;
  v_items := p_payload->'product_skus';
  IF v_member IS NOT NULL THEN
    v_m := _booker_authorize(v_member, p_brand_id, p_retailer_id, p_payload->>'default_demo_policy', p_payload->>'default_cancellation_policy', p_payload->>'tos_version');
    IF v_m.role = 'booker' THEN
      SELECT array_agg(x) INTO v_ids FROM jsonb_array_elements_text(coalesce(p_payload->'item_ids', '[]'::jsonb)) x;
      v_items := _catalog_snapshot(p_brand_id, v_ids);
    END IF;
  END IF;
  SELECT * INTO v_r FROM booking_code_check(p_code, p_retailer_id);
  IF NOT v_r.ok THEN RAISE EXCEPTION 'code_rejected:%', v_r.reason USING errcode = 'check_violation'; END IF;
  INSERT INTO bookings (retailer_id, venue_id, brand_id, brand_name, contact_name, contact_email, contact_phone, demo_date, demo_time, duration_hours,
                        product, notes, product_skus, needs_electricity, status, held_expires_at, payment_status, amount_paid,
                        booked_by_member_id, booked_by_email, booked_by_name)
  VALUES (p_retailer_id, (p_payload->>'venue_id')::uuid, p_brand_id, p_payload->>'brand_name', p_payload->>'contact_name', p_payload->>'contact_email', p_payload->>'contact_phone',
          (p_payload->>'demo_date')::date, p_payload->>'demo_time', (p_payload->>'duration_hours')::numeric,
          p_payload->>'product', p_payload->>'notes', v_items, (p_payload->>'needs_electricity')::boolean, p_payload->>'status',
          (p_payload->>'held_expires_at')::timestamptz, coalesce(p_payload->>'payment_status', 'unpaid'), coalesce((p_payload->>'amount_paid')::int, 0),
          v_member, nullif(p_payload->>'booked_by_email', ''), nullif(p_payload->>'booked_by_name', ''))
  RETURNING * INTO v_b;
  SELECT * INTO v_r FROM booking_code_redeem(p_code, p_retailer_id, v_b.id, p_brand_id);
  IF NOT v_r.ok THEN RAISE EXCEPTION 'code_rejected:%', v_r.reason USING errcode = 'check_violation'; END IF;
  v_res := jsonb_build_object('ok', true, 'booking_id', v_b.id, 'fee_waived', v_r.waived_fee, 'waived_lead_time', v_r.waived_lead_time, 'target_status', v_r.target_status, 'code_id', v_r.code_id);
  UPDATE booking_operations SET booking_id = v_b.id, result = v_res WHERE op_key = p_op_key;
  RETURN v_res || jsonb_build_object('replay', false);
END $function$

CREATE OR REPLACE FUNCTION public.booking_interval_ok(p_date date, p_time text, p_hours integer, p_tz text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE v_start timestamptz; v_end timestamptz; v_tz text := coalesce(nullif(btrim(p_tz), ''), 'America/Los_Angeles');
        v_off_start interval; v_off_end interval;
BEGIN
  v_start := booking_slot_start_strict(p_date, p_time, v_tz);
  IF v_start IS NULL THEN RETURN false; END IF;
  v_end := v_start + make_interval(hours => coalesce(p_hours, 3));
  v_off_start := (v_start AT TIME ZONE v_tz) - (v_start AT TIME ZONE 'UTC');
  v_off_end   := (v_end   AT TIME ZONE v_tz) - (v_end   AT TIME ZONE 'UTC');
  RETURN v_off_start = v_off_end;
END $function$

CREATE OR REPLACE FUNCTION public.booking_slot_resolve()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_av jsonb; v_min integer; v_ok boolean; v_reason text; v_hours integer; v_tz text;
  v_slot_changed boolean; v_reactivated boolean; v_msg text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    v_slot_changed := NEW.venue_id IS DISTINCT FROM OLD.venue_id
                   OR NEW.demo_date IS DISTINCT FROM OLD.demo_date
                   OR slot_key(NEW.demo_time) IS DISTINCT FROM slot_key(OLD.demo_time);
    v_reactivated  :=     coalesce(OLD.status,'pending')     IN ('cancelled','declined','expired','auth_canceled')
                   AND coalesce(NEW.status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled');
    IF NOT v_slot_changed AND NOT v_reactivated THEN RETURN NEW; END IF;
  END IF;
  IF coalesce(NEW.status, 'pending') IN ('cancelled', 'declined', 'expired', 'auth_canceled') THEN RETURN NEW; END IF;
  IF NEW.venue_id IS NULL THEN RETURN NEW; END IF;
  SELECT v.availability INTO v_av FROM venues v
   WHERE v.id = NEW.venue_id AND v.retailer_id = NEW.retailer_id
   FOR SHARE;
  IF NOT FOUND THEN RETURN NEW; END IF;
  BEGIN
    PERFORM venue_availability_validate(v_av);
  EXCEPTION WHEN check_violation THEN
    GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT;
    RAISE EXCEPTION 'slot_config_invalid: this location''s availability is misconfigured (%)', v_msg USING errcode = 'check_violation';
  END;
  v_min := slot_minutes(NEW.demo_time);
  IF v_min IS NULL THEN
    RAISE EXCEPTION 'slot_not_offered: "%" is not a time this location offers on %', coalesce(NEW.demo_time, ''), NEW.demo_date
      USING errcode = 'check_violation';
  END IF;
  SELECT o.ok, o.reason, o.hours INTO v_ok, v_reason, v_hours FROM venue_slot_offered(v_av, NEW.demo_date, v_min) o;
  IF NOT coalesce(v_ok, false) THEN
    RAISE EXCEPTION '%: % at % is not bookable at this location', v_reason, slot_label(v_min), NEW.demo_date
      USING errcode = 'check_violation';
  END IF;
  SELECT r.timezone INTO v_tz FROM retailers r WHERE r.id = NEW.retailer_id;
  IF booking_slot_start_strict(NEW.demo_date, slot_label(v_min), v_tz) IS NULL THEN
    RAISE EXCEPTION 'invalid_local_time: % on % does not exist exactly once in %', slot_label(v_min), NEW.demo_date, coalesce(nullif(btrim(v_tz), ''), 'America/Los_Angeles')
      USING errcode = 'check_violation';
  END IF;
  -- R6: the whole interval must sit on one side of any clock change.
  IF NOT booking_interval_ok(NEW.demo_date, slot_label(v_min), v_hours, v_tz) THEN
    RAISE EXCEPTION 'invalid_local_time: % + %h on % spans a daylight-saving change in %', slot_label(v_min), v_hours, NEW.demo_date, coalesce(nullif(btrim(v_tz), ''), 'America/Los_Angeles')
      USING errcode = 'check_violation';
  END IF;
  NEW.duration_hours := v_hours;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.booking_slot_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_tz text; v_hours integer;
BEGIN
  v_hours := NEW.duration_hours;
  IF v_hours IS NULL THEN
    SELECT d.duration_hours INTO v_hours FROM demos d WHERE d.booking_id = NEW.id LIMIT 1;
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.demo_date IS NOT DISTINCT FROM OLD.demo_date
     AND NEW.demo_time IS NOT DISTINCT FROM OLD.demo_time
     AND NEW.retailer_id IS NOT DISTINCT FROM OLD.retailer_id
     AND OLD.start_at IS NOT NULL THEN
    NEW.start_at  := OLD.start_at;
    NEW.timezone  := OLD.timezone;
    NEW.end_at    := OLD.start_at + make_interval(hours => coalesce(v_hours, 3));
    RETURN NEW;
  END IF;
  SELECT r.timezone INTO v_tz FROM retailers r WHERE r.id = NEW.retailer_id;
  NEW.timezone := coalesce(nullif(btrim(v_tz), ''), 'America/Los_Angeles');
  NEW.start_at := booking_slot_start(NEW.demo_date, NEW.demo_time, NEW.timezone, 11);
  IF NEW.start_at IS NULL THEN NEW.end_at := NULL;
  ELSE NEW.end_at := NEW.start_at + make_interval(hours => coalesce(v_hours, 3));
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.booking_slot_start(p_date date, p_time text, p_tz text, p_default_hour integer DEFAULT 11)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  m      text[];
  v_h    integer;
  v_min  integer;
  v_ampm text;
  v_tz   text := coalesce(nullif(btrim(p_tz), ''), 'America/Los_Angeles');
  v_wall timestamp;
BEGIN
  IF p_date IS NULL THEN RETURN NULL; END IF;
  m := regexp_match(coalesce(p_time, ''), '^\s*(\d{1,2})(?::(\d{2}))?\s*([AaPp]\.?[Mm]\.?)?\s*$');
  IF m IS NOT NULL THEN
    v_h    := m[1]::integer;
    v_min  := coalesce(m[2]::integer, 0);
    v_ampm := lower(replace(coalesce(m[3], ''), '.', ''));
    IF v_min > 59 THEN
      v_h := NULL;
    ELSIF v_ampm <> '' THEN
      IF v_h < 1 OR v_h > 12 THEN v_h := NULL;
      ELSIF v_ampm = 'pm' AND v_h <> 12 THEN v_h := v_h + 12;
      ELSIF v_ampm = 'am' AND v_h = 12 THEN v_h := 0;
      END IF;
    ELSIF v_h > 23 THEN
      v_h := NULL;
    END IF;
  END IF;
  IF v_h IS NULL THEN
    IF p_default_hour IS NULL THEN RETURN NULL; END IF;
    v_h := p_default_hour; v_min := 0;
  END IF;
  v_wall := p_date + make_time(v_h, v_min, 0);
  BEGIN
    RETURN v_wall AT TIME ZONE v_tz;
  EXCEPTION WHEN invalid_parameter_value OR invalid_datetime_format THEN
    RETURN v_wall AT TIME ZONE 'America/Los_Angeles';
  END;
END $function$

CREATE OR REPLACE FUNCTION public.booking_slot_start_strict(p_date date, p_time text, p_tz text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE v_min integer; v_wall timestamp; v_inst timestamptz; v_tz text := coalesce(nullif(btrim(p_tz), ''), 'America/Los_Angeles');
BEGIN
  IF p_date IS NULL THEN RETURN NULL; END IF;
  v_min := slot_minutes(p_time);
  IF v_min IS NULL THEN RETURN NULL; END IF;
  v_wall := p_date + make_time(v_min / 60, v_min % 60, 0);
  BEGIN
    v_inst := v_wall AT TIME ZONE v_tz;
  EXCEPTION WHEN invalid_parameter_value OR invalid_datetime_format THEN
    RETURN NULL;
  END;
  IF (v_inst AT TIME ZONE v_tz) <> v_wall THEN RETURN NULL; END IF;                      -- gap: the wall time does not exist
  IF ((v_inst - interval '1 hour') AT TIME ZONE v_tz) = v_wall
     OR ((v_inst + interval '1 hour') AT TIME ZONE v_tz) = v_wall THEN RETURN NULL; END IF;  -- fold: two instants share the wall time
  RETURN v_inst;
END $function$

CREATE OR REPLACE FUNCTION public.booking_transition(p_booking_id uuid, p_retailer_id uuid, p_action text, p_fields jsonb DEFAULT '{}'::jsonb, p_demo_fee numeric DEFAULT NULL::numeric)
 RETURNS TABLE(ok boolean, reason text, status_before text, status_after text, demo_id uuid, demo_created boolean, demo_reactivated boolean, demos_cancelled integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_b bookings%ROWTYPE; v_d demos%ROWTYPE; v_target text; v_from text[]; v_cur text; v_fee numeric;
  v_demo_id uuid; v_created boolean := false; v_react boolean := false; v_cancelled integer := 0; v_found boolean;
BEGIN
  IF p_booking_id IS NULL OR p_retailer_id IS NULL THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::text, NULL::text, NULL::uuid, false, false, 0; RETURN;
  END IF;
  -- 1. Booking first (the same lock order as accept_reschedule), then its projection.
  SELECT * INTO v_b FROM bookings b WHERE b.id = p_booking_id AND b.retailer_id = p_retailer_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::text, NULL::text, NULL::uuid, false, false, 0; RETURN;
  END IF;
  v_cur := coalesce(v_b.status, 'pending');
  -- 0106 (Codex refund-cutoff R2-3): a recorded cancellation decision is a barrier until the cancellation lands.
  -- No confirmation, capture promotion or projection step may run on top of it; only the cancel itself.
  IF v_b.cancellation_pending_at IS NOT NULL AND p_action <> 'cancel' THEN
    RETURN QUERY SELECT false, 'cancellation_pending'::text, v_cur, v_cur, NULL::uuid, false, false, 0; RETURN;
  END IF;
  -- 2. Allowed transitions per action, judged on the CURRENT persisted state.
  -- [0078] C2: the action's own terminal target is an ALLOWED current state , a provider-side step
  -- (an authorization release, a capture-side auto-confirm, a concurrent identical request) may have
  -- applied it already. The call then converges: audited fields are applied, the projection is
  -- ensured/retired idempotently, and reason = 'already_applied' (ok = true). Any OTHER state is
  -- still 'state_changed' (ok = false): confirm-vs-cancel and cancel-vs-confirm conflicts keep 409.
  IF p_action = 'confirm' THEN        v_from := ARRAY['pending', 'held', 'confirmed'];              v_target := 'confirmed';
  ELSIF p_action = 'decline' THEN     v_from := ARRAY['pending', 'held', 'declined'];               v_target := 'declined';
  ELSIF p_action = 'cancel' THEN      v_from := ARRAY['pending', 'confirmed', 'held', 'cancelled']; v_target := 'cancelled';
  ELSIF p_action = 'promote_paid' THEN
    v_target := p_fields->>'status';
    IF v_target IS NULL OR v_target NOT IN ('confirmed', 'pending') THEN
      RAISE EXCEPTION 'invalid_target: promote_paid needs status confirmed|pending' USING errcode = 'check_violation';
    END IF;
    v_from := ARRAY['pending_payment', 'held', v_target];   -- the target itself = idempotent retry
    -- [0078] C3: a booking that was legitimately advanced past the job's target (manual confirmation
    -- of a paid pending booking) is 'already_advanced' , not a conflict, never a downgrade. The
    -- caller finishes or supersedes its remaining notification work against the CURRENT state.
    IF v_target = 'pending' AND v_cur = 'confirmed' THEN
      SELECT d.id INTO v_demo_id FROM demos d WHERE d.booking_id = p_booking_id AND coalesce(d.status, '') IN ('confirmed', 'scheduled', 'completed') ORDER BY d.created_at LIMIT 1;
      RETURN QUERY SELECT false, 'already_advanced'::text, v_cur, v_cur, v_demo_id, false, false, 0;
      RETURN;
    END IF;
  ELSIF p_action = 'materialize' THEN v_from := ARRAY['confirmed'];                    v_target := 'confirmed';
  ELSE
    RAISE EXCEPTION 'invalid_action: %', p_action USING errcode = 'check_violation';
  END IF;
  IF NOT (v_cur = ANY (v_from)) THEN
    RETURN QUERY SELECT false,
      CASE WHEN v_cur IN ('cancelled', 'declined', 'expired', 'auth_canceled') AND p_action IN ('promote_paid', 'materialize') THEN 'superseded' ELSE 'state_changed' END,
      v_cur, v_cur, NULL::uuid, false, false, 0;
    RETURN;
  END IF;
  -- 3. The booking transition (+ the caller's audited fields). UPDATE OF status fires the offering
  --    re-check only for inactive -> active (none of these), never for active -> active.
  IF v_cur <> v_target OR p_fields <> '{}'::jsonb THEN
    UPDATE bookings SET
      status            = v_target,
      cancelled_at      = CASE WHEN p_fields ? 'cancelled_at'      THEN (p_fields->>'cancelled_at')::timestamptz ELSE cancelled_at END,
      cancel_reason     = CASE WHEN p_fields ? 'cancel_reason'     THEN p_fields->>'cancel_reason'                ELSE cancel_reason END,
      refund_id         = CASE WHEN p_fields ? 'refund_id'         THEN p_fields->>'refund_id'                    ELSE refund_id END,
      payment_status    = CASE WHEN p_fields ? 'payment_status'    THEN p_fields->>'payment_status'               ELSE payment_status END,
      payment_intent_id = CASE WHEN p_fields ? 'payment_intent_id' THEN p_fields->>'payment_intent_id'            ELSE payment_intent_id END,
      paid_at           = CASE WHEN p_fields ? 'paid_at'           THEN (p_fields->>'paid_at')::timestamptz       ELSE paid_at END,
      cancellation_pending_at = CASE WHEN p_action = 'cancel' THEN NULL ELSE cancellation_pending_at END   -- 0106: the barrier lifts with the cancellation
    WHERE id = p_booking_id
    RETURNING * INTO v_b;
  END IF;
  -- 4. The projection, under the same lock. At most one demo per booking (demos_one_per_booking).
  SELECT * INTO v_d FROM demos d WHERE d.booking_id = p_booking_id ORDER BY d.created_at LIMIT 1 FOR UPDATE;
  v_found := FOUND;
  IF v_target = 'confirmed' THEN
    IF v_b.demo_date IS NULL THEN
      RAISE EXCEPTION 'booking_has_no_date: % cannot be projected onto the calendar', p_booking_id USING errcode = 'check_violation';
    END IF;
    v_fee := p_demo_fee;
    IF v_fee IS NULL THEN SELECT x.demo_fee INTO v_fee FROM venues x WHERE x.id = v_b.venue_id; END IF;
    IF v_found AND coalesce(v_d.status, '') IN ('confirmed', 'scheduled', 'completed') THEN
      v_demo_id := v_d.id;
    ELSIF v_found THEN
      -- a retired projection for a booking that is confirmed again: bring it back on the current schedule
      UPDATE demos SET status = 'confirmed', confirmed_at = now(),
             venue_id = v_b.venue_id, demo_date = v_b.demo_date, demo_time = v_b.demo_time,
             duration_hours = coalesce(v_b.duration_hours, demos.duration_hours, 3),
             demo_fee = coalesce(v_fee, demos.demo_fee)
       WHERE id = v_d.id;
      v_demo_id := v_d.id; v_react := true;
    ELSE
      INSERT INTO demos (retailer_id, venue_id, brand_id, company_name, contact_name, contact_email, contact_phone, product, product_skus,
                         demo_date, demo_time, duration_hours, status, confirmed_at, demo_fee, notes, booking_id)
      VALUES (v_b.retailer_id, v_b.venue_id, v_b.brand_id, coalesce(nullif(btrim(v_b.brand_name), ''), 'Unknown'), v_b.contact_name, v_b.contact_email, v_b.contact_phone,
              v_b.product, CASE WHEN jsonb_typeof(v_b.product_skus) = 'array' AND jsonb_array_length(v_b.product_skus) > 0 THEN v_b.product_skus ELSE NULL END,
              v_b.demo_date, v_b.demo_time, coalesce(v_b.duration_hours, 3), 'confirmed', now(), v_fee, v_b.notes, v_b.id)
      RETURNING id INTO v_demo_id;
      v_created := true;
    END IF;
  ELSIF v_target IN ('cancelled', 'declined') THEN
    UPDATE demos SET status = 'cancelled'
     WHERE booking_id = p_booking_id AND coalesce(status, '') IN ('confirmed', 'scheduled');
    GET DIAGNOSTICS v_cancelled = ROW_COUNT;
    IF v_found THEN v_demo_id := v_d.id; END IF;
  ELSE
    IF v_found THEN v_demo_id := v_d.id; END IF;
  END IF;
  RETURN QUERY SELECT true, CASE WHEN v_cur = v_target AND p_action IN ('confirm', 'decline', 'cancel') THEN 'already_applied'::text ELSE NULL::text END,
                      v_cur, v_target, v_demo_id, v_created, v_react, v_cancelled;
END $function$

CREATE OR REPLACE FUNCTION public.brand_members_owner_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.email := lower(btrim(NEW.email));
  IF NEW.role = 'owner' THEN
    NEW.status := 'accepted';
    IF NEW.accepted_at IS NULL THEN NEW.accepted_at := now(); END IF;
  ELSIF NEW.role = 'booker' AND NEW.status IN ('pending','accepted') THEN
    IF EXISTS (SELECT 1 FROM brands b WHERE lower(b.email) = NEW.email) THEN
      RAISE EXCEPTION 'email_in_use: % owns a brand account' , NEW.email USING errcode = 'unique_violation';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.brands_products_version_bump()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.products is distinct from old.products then
    new.products_version := coalesce(old.products_version, 0) + 1;
  else
    new.products_version := coalesce(old.products_version, 0);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.checkout_claim_group(p_brand_id uuid, p_retailer_id uuid, p_booking_ids uuid[], p_platform_keeps_all boolean, p_connect_account_id text, p_platform_fee_cents integer, p_provisional boolean DEFAULT NULL::boolean)
 RETURNS TABLE(payment_group_id uuid, total_customer_amount integer, reused boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ids uuid[]; v_gid uuid; v_total int := 0; v_bid uuid; v_bk record; v_fee_row record;
  v_cust int; v_venue int; v_fee int; v_groups uuid[]; v_existing uuid; v_existing_set uuid[];
  v_g record; v_keeps boolean; v_connect text;
BEGIN
  IF array_length(p_booking_ids,1) IS NULL THEN RAISE EXCEPTION 'no bookings'; END IF;
  IF p_brand_id IS NULL OR p_retailer_id IS NULL THEN RAISE EXCEPTION 'brand_and_retailer_required'; END IF;
  v_keeps := coalesce(p_platform_keeps_all,false);
  v_connect := nullif(btrim(coalesce(p_connect_account_id,'')), '');
  -- 0116: a connected group must name the account the demo fee is routed to. The handler reads it off the retailer
  -- row and refuses a store that is not payout-ready, but the ledger does not trust the handler for this.
  IF NOT v_keeps AND v_connect IS NULL THEN RAISE EXCEPTION 'connect_account_required'; END IF;
  IF NOT v_keeps AND coalesce(p_platform_fee_cents,0) < 0 THEN RAISE EXCEPTION 'platform_fee_invalid'; END IF;
  IF v_keeps THEN v_connect := NULL; END IF;
  SELECT array_agg(x ORDER BY x) INTO v_ids FROM (SELECT DISTINCT unnest(p_booking_ids) x) d;
  IF array_length(v_ids,1) <> array_length(p_booking_ids,1) THEN RAISE EXCEPTION 'duplicate_booking_input'; END IF;
  -- 0118 (Codex R3-2): the handler decides the capture mode (manual authorization for ONE held booking, immediate charge
  -- otherwise) from the rows it read; that decision is asserted below, under the locks, against each booking's current
  -- state. NULL (a six-argument caller) means no assertion, the 0116 behaviour.
  IF p_provisional IS TRUE THEN
    IF NOT v_keeps THEN RAISE EXCEPTION 'connected_hold_unsupported'; END IF;
    IF array_length(v_ids,1) <> 1 THEN RAISE EXCEPTION 'provisional_checkout_single_only'; END IF;
  END IF;
  -- (a) Lock every requested booking in id order and validate it under its lock. This is the ONE validation both the
  --     reuse path and the new-group path go through; neither returns before it has completed for every booking.
  FOREACH v_bid IN ARRAY v_ids LOOP
    SELECT b.id, b.brand_id, b.retailer_id, b.status, b.payment_status
      INTO v_bk FROM bookings b WHERE b.id = v_bid FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'booking_set_mismatch %', v_bid; END IF;
    IF v_bk.brand_id IS NULL OR v_bk.brand_id <> p_brand_id THEN RAISE EXCEPTION 'not_your_booking %', v_bid; END IF;
    IF v_bk.retailer_id IS NULL OR v_bk.retailer_id <> p_retailer_id THEN RAISE EXCEPTION 'mixed_retailers'; END IF;
    -- payable means exactly this; "not held" is never read as "pending_payment and unpaid"
    IF v_bk.status NOT IN ('pending_payment','held') OR v_bk.payment_status <> 'unpaid' THEN RAISE EXCEPTION 'not_payable_state %', v_bid; END IF;
    IF p_provisional IS NOT NULL AND ((v_bk.status = 'held') <> p_provisional) THEN RAISE EXCEPTION 'capture_mode_stale %', v_bid; END IF;
  END LOOP;
  -- (b) Existing allocations, read under the booking locks (every allocation is inserted under these locks, so the
  --     read is authoritative), and the existing group's state re-read as part of the same protected decision.
  SELECT array_agg(DISTINCT a.payment_group_id) INTO v_groups FROM payment_allocations a WHERE a.booking_id = ANY(v_ids);
  IF v_groups IS NOT NULL THEN
    IF array_length(v_groups,1) <> 1 THEN RAISE EXCEPTION 'booking_in_another_group'; END IF;
    v_existing := v_groups[1];
    SELECT array_agg(pa.booking_id ORDER BY pa.booking_id) INTO v_existing_set
      FROM payment_allocations pa WHERE pa.payment_group_id = v_existing;
    SELECT g.* INTO v_g FROM payment_groups g WHERE g.id = v_existing;   -- read, not locked: see the lock-order note above
    IF v_existing_set = v_ids
       AND v_g.status IN ('pending','session_created')
       AND v_g.brand_id = p_brand_id
       AND v_g.retailer_id = p_retailer_id
       AND v_g.platform_keeps_all = v_keeps
       AND coalesce(v_g.connect_account_id,'') = coalesce(v_connect,'')
       AND lower(v_g.currency) = 'usd' THEN
      -- RETURN 1 of 2: idempotent reuse, after (a) for every booking and the group check just above
      RETURN QUERY SELECT v_g.id, v_g.total_customer_amount, true; RETURN;
    END IF;
    RAISE EXCEPTION 'booking_in_another_group';
  END IF;
  -- (c) No allocation for any requested booking: a new group with immutable allocations, under the same locks.
  INSERT INTO payment_groups(brand_id, retailer_id, total_customer_amount, platform_keeps_all, connect_account_id, status)
    VALUES (p_brand_id, p_retailer_id, 0, v_keeps, v_connect, 'pending')
    RETURNING id INTO v_gid;
  FOREACH v_bid IN ARRAY v_ids LOOP
    SELECT b.venue_id INTO v_bk FROM bookings b WHERE b.id = v_bid;   -- locked in (a)
    SELECT v.demo_fee INTO v_fee_row FROM venues v WHERE v.id = v_bk.venue_id;
    IF v_fee_row IS NULL OR v_fee_row.demo_fee IS NULL OR v_fee_row.demo_fee < 0 THEN RAISE EXCEPTION 'venue_missing_fee %', v_bid; END IF;
    v_venue := round(v_fee_row.demo_fee * 100)::int;
    v_fee   := CASE WHEN v_keeps THEN 0 ELSE coalesce(p_platform_fee_cents,0) END;
    v_cust  := v_venue + v_fee;
    v_total := v_total + v_cust;
    INSERT INTO payment_allocations(payment_group_id, booking_id, customer_amount, venue_amount, platform_fee_amount)
      VALUES (v_gid, v_bid, v_cust, v_venue, v_fee);
  END LOOP;
  UPDATE payment_groups SET total_customer_amount = v_total WHERE id = v_gid;
  -- RETURN 2 of 2: the new group, after (a) for every booking
  RETURN QUERY SELECT v_gid, v_total, false;
END $function$

CREATE OR REPLACE FUNCTION public.claim_move_settlement(p_move_id uuid, p_owner text, p_lease_seconds integer DEFAULT 180)
 RETURNS TABLE(ok boolean, reason text, move jsonb, booking jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_m booking_moves%ROWTYPE; v_b bookings%ROWTYPE;
BEGIN
  SELECT * INTO v_m FROM booking_moves m WHERE m.id = p_move_id;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found'::text, NULL::jsonb, NULL::jsonb; RETURN; END IF;
  SELECT * INTO v_b FROM bookings b WHERE b.id = v_m.booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'booking_missing'::text, to_jsonb(v_m), NULL::jsonb; RETURN; END IF;
  SELECT * INTO v_m FROM booking_moves m WHERE m.id = p_move_id FOR UPDATE;
  IF v_m.status NOT IN ('declined', 'lapsed') THEN RETURN QUERY SELECT false, ('move_' || v_m.status)::text, to_jsonb(v_m), to_jsonb(v_b); RETURN; END IF;
  IF v_m.settled_at IS NOT NULL THEN RETURN QUERY SELECT false, 'already_settled'::text, to_jsonb(v_m), to_jsonb(v_b); RETURN; END IF;
  IF v_b.retailer_id IS DISTINCT FROM v_m.retailer_id THEN RETURN QUERY SELECT false, 'tenant_mismatch'::text, to_jsonb(v_m), to_jsonb(v_b); RETURN; END IF;
  IF v_m.settle_lease_until IS NOT NULL AND v_m.settle_lease_until > now() AND v_m.settle_lease_owner IS DISTINCT FROM p_owner THEN
    RETURN QUERY SELECT false, 'lease_held'::text, to_jsonb(v_m), to_jsonb(v_b); RETURN;
  END IF;
  -- The booking must still be the schedule this move produced, or already inactive (a settlement that
  -- cancelled it and crashed before finalising). A different ACTIVE revision means a valid newer
  -- schedule landed; this move is retired and must never cancel it.
  IF coalesce(v_b.status, 'pending') IN ('pending', 'confirmed') AND v_b.schedule_revision IS DISTINCT FROM v_m.schedule_revision THEN
    UPDATE booking_moves SET status = 'superseded', settle_lease_owner = NULL, settle_lease_until = NULL, updated_at = now() WHERE id = p_move_id;
    UPDATE bookings SET pending_move_settlement = NULL WHERE id = v_b.id AND pending_move_settlement = p_move_id;
    RETURN QUERY SELECT false, 'revision_mismatch'::text, to_jsonb(v_m), to_jsonb(v_b); RETURN;
  END IF;
  IF coalesce(v_b.status, 'pending') IN ('pending', 'confirmed') AND v_b.pending_move_settlement IS DISTINCT FROM p_move_id THEN
    -- The booking was never marked for this settlement (an older row shape); mark it now so no schedule change lands.
    UPDATE bookings SET pending_move_settlement = p_move_id WHERE id = v_b.id AND pending_move_settlement IS NULL;
  END IF;
  UPDATE booking_moves
     SET settle_lease_owner = p_owner, settle_lease_until = now() + make_interval(secs => greatest(30, coalesce(p_lease_seconds, 180))), updated_at = now()
   WHERE id = p_move_id
  RETURNING * INTO v_m;
  SELECT * INTO v_b FROM bookings b WHERE b.id = v_m.booking_id;
  RETURN QUERY SELECT true, NULL::text, to_jsonb(v_m), to_jsonb(v_b);
END $function$

CREATE OR REPLACE FUNCTION public.claim_stripe_event(p_event_id text, p_event_type text, p_owner text, p_lease_seconds integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record;
BEGIN
  BEGIN
    INSERT INTO processed_stripe_events(event_id, event_type, status, lease_owner, lease_expires_at)
      VALUES (p_event_id, p_event_type, 'processing', p_owner, now() + make_interval(secs => p_lease_seconds));
    RETURN 'process';
  EXCEPTION WHEN unique_violation THEN NULL; END;
  SELECT * INTO v FROM processed_stripe_events WHERE event_id = p_event_id FOR UPDATE;
  IF v.status = 'completed' THEN RETURN 'skip'; END IF;
  IF v.lease_expires_at IS NULL OR v.lease_expires_at < now() THEN
    UPDATE processed_stripe_events
      SET status = 'processing', lease_owner = p_owner, lease_expires_at = now() + make_interval(secs => p_lease_seconds)
      WHERE event_id = p_event_id;
    RETURN 'process';
  END IF;
  RETURN 'busy';
END $function$

CREATE OR REPLACE FUNCTION public.create_refund_replacement(p_op_key text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_op record; v_alloc record; v_ver int; v_remaining int; v_rid uuid; v_key text; v_keeps boolean; v_fee int; v_live int; v_fee_prior int;
BEGIN
  SELECT * INTO v_op FROM refund_operations WHERE op_key = p_op_key FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_operation'); END IF;
  IF v_op.status NOT IN ('failed','requires_review') THEN RETURN jsonb_build_object('outcome','not_replaceable','status',v_op.status); END IF;
  SELECT count(*) INTO v_live FROM refund_requests
    WHERE parent_operation_id = v_op.id AND status IN ('reserved','submitted','pending','requires_action','failed_retryable');
  IF v_live > 0 THEN RETURN jsonb_build_object('outcome','live_request_exists','live',v_live); END IF;
  SELECT a.*, g.stripe_payment_intent_id AS pi, g.platform_keeps_all AS keeps, g.connect_account_id AS connect, g.currency AS gcur
    INTO v_alloc FROM payment_allocations a JOIN payment_groups g ON g.id = a.payment_group_id
    WHERE a.id = v_op.payment_allocation_id FOR UPDATE;
  v_keeps := v_alloc.keeps;
  v_remaining := v_alloc.customer_amount - v_alloc.refunded_amount - v_alloc.reserved_refund_amount;
  IF v_remaining <= 0 THEN RETURN jsonb_build_object('outcome','nothing_refundable'); END IF;
  -- 0117: cumulative fee entitlement (see refund_reserve_cas); the replaced attempt is terminal so it is excluded
  SELECT coalesce(sum(expected_fee_refund_amount),0) INTO v_fee_prior FROM refund_requests
    WHERE payment_allocation_id = v_alloc.id AND status NOT IN ('failed_terminal','failed','canceled');
  v_fee := greatest(0, round(v_alloc.platform_fee_amount::numeric * (v_alloc.refunded_amount + v_alloc.reserved_refund_amount + v_remaining) / v_alloc.customer_amount)::int - v_fee_prior);
  SELECT coalesce(max(attempt_version),1) + 1 INTO v_ver FROM refund_requests WHERE parent_operation_id = v_op.id;
  UPDATE payment_allocations SET reserved_refund_amount = reserved_refund_amount + v_remaining WHERE id = v_alloc.id;
  UPDATE refund_operations SET status = 'open' WHERE id = v_op.id;
  v_rid := gen_random_uuid(); v_key := 'rf-' || v_rid::text;
  INSERT INTO refund_requests(
      id, parent_operation_id, attempt_version, payment_allocation_id, booking_id, amount, currency,
      actor, reason, op_key, status, stripe_idempotency_key, next_attempt_at,
      expected_customer_amount, expected_transfer_reversal_amount, expected_fee_refund_amount,
      customer_refund_status, settlement_status, canonical_request_hash, request_schema_version,
      settlement_strategy, fee_refund_idempotency_key)
    VALUES (v_rid, v_op.id, v_ver, v_alloc.id, v_op.booking_id, v_remaining, v_alloc.gcur,
      p_actor, 'authorized_replacement', p_op_key, 'reserved', v_key, now(),
      v_remaining, CASE WHEN v_keeps THEN NULL ELSE v_remaining END, CASE WHEN v_keeps THEN NULL ELSE v_fee END,
      'pending', CASE WHEN v_keeps THEN 'not_required' ELSE 'pending' END,
      md5(coalesce(v_alloc.pi,'') || ':' || v_remaining || ':' || v_alloc.gcur || ':' || coalesce(v_alloc.connect,'keepsall')), 1,
      CASE WHEN v_keeps THEN 1 ELSE 2 END, CASE WHEN v_keeps THEN NULL ELSE 'fr-' || v_rid::text END);
  RETURN jsonb_build_object('outcome','replacement_created','refund_request_id',v_rid,'refund_operation_id',v_op.id,
    'attempt_version',v_ver,'idempotency_key',v_key,'payment_intent',v_alloc.pi,'keeps_all',v_keeps,'amount',v_remaining);
END $function$

CREATE OR REPLACE FUNCTION public.decline_reschedule(p_booking_id uuid, p_brand_id uuid, p_proposal_version integer)
 RETURNS TABLE(ok boolean, reason text, schedule_revision integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_b bookings%ROWTYPE;
  v_d demos%ROWTYPE;
BEGIN
  SELECT * INTO v_b FROM bookings b WHERE b.id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found'::text, NULL::integer; RETURN; END IF;
  SELECT * INTO v_d FROM demos d WHERE d.booking_id = p_booking_id ORDER BY d.created_at LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'no_demo'::text, v_b.schedule_revision; RETURN; END IF;
  IF p_brand_id IS NULL OR coalesce(v_b.brand_id, v_d.brand_id) IS DISTINCT FROM p_brand_id THEN
    RETURN QUERY SELECT false, 'forbidden'::text, v_b.schedule_revision; RETURN;
  END IF;
  IF v_d.reschedule_to_date IS NULL THEN RETURN QUERY SELECT false, 'no_proposal'::text, v_b.schedule_revision; RETURN; END IF;
  IF p_proposal_version IS NULL OR v_b.reschedule_proposal_version <> p_proposal_version THEN
    RETURN QUERY SELECT false, 'stale_proposal'::text, v_b.schedule_revision; RETURN;
  END IF;
  UPDATE demos
     SET reschedule_to_date = NULL, reschedule_to_time = NULL, reschedule_requested_at = NULL
   WHERE id = v_d.id;
  RETURN QUERY SELECT true, NULL::text, v_b.schedule_revision;
END $function$

CREATE OR REPLACE FUNCTION public.demos_copy_booked_by()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_b record;
BEGIN
  IF NEW.booking_id IS NOT NULL AND NEW.booked_by_member_id IS NULL THEN
    SELECT booked_by_member_id, booked_by_email, booked_by_name INTO v_b FROM bookings WHERE id = NEW.booking_id;
    IF FOUND THEN
      NEW.booked_by_member_id := v_b.booked_by_member_id;
      NEW.booked_by_email := coalesce(NEW.booked_by_email, v_b.booked_by_email);
      NEW.booked_by_name := coalesce(NEW.booked_by_name, v_b.booked_by_name);
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_slot_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE cap int; taken int; v_key bigint; v_slot text;
BEGIN
  IF NEW.venue_id IS NULL THEN RAISE EXCEPTION 'booking requires a valid venue'; END IF;
  IF coalesce(NEW.status,'pending') IN ('cancelled','declined','expired','auth_canceled') THEN RETURN NEW; END IF;
  -- 1. Venue row lock FIRST (see 0070). The cap used below is the one read under that lock.
  SELECT max_demos_per_slot INTO cap FROM venues
   WHERE id = NEW.venue_id AND retailer_id = NEW.retailer_id
   FOR SHARE;
  IF cap IS NULL THEN RAISE EXCEPTION 'venue does not belong to this retailer'; END IF;
  -- 2. Per-slot advisory lock on the RESOLVED slot (0075): "11:00", "11:00 AM" and "11:00 am"
  --    are one slot, one lock, one count.
  v_slot := slot_key(NEW.demo_time);
  v_key := hashtextextended(NEW.venue_id::text || '|' || coalesce(NEW.demo_date::text,'') || '|' || v_slot, 0);
  PERFORM pg_advisory_xact_lock(v_key);
  SELECT count(*) INTO taken FROM bookings
   WHERE venue_id = NEW.venue_id
     AND demo_date = NEW.demo_date
     AND slot_key(demo_time) = v_slot
     AND coalesce(status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled');
  IF taken >= cap THEN
    RAISE EXCEPTION 'slot_full: % already booked for % % (cap %)', taken, NEW.demo_date, NEW.demo_time, cap
      USING errcode = 'check_violation';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_slot_capacity_on_move()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  cap int; taken int; v_key bigint; v_slot text;
  slot_changed boolean;
  reactivated  boolean;
BEGIN
  slot_changed := NEW.venue_id   IS DISTINCT FROM OLD.venue_id
               OR NEW.demo_date  IS DISTINCT FROM OLD.demo_date
               OR slot_key(NEW.demo_time) IS DISTINCT FROM slot_key(OLD.demo_time);
  reactivated  :=     coalesce(OLD.status,'pending')     IN ('cancelled','declined','expired','auth_canceled')
               AND coalesce(NEW.status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled');
  IF NOT slot_changed AND NOT reactivated THEN RETURN NEW; END IF;
  IF coalesce(NEW.status,'pending') IN ('cancelled','declined','expired','auth_canceled') THEN RETURN NEW; END IF;
  -- 1. Venue row lock FIRST (see enforce_slot_capacity).
  SELECT max_demos_per_slot INTO cap FROM venues
   WHERE id = NEW.venue_id AND retailer_id = NEW.retailer_id
   FOR SHARE;
  IF cap IS NULL THEN RAISE EXCEPTION 'venue does not belong to this retailer'; END IF;
  -- 2. Per-slot advisory lock on the DESTINATION slot, normalized (0075).
  v_slot := slot_key(NEW.demo_time);
  v_key := hashtextextended(NEW.venue_id::text || '|' || coalesce(NEW.demo_date::text,'') || '|' || v_slot, 0);
  PERFORM pg_advisory_xact_lock(v_key);
  -- 3. Count the OTHER active bookings on the destination slot (a same-slot reactivation counts
  --    correctly because the row itself is excluded).
  SELECT count(*) INTO taken FROM bookings
   WHERE venue_id = NEW.venue_id AND demo_date = NEW.demo_date AND slot_key(demo_time) = v_slot
     AND id <> NEW.id
     AND coalesce(status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled');
  IF taken >= cap THEN
    RAISE EXCEPTION 'slot_full: % already booked for % % (cap %)', taken, NEW.demo_date, NEW.demo_time, cap
      USING errcode = 'check_violation';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.expire_payment_attempt(p_session_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_att record; v_grp record; v_other int;
BEGIN
  SELECT * INTO v_att FROM payment_attempts WHERE stripe_checkout_session_id = p_session_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_attempt'); END IF;
  SELECT * INTO v_grp FROM payment_groups WHERE id = v_att.payment_group_id FOR UPDATE;
  SELECT * INTO v_att FROM payment_attempts WHERE id = v_att.id FOR UPDATE;
  IF v_att.status <> 'open' THEN RETURN jsonb_build_object('outcome','not_open','status',v_att.status); END IF;
  IF v_grp.status = 'paid' THEN
    UPDATE payment_attempts SET status = 'expired', expired_at = now(), last_error = 'superseded_by_paid' WHERE id = v_att.id;
    RETURN jsonb_build_object('outcome','superseded_group_paid');
  END IF;
  UPDATE payment_attempts SET status = 'expired', expired_at = now() WHERE id = v_att.id;
  SELECT count(*) INTO v_other FROM payment_attempts WHERE payment_group_id = v_grp.id AND status = 'open';
  IF v_other = 0 AND v_grp.status IN ('pending','session_created') THEN
    -- release the group's session binding so a FRESH attempt can be created (P0-2)
    UPDATE payment_groups SET status = 'pending' WHERE id = v_grp.id;
    RETURN jsonb_build_object('outcome','attempt_expired_group_reopened','payment_group_id',v_grp.id);
  END IF;
  RETURN jsonb_build_object('outcome','attempt_expired','payment_group_id',v_grp.id);
END $function$

CREATE OR REPLACE FUNCTION public.finalize_move_settlement(p_move_id uuid, p_owner text, p_settled boolean, p_refund_status text DEFAULT NULL::text, p_refund_request_id uuid DEFAULT NULL::uuid, p_case_id uuid DEFAULT NULL::uuid, p_error text DEFAULT NULL::text, p_event_payload jsonb DEFAULT NULL::jsonb, p_refund_case_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(ok boolean, reason text, event_written boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_m booking_moves%ROWTYPE; v_b bookings%ROWTYPE; v_n integer := 0; v_now timestamptz; v_env text;
  v_req refund_requests%ROWTYPE; v_case reconciliation_cases%ROWTYPE; v_alloc payment_allocations%ROWTYPE;
BEGIN
  SELECT * INTO v_m FROM booking_moves m WHERE m.id = p_move_id;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found'::text, false; RETURN; END IF;
  SELECT * INTO v_b FROM bookings b WHERE b.id = v_m.booking_id FOR UPDATE;
  SELECT * INTO v_m FROM booking_moves m WHERE m.id = p_move_id FOR UPDATE;
  v_now := clock_timestamp();
  IF v_m.settle_lease_owner IS DISTINCT FROM p_owner THEN RETURN QUERY SELECT false, 'lease_lost'::text, false; RETURN; END IF;
  IF v_m.settled_at IS NOT NULL THEN RETURN QUERY SELECT false, 'already_settled'::text, false; RETURN; END IF;
  IF v_m.status NOT IN ('declined', 'lapsed') THEN RETURN QUERY SELECT false, ('move_' || v_m.status)::text, false; RETURN; END IF;
  IF NOT coalesce(p_settled, false) THEN
    UPDATE booking_moves
       SET settle_attempts = settle_attempts + 1, settle_last_error = left(coalesce(p_error, 'unknown'), 300),
           refund_request_id = coalesce(p_refund_request_id, refund_request_id),
           reconciliation_case_id = coalesce(p_case_id, reconciliation_case_id),
           refund_case_id = coalesce(p_refund_case_id, refund_case_id),
           refund_status = coalesce(p_refund_status, refund_status),
           settle_lease_owner = NULL, settle_lease_until = NULL, updated_at = v_now
     WHERE id = p_move_id;
    RETURN QUERY SELECT true, NULL::text, false; RETURN;
  END IF;
  IF v_b.id IS NULL THEN RETURN QUERY SELECT false, 'booking_missing'::text, false; RETURN; END IF;
  IF coalesce(v_b.status, 'pending') NOT IN ('cancelled', 'declined', 'expired', 'auth_canceled') THEN
    RETURN QUERY SELECT false, 'booking_still_active'::text, false; RETURN;
  END IF;
  IF p_refund_status IS NULL OR p_refund_status NOT IN ('not_paid', 'already_refunded', 'submitted', 'succeeded', 'pending_worker', 'review_required') THEN
    RETURN QUERY SELECT false, 'refund_status_unknown'::text, false; RETURN;
  END IF;
  IF p_refund_status IN ('submitted', 'succeeded', 'pending_worker') THEN
    IF p_refund_request_id IS NULL THEN RETURN QUERY SELECT false, 'request_required'::text, false; RETURN; END IF;
    SELECT * INTO v_req FROM refund_requests r WHERE r.id = p_refund_request_id;
    IF NOT FOUND OR v_req.booking_id IS DISTINCT FROM v_m.booking_id THEN RETURN QUERY SELECT false, 'request_invalid'::text, false; RETURN; END IF;
    -- R2-1: the label must agree with the request's persisted state.
    IF p_refund_status = 'succeeded' AND v_req.status <> 'succeeded' THEN RETURN QUERY SELECT false, 'request_state_mismatch'::text, false; RETURN; END IF;
    IF p_refund_status = 'submitted' AND v_req.status NOT IN ('submitted', 'pending', 'requires_action', 'succeeded') THEN RETURN QUERY SELECT false, 'request_state_mismatch'::text, false; RETURN; END IF;
    IF p_refund_status = 'pending_worker' AND v_req.status NOT IN ('reserved', 'failed_retryable', 'submitted', 'pending', 'requires_action', 'succeeded') THEN RETURN QUERY SELECT false, 'request_state_mismatch'::text, false; RETURN; END IF;
  ELSIF p_refund_status = 'review_required' THEN
    IF p_refund_case_id IS NULL THEN RETURN QUERY SELECT false, 'case_required'::text, false; RETURN; END IF;
    SELECT * INTO v_case FROM reconciliation_cases c WHERE c.id = p_refund_case_id;
    IF NOT FOUND OR v_case.dedupe_key IS DISTINCT FROM ('move_refund:' || p_move_id::text) THEN RETURN QUERY SELECT false, 'case_invalid'::text, false; RETURN; END IF;
  ELSIF p_refund_status = 'not_paid' THEN
    IF NOT (v_b.fee_waived IS TRUE OR (v_b.payment_intent_id IS NULL AND coalesce(v_b.payment_status, 'unpaid') NOT IN ('paid', 'refund_pending', 'authorized'))) THEN
      RETURN QUERY SELECT false, 'not_paid_inconsistent'::text, false; RETURN;
    END IF;
  ELSIF p_refund_status = 'already_refunded' THEN
    -- R2-1: completed money only. A reservation (reserved_refund_amount) is never completion; a succeeded
    -- request is not proof of the full entitlement; the allocation's refunded_amount is.
    SELECT * INTO v_alloc FROM payment_allocations a WHERE a.booking_id = v_m.booking_id ORDER BY a.created_at LIMIT 1;
    IF NOT (coalesce(v_b.payment_status, '') = 'refunded'
            OR (v_alloc.id IS NOT NULL AND v_alloc.refunded_amount >= v_alloc.customer_amount)) THEN
      RETURN QUERY SELECT false, 'already_refunded_inconsistent'::text, false; RETURN;
    END IF;
  END IF;
  UPDATE booking_moves
     SET settled_at = v_now, refund_status = p_refund_status, refund_request_id = coalesce(p_refund_request_id, refund_request_id),
         reconciliation_case_id = coalesce(p_case_id, reconciliation_case_id), refund_case_id = coalesce(p_refund_case_id, refund_case_id),
         settle_last_error = NULL, settle_lease_owner = NULL, settle_lease_until = NULL, updated_at = v_now
   WHERE id = p_move_id;
  UPDATE bookings SET pending_move_settlement = NULL WHERE id = v_m.booking_id AND pending_move_settlement = p_move_id;
  INSERT INTO notification_events (retailer_id, booking_id, brand_id, kind, transition_id, payload)
  VALUES (v_m.retailer_id, v_m.booking_id, coalesce(v_m.brand_id, v_b.brand_id), 'demo_move_cancelled', p_move_id::text || ':cancelled',
          (coalesce(p_event_payload, '{}'::jsonb) - '_inject_failure') || jsonb_build_object('move_id', p_move_id, 'outcome', v_m.status, 'refund_status', p_refund_status,
                                                                      'refund_request_id', coalesce(p_refund_request_id, v_m.refund_request_id),
                                                                      'refund_case_id', coalesce(p_refund_case_id, v_m.refund_case_id),
                                                                      'to_date', v_m.to_date, 'to_time', v_m.to_time, 'from_date', v_m.from_date, 'from_time', v_m.from_time, 'note', v_m.note))
  ON CONFLICT (kind, transition_id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF coalesce(p_event_payload->>'_inject_failure', '') = 'true' THEN
    SELECT environment INTO v_env FROM get_deployment_identity();
    IF v_env IS DISTINCT FROM 'production' THEN RAISE EXCEPTION 'injected_failure_after_finalize' USING errcode = 'check_violation'; END IF;
  END IF;
  RETURN QUERY SELECT true, NULL::text, v_n > 0;
END $function$

CREATE OR REPLACE FUNCTION public.finalize_refund(p_stripe_refund_id text, p_status text, p_amount integer, p_currency text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_req record; v_alloc record; v_grp uuid; v_all boolean;
BEGIN
  SELECT * INTO v_req FROM refund_requests WHERE stripe_refund_id = p_stripe_refund_id FOR UPDATE;
  IF NOT FOUND THEN RETURN 'unmatched'; END IF;                                   -- typed, not an exception
  IF p_amount IS NOT NULL AND p_amount <> v_req.amount THEN RAISE EXCEPTION 'refund_amount_mismatch % <> %', p_amount, v_req.amount; END IF;
  IF p_currency IS NOT NULL AND lower(p_currency) <> lower(v_req.currency) THEN RAISE EXCEPTION 'refund_currency_mismatch'; END IF;
  IF v_req.status IN ('succeeded','failed','canceled') THEN RETURN 'already_terminal'; END IF;
  SELECT * INTO v_alloc FROM payment_allocations WHERE id = v_req.payment_allocation_id FOR UPDATE;
  IF p_status = 'succeeded' THEN
    IF v_alloc.reserved_refund_amount < v_req.amount THEN RAISE EXCEPTION 'reservation_underflow'; END IF;
    UPDATE payment_allocations SET reserved_refund_amount = reserved_refund_amount - v_req.amount, refunded_amount = refunded_amount + v_req.amount WHERE id = v_alloc.id;
    UPDATE refund_requests SET status = 'succeeded' WHERE id = v_req.id;
    UPDATE bookings SET payment_status = CASE WHEN (v_alloc.refunded_amount + v_req.amount) >= v_alloc.customer_amount THEN 'refunded' ELSE 'partial_refund' END,
                        refund_id = p_stripe_refund_id, refunded_at = now() WHERE id = v_req.booking_id;
  ELSIF p_status IN ('failed','canceled') THEN
    UPDATE payment_allocations SET reserved_refund_amount = greatest(0, reserved_refund_amount - v_req.amount) WHERE id = v_alloc.id;
    UPDATE refund_requests SET status = p_status WHERE id = v_req.id;
  ELSE
    RETURN 'pending';                                                            -- pending/requires_action: no money move
  END IF;
  v_grp := v_alloc.payment_group_id;
  SELECT bool_and(refunded_amount >= customer_amount) INTO v_all FROM payment_allocations WHERE payment_group_id = v_grp;
  UPDATE payment_groups SET status = CASE WHEN v_all THEN 'refunded'
                                          WHEN EXISTS (SELECT 1 FROM payment_allocations WHERE payment_group_id = v_grp AND refunded_amount > 0) THEN 'partially_refunded'
                                          ELSE status END
    WHERE id = v_grp AND status IN ('paid','partially_refunded');
  RETURN 'finalized';
END $function$

CREATE OR REPLACE FUNCTION public.freeze_fulfillment_outbound(p_booking_id uuid, p_owner text, p_generation integer, p_key text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v booking_fulfillments%ROWTYPE; v_new jsonb;
BEGIN
  IF p_booking_id IS NULL OR p_owner IS NULL OR p_generation IS NULL OR coalesce(btrim(p_key), '') = '' THEN
    RETURN jsonb_build_object('outcome', 'stale', 'reason', 'missing_claim');
  END IF;
  SELECT * INTO v FROM booking_fulfillments WHERE booking_id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'stale', 'reason', 'no_row'); END IF;
  -- the same fence as record_fulfillment (0081): the claim must still be the CURRENT one
  IF v.lease_owner IS DISTINCT FROM p_owner OR v.generation IS DISTINCT FROM p_generation OR v.status <> 'pending' THEN
    RETURN jsonb_build_object('outcome', 'stale', 'reason',
      CASE WHEN v.status <> 'pending' THEN 'row_' || v.status
           WHEN v.generation IS DISTINCT FROM p_generation THEN 'generation_' || v.generation::text
           ELSE 'lease_' || coalesce(v.lease_owner, 'none') END);
  END IF;
  -- first writer wins: an already-frozen message is returned, never replaced
  IF v.outbound ? p_key THEN
    RETURN jsonb_build_object('outcome', 'existing', 'payload', v.outbound -> p_key);
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
     OR coalesce(p_payload->>'to', '') = '' OR coalesce(p_payload->>'subject', '') = '' OR coalesce(p_payload->>'html', '') = '' THEN
    RAISE EXCEPTION 'freeze_fulfillment_outbound: payload must carry to, subject and html' USING errcode = 'check_violation';
  END IF;
  v_new := p_payload || jsonb_build_object('frozen_at', to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
  UPDATE booking_fulfillments SET outbound = outbound || jsonb_build_object(p_key, v_new) WHERE booking_id = p_booking_id;
  RETURN jsonb_build_object('outcome', 'frozen', 'payload', v_new);
END $function$

CREATE OR REPLACE FUNCTION public.guard_capacity_decrease()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_slot record;
  v_taken int;
  v_key bigint;
BEGIN
  IF NEW.max_demos_per_slot IS NULL OR OLD.max_demos_per_slot IS NULL
     OR NEW.max_demos_per_slot >= OLD.max_demos_per_slot THEN
    RETURN NEW;
  END IF;
  FOR v_slot IN
    SELECT demo_date, slot_key(demo_time), min(demo_time) AS demo_time
      FROM bookings
     WHERE venue_id = NEW.id
       AND demo_date >= current_date
       AND coalesce(status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled')
     GROUP BY demo_date, slot_key(demo_time)
     ORDER BY demo_date, slot_key(demo_time)
  LOOP
    v_key := hashtextextended(NEW.id::text || '|' || coalesce(v_slot.demo_date::text,'') || '|' || v_slot.slot_key, 0);
    PERFORM pg_advisory_xact_lock(v_key);
    SELECT count(*) INTO v_taken FROM bookings
     WHERE venue_id = NEW.id
       AND demo_date = v_slot.demo_date
       AND slot_key(demo_time) = v_slot.slot_key
       AND coalesce(status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled');
    IF v_taken > NEW.max_demos_per_slot THEN
      RAISE EXCEPTION 'capacity_below_active_reservations: venue % has % active reservation(s) for % % but proposed max_demos_per_slot is % (current %)',
        NEW.id, v_taken, v_slot.demo_date, v_slot.demo_time, NEW.max_demos_per_slot, OLD.max_demos_per_slot
        USING errcode = 'check_violation',
              hint = 'Cancel or move the excess reservations first, then lower the capacity.';
    END IF;
  END LOOP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.issue_calendar_token(p_brand_id uuid, p_rotate boolean DEFAULT false, p_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_token uuid;
BEGIN
  IF p_brand_id IS NULL THEN RAISE EXCEPTION 'brand_required'; END IF;
  IF coalesce(p_rotate,false) THEN
    UPDATE brand_calendar_tokens SET revoked_at = now() WHERE brand_id = p_brand_id AND revoked_at IS NULL;
  ELSE
    SELECT token INTO v_token FROM brand_calendar_tokens
     WHERE brand_id = p_brand_id AND revoked_at IS NULL ORDER BY created_at DESC LIMIT 1;
    IF v_token IS NOT NULL THEN RETURN v_token; END IF;
  END IF;
  INSERT INTO brand_calendar_tokens(brand_id, label) VALUES (p_brand_id, p_label) RETURNING token INTO v_token;
  RETURN v_token;
END $function$

CREATE OR REPLACE FUNCTION public.lapse_booking_moves(p_limit integer DEFAULT 25)
 RETURNS SETOF booking_moves
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record; v_b bookings%ROWTYPE; v_m booking_moves%ROWTYPE; v_now timestamptz;
BEGIN
  FOR r IN
    SELECT m.id, m.booking_id FROM booking_moves m
     WHERE m.status = 'pending' AND m.reconfirm_due_at <= clock_timestamp()
     ORDER BY m.reconfirm_due_at ASC
     LIMIT greatest(coalesce(p_limit, 25), 1)
  LOOP
    SELECT * INTO v_b FROM bookings b WHERE b.id = r.booking_id FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN CONTINUE; END IF;
    SELECT * INTO v_m FROM booking_moves m WHERE m.id = r.id FOR UPDATE SKIP LOCKED;
    v_now := clock_timestamp();
    IF NOT FOUND OR v_m.status <> 'pending' OR v_m.reconfirm_due_at > v_now THEN CONTINUE; END IF;
    IF coalesce(v_b.status, 'pending') NOT IN ('pending', 'confirmed') OR v_b.schedule_revision IS DISTINCT FROM v_m.schedule_revision OR v_b.pending_move_settlement IS NOT NULL THEN
      UPDATE booking_moves SET status = 'superseded', updated_at = v_now WHERE id = v_m.id;
      CONTINUE;
    END IF;
    UPDATE booking_moves SET status = 'lapsed', lapsed_at = v_now, updated_at = v_now WHERE id = v_m.id RETURNING * INTO v_m;
    UPDATE bookings SET pending_move_settlement = v_m.id WHERE id = v_b.id;
    RETURN NEXT v_m;
  END LOOP;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.move_booking_by_retailer(p_demo_id uuid, p_retailer_id uuid, p_new_date date, p_new_time text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_actor text DEFAULT NULL::text, p_reconfirm_hours integer DEFAULT 72)
 RETURNS TABLE(ok boolean, reason text, booking_id uuid, schedule_revision integer, move_id uuid, reconfirm_due_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bid      uuid;
  v_b        bookings%ROWTYPE;
  v_d        demos%ROWTYPE;
  v_brand    brands%ROWTYPE;
  v_tz       text;
  v_today    date;
  v_new_time text;
  v_old_rev  integer;
  v_new_rev  integer;
  v_new_dur  integer;
  v_start    timestamptz;
  v_covered  boolean;
  v_note     text;
  v_due      timestamptz;
  v_move     uuid;
  v_hours    integer := greatest(coalesce(p_reconfirm_hours, 72), 1);
BEGIN
  SELECT d.booking_id INTO v_bid FROM demos d WHERE d.id = p_demo_id AND d.retailer_id = p_retailer_id;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found'::text, NULL::uuid, NULL::integer, NULL::uuid, NULL::timestamptz; RETURN; END IF;
  IF v_bid IS NULL THEN RETURN QUERY SELECT false, 'no_booking'::text, NULL::uuid, NULL::integer, NULL::uuid, NULL::timestamptz; RETURN; END IF;
  SELECT * INTO v_b FROM bookings b WHERE b.id = v_bid FOR UPDATE;
  IF NOT FOUND OR v_b.retailer_id IS DISTINCT FROM p_retailer_id THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::uuid, NULL::integer, NULL::uuid, NULL::timestamptz; RETURN;
  END IF;
  SELECT * INTO v_d FROM demos d WHERE d.id = p_demo_id FOR UPDATE;
  IF v_d.booking_id IS DISTINCT FROM v_bid THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::uuid, NULL::integer, NULL::uuid, NULL::timestamptz; RETURN;
  END IF;
  IF coalesce(v_b.status, 'pending') NOT IN ('pending', 'confirmed') OR coalesce(v_d.status, '') NOT IN ('confirmed', 'scheduled') THEN
    RETURN QUERY SELECT false, 'not_active'::text, v_bid, v_b.schedule_revision, NULL::uuid, NULL::timestamptz; RETURN;
  END IF;
  -- RM-1: a decline / lapse is being settled (cancel + refund). No schedule change may land on top of it.
  IF v_b.pending_move_settlement IS NOT NULL OR v_b.cancellation_pending_at IS NOT NULL THEN   -- 0106: a recorded cancellation is a barrier too
    RETURN QUERY SELECT false, 'cancellation_pending'::text, v_bid, v_b.schedule_revision, v_b.pending_move_settlement, NULL::timestamptz; RETURN;
  END IF;
  v_note := nullif(btrim(coalesce(p_note, '')), '');
  IF length(coalesce(v_note, '')) > 500 THEN RETURN QUERY SELECT false, 'note_too_long'::text, v_bid, v_b.schedule_revision, NULL::uuid, NULL::timestamptz; RETURN; END IF;
  SELECT r.timezone INTO v_tz FROM retailers r WHERE r.id = p_retailer_id;
  v_tz := coalesce(nullif(btrim(v_tz), ''), 'America/Los_Angeles');
  v_today := (now() AT TIME ZONE v_tz)::date;
  IF p_new_date IS NULL OR p_new_date < v_today THEN RETURN QUERY SELECT false, 'date_in_past'::text, v_bid, v_b.schedule_revision, NULL::uuid, NULL::timestamptz; RETURN; END IF;
  v_new_time := coalesce(nullif(btrim(p_new_time), ''), v_b.demo_time, v_d.demo_time);
  IF p_new_date = v_b.demo_date AND (
       v_new_time IS NOT DISTINCT FROM v_b.demo_time
       OR (booking_slot_start(p_new_date, v_new_time, v_tz, NULL) IS NOT NULL
           AND booking_slot_start(p_new_date, v_new_time, v_tz, NULL) IS NOT DISTINCT FROM booking_slot_start(v_b.demo_date, v_b.demo_time, v_tz, NULL))) THEN
    RETURN QUERY SELECT false, 'same_slot'::text, v_bid, v_b.schedule_revision, NULL::uuid, NULL::timestamptz; RETURN;
  END IF;
  SELECT * INTO v_brand FROM brands br WHERE br.id = coalesce(v_b.brand_id, v_d.brand_id);
  v_covered := (v_b.coi_waived_at IS NOT NULL)
            OR (v_brand.default_coi_url IS NOT NULL
                AND lower(coalesce(v_brand.coi_verification_status, '')) IN ('passed', 'approved')
                AND v_brand.default_coi_expires IS NOT NULL
                AND v_brand.default_coi_expires >= p_new_date);
  IF NOT coalesce(v_covered, false) THEN RETURN QUERY SELECT false, 'coi_not_covered'::text, v_bid, v_b.schedule_revision, NULL::uuid, NULL::timestamptz; RETURN; END IF;
  v_old_rev := v_b.schedule_revision;
  BEGIN
    UPDATE bookings
       SET demo_date = p_new_date,
           demo_time = v_new_time,
           schedule_revision = bookings.schedule_revision + 1
     WHERE id = v_bid
    RETURNING bookings.schedule_revision, bookings.duration_hours, bookings.start_at INTO v_new_rev, v_new_dur, v_start;
    IF v_start IS NULL THEN
      RAISE EXCEPTION 'unresolvable_start' USING errcode = 'check_violation';
    END IF;
    IF v_start <= now() THEN
      RAISE EXCEPTION 'time_in_past' USING errcode = 'check_violation';
    END IF;
  EXCEPTION WHEN check_violation THEN
    IF SQLERRM LIKE 'slot_full%' THEN RETURN QUERY SELECT false, 'slot_full'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'slot_not_offered%' THEN RETURN QUERY SELECT false, 'slot_not_offered'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'slot_outside_hours%' THEN RETURN QUERY SELECT false, 'slot_outside_hours'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'date_blackout%' THEN RETURN QUERY SELECT false, 'date_blackout'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'venue_closed%' THEN RETURN QUERY SELECT false, 'venue_closed'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'slot_config_invalid%' THEN RETURN QUERY SELECT false, 'slot_config_invalid'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'venue_hours_not_set%' THEN RETURN QUERY SELECT false, 'venue_hours_not_set'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'invalid_local_time%' THEN RETURN QUERY SELECT false, 'invalid_local_time'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'time_in_past%' THEN RETURN QUERY SELECT false, 'time_in_past'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    IF SQLERRM LIKE 'unresolvable_start%' THEN RETURN QUERY SELECT false, 'unresolvable_start'::text, v_bid, v_old_rev, NULL::uuid, NULL::timestamptz; RETURN; END IF;
    RAISE;
  END;
  UPDATE demos
     SET demo_date = p_new_date, demo_time = v_new_time,
         duration_hours = coalesce(v_new_dur, demos.duration_hours),
         reschedule_to_date = NULL, reschedule_to_time = NULL, reschedule_requested_at = NULL
   WHERE id = v_d.id;
  -- RM-5: ONE explicit policy, the same function the store sees before committing.
  v_due := move_reconfirm_deadline(now(), v_start, v_hours);
  UPDATE booking_moves SET status = 'superseded', updated_at = now()
   WHERE booking_moves.booking_id = v_bid AND booking_moves.status = 'pending';
  INSERT INTO booking_moves (booking_id, retailer_id, brand_id, demo_id, from_date, from_time, to_date, to_time, schedule_revision, note, moved_by, moved_at, reconfirm_due_at)
  VALUES (v_bid, p_retailer_id, coalesce(v_b.brand_id, v_d.brand_id), v_d.id, v_b.demo_date, v_b.demo_time, p_new_date, v_new_time, v_new_rev, v_note, p_actor, now(), v_due)
  RETURNING id INTO v_move;
  INSERT INTO notification_events (retailer_id, booking_id, brand_id, kind, transition_id, payload)
  VALUES (v_b.retailer_id, v_bid, coalesce(v_b.brand_id, v_d.brand_id), 'demo_rescheduled',
          v_bid::text || ':rescheduled:' || v_new_rev::text,
          jsonb_build_object('old_date', v_b.demo_date, 'old_time', v_b.demo_time, 'old_schedule_revision', v_old_rev,
                             'new_date', p_new_date, 'new_time', v_new_time, 'schedule_revision', v_new_rev,
                             'venue_id', v_b.venue_id, 'timezone', v_tz, 'moved_by_retailer', true, 'move_id', v_move))
  ON CONFLICT (kind, transition_id) DO NOTHING;
  INSERT INTO notification_events (retailer_id, booking_id, brand_id, kind, transition_id, payload)
  VALUES (v_b.retailer_id, v_bid, coalesce(v_b.brand_id, v_d.brand_id), 'demo_moved', v_move::text,
          jsonb_build_object('move_id', v_move, 'old_date', v_b.demo_date, 'old_time', v_b.demo_time,
                             'new_date', p_new_date, 'new_time', v_new_time, 'schedule_revision', v_new_rev,
                             'note', v_note, 'reconfirm_due_at', v_due, 'venue_id', v_b.venue_id, 'timezone', v_tz))
  ON CONFLICT (kind, transition_id) DO NOTHING;
  UPDATE notification_deliveries
     SET status = 'skipped', skip_reason = 'rescheduled', updated_at = now()
   WHERE occurrence_key = v_bid::text || ':' || v_old_rev::text
     AND notification_deliveries.status IN ('pending', 'claimed');
  RETURN QUERY SELECT true, NULL::text, v_bid, v_new_rev, v_move, v_due;
END $function$

CREATE OR REPLACE FUNCTION public.offering_anomalies(p_retailer_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(booking_id uuid, venue_id uuid, retailer_id uuid, demo_date date, demo_time text, duration_hours integer, reason text, class text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_ok boolean; v_reason text; v_hours integer; v_min integer; v_class text;
BEGIN
  FOR r IN
    SELECT b.id, b.venue_id, b.retailer_id, b.demo_date, b.demo_time, b.duration_hours, b.timezone, v.availability
      FROM bookings b JOIN venues v ON v.id = b.venue_id
     WHERE (p_retailer_id IS NULL OR b.retailer_id = p_retailer_id)
       AND b.demo_date >= current_date
       AND coalesce(b.status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled')
     ORDER BY b.demo_date, b.demo_time
  LOOP
    v_min := slot_minutes(r.demo_time); v_reason := NULL; v_class := NULL;
    IF v_min IS NULL THEN
      v_reason := 'unparseable_time'; v_class := 'legacy';
    ELSIF NOT venue_schedule_present(r.availability) THEN
      -- accepted before the location had hours: reported as legacy, never as a broken invariant
      v_reason := 'venue_hours_not_set'; v_class := 'legacy';
    ELSE
      BEGIN
        PERFORM venue_availability_validate(r.availability);
        SELECT o.ok, o.reason, o.hours INTO v_ok, v_reason, v_hours FROM venue_slot_offered(r.availability, r.demo_date, v_min) o;
      EXCEPTION WHEN check_violation THEN
        v_ok := false; v_reason := 'slot_config_invalid';
      END;
      IF v_reason IN ('date_blackout', 'venue_closed', 'slot_outside_hours') THEN
        -- allowed to coexist with an accepted reservation: only the interval itself must survive
        SELECT sc.hours INTO v_hours FROM venue_slots_config(r.availability) sc WHERE sc.start_min = v_min;
        v_ok := v_hours IS NOT NULL; v_reason := CASE WHEN v_ok THEN NULL ELSE 'slot_not_offered' END;
      END IF;
      IF v_reason = 'venue_hours_not_set' THEN
        v_class := 'legacy';
      ELSIF NOT coalesce(v_ok, false) THEN
        v_class := 'invariant';
      ELSIF v_hours IS DISTINCT FROM coalesce(r.duration_hours, 3) THEN
        v_reason := 'duration_mismatch'; v_class := 'invariant';
      ELSIF booking_slot_start_strict(r.demo_date, slot_label(v_min), r.timezone) IS NULL THEN
        v_reason := 'invalid_local_time'; v_class := 'legacy';
      END IF;
    END IF;
    IF v_reason IS NOT NULL THEN
      booking_id := r.id; venue_id := r.venue_id; retailer_id := r.retailer_id; demo_date := r.demo_date; demo_time := r.demo_time;
      duration_hours := r.duration_hours; reason := v_reason; class := v_class;
      RETURN NEXT;
    END IF;
  END LOOP;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.park_refund_for_review(p_request_id uuid, p_owner text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_req record; v_case uuid;
BEGIN
  SELECT * INTO v_req FROM refund_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_request'); END IF;
  -- reservation is intentionally PRESERVED: Stripe may still hold an unadopted refund
  UPDATE refund_requests SET status = 'requires_review', lease_owner = NULL, lease_expires_at = NULL,
         last_error = coalesce(p_reason, last_error) WHERE id = p_request_id;
  IF v_req.parent_operation_id IS NOT NULL THEN
    UPDATE refund_operations SET status = 'requires_review' WHERE id = v_req.parent_operation_id;
  END IF;
  v_case := _open_case('refund_requires_review','park:'||p_request_id::text,coalesce(p_reason,'retry_cap_exhausted'),
                       NULL, p_request_id, v_req.parent_operation_id, NULL, NULL, NULL, v_req.stripe_refund_id,
                       v_req.amount, v_req.currency, jsonb_build_object('attempts',v_req.attempts,'owner',p_owner));
  RETURN jsonb_build_object('outcome','parked','case_id',v_case,'refund_request_id',p_request_id);
END $function$

CREATE OR REPLACE FUNCTION public.promote_held_bookings(p_brand_id uuid, p_member_id uuid, p_role text, p_booking_ids uuid[], p_covered_booking_ids uuid[])
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ids uuid[]; v_cov uuid[]; v_bid uuid; v_bk record; v_n int; v_promoted uuid[] := '{}';
BEGIN
  IF p_brand_id IS NULL THEN RAISE EXCEPTION 'brand_required'; END IF;
  IF array_length(p_booking_ids,1) IS NULL THEN RAISE EXCEPTION 'no bookings'; END IF;
  SELECT array_agg(x ORDER BY x) INTO v_ids FROM (SELECT DISTINCT unnest(p_booking_ids) x) d;
  v_cov := coalesce(p_covered_booking_ids, '{}'::uuid[]);
  IF EXISTS (SELECT 1 FROM unnest(v_cov) c WHERE NOT (c = ANY(v_ids))) THEN RAISE EXCEPTION 'covered_not_in_set'; END IF;
  -- Lock every requested booking in id order (the order checkout_claim_group takes its locks in), then authorize the
  -- WHOLE set before any write: exact set, every booking owned by the authenticated brand, a booker only its own
  -- bookings, one store. A set that fails any of these changes nothing.
  FOREACH v_bid IN ARRAY v_ids LOOP
    PERFORM 1 FROM bookings b WHERE b.id = v_bid FOR UPDATE;
  END LOOP;
  SELECT count(*) INTO v_n FROM bookings b WHERE b.id = ANY(v_ids);
  IF v_n <> array_length(v_ids,1) THEN RAISE EXCEPTION 'booking_set_mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM bookings b WHERE b.id = ANY(v_ids) AND (b.brand_id IS NULL OR b.brand_id <> p_brand_id)) THEN RAISE EXCEPTION 'not_your_booking'; END IF;
  IF p_role = 'booker' THEN
    IF p_member_id IS NULL OR EXISTS (SELECT 1 FROM bookings b WHERE b.id = ANY(v_ids) AND (b.booked_by_member_id IS NULL OR b.booked_by_member_id <> p_member_id)) THEN
      RAISE EXCEPTION 'not_your_booking';
    END IF;
  END IF;
  SELECT count(DISTINCT b.retailer_id) INTO v_n FROM bookings b WHERE b.id = ANY(v_ids);
  IF v_n <> 1 THEN RAISE EXCEPTION 'mixed_retailers'; END IF;
  -- Eligibility, re-read under the lock, per booking the caller's coverage policy marked as covered: still held and
  -- unpaid, never authorized (no PaymentIntent), not expired, and in NO payment group (allocations are only ever
  -- inserted by checkout_claim_group while it holds this same row lock, so this read is authoritative).
  FOREACH v_bid IN ARRAY v_ids LOOP
    CONTINUE WHEN NOT (v_bid = ANY(v_cov));
    SELECT b.status, b.payment_status, b.payment_intent_id, b.held_expires_at INTO v_bk FROM bookings b WHERE b.id = v_bid;
    IF v_bk.status = 'held' AND v_bk.payment_status = 'unpaid' AND v_bk.payment_intent_id IS NULL
       AND (v_bk.held_expires_at IS NULL OR v_bk.held_expires_at > now())
       AND NOT EXISTS (SELECT 1 FROM payment_allocations a WHERE a.booking_id = v_bid) THEN
      UPDATE bookings SET status = 'pending_payment', held_expires_at = NULL
        WHERE bookings.id = v_bid AND bookings.status = 'held' AND bookings.payment_status = 'unpaid';
      v_promoted := v_promoted || v_bid;
    END IF;
  END LOOP;
  RETURN QUERY
    SELECT to_jsonb(b) || jsonb_build_object('promoted', b.id = ANY(v_promoted))
    FROM bookings b WHERE b.id = ANY(v_ids) ORDER BY b.id;
END $function$

CREATE OR REPLACE FUNCTION public.propose_reschedule(p_demo_id uuid, p_retailer_id uuid, p_new_date date, p_new_time text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, reason text, proposal_version integer, booking_id uuid, new_time text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bid  uuid;
  v_b    bookings%ROWTYPE;
  v_d    demos%ROWTYPE;
  v_tz   text;
  v_ver  integer;
  v_time text;
BEGIN
  SELECT d.booking_id INTO v_bid FROM demos d WHERE d.id = p_demo_id AND d.retailer_id = p_retailer_id;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found'::text, NULL::integer, NULL::uuid, NULL::text; RETURN; END IF;
  IF v_bid IS NULL THEN RETURN QUERY SELECT false, 'no_booking'::text, NULL::integer, NULL::uuid, NULL::text; RETURN; END IF;
  SELECT * INTO v_b FROM bookings b WHERE b.id = v_bid FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'no_booking'::text, NULL::integer, NULL::uuid, NULL::text; RETURN; END IF;
  SELECT * INTO v_d FROM demos d WHERE d.id = p_demo_id FOR UPDATE;
  IF v_d.booking_id IS DISTINCT FROM v_bid OR v_d.retailer_id IS DISTINCT FROM p_retailer_id THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::integer, NULL::uuid, NULL::text; RETURN;
  END IF;
  IF v_b.retailer_id IS DISTINCT FROM p_retailer_id THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::integer, NULL::uuid, NULL::text; RETURN;
  END IF;
  IF coalesce(v_d.status, '') NOT IN ('confirmed', 'scheduled') OR coalesce(v_b.status, 'pending') NOT IN ('pending', 'confirmed') THEN
    RETURN QUERY SELECT false, 'not_active'::text, NULL::integer, v_bid, NULL::text; RETURN;
  END IF;
  -- RM-1 (0095): no schedule change while a declined / lapsed move is being settled.
  IF v_b.pending_move_settlement IS NOT NULL OR v_b.cancellation_pending_at IS NOT NULL THEN   -- 0106: a recorded cancellation is a barrier too
    RETURN QUERY SELECT false, 'cancellation_pending'::text, NULL::integer, v_bid, NULL::text; RETURN;
  END IF;
  SELECT r.timezone INTO v_tz FROM retailers r WHERE r.id = p_retailer_id;
  IF p_new_date IS NULL OR p_new_date < (now() AT TIME ZONE coalesce(nullif(v_tz, ''), 'America/Los_Angeles'))::date THEN
    RETURN QUERY SELECT false, 'date_in_past'::text, NULL::integer, v_bid, NULL::text; RETURN;
  END IF;
  v_time := coalesce(nullif(btrim(p_new_time), ''), v_b.demo_time, v_d.demo_time);
  UPDATE demos
     SET reschedule_to_date = p_new_date, reschedule_to_time = v_time, reschedule_requested_at = now()
   WHERE id = p_demo_id;
  UPDATE bookings
     SET reschedule_proposal_version = reschedule_proposal_version + 1
   WHERE id = v_bid
  RETURNING reschedule_proposal_version INTO v_ver;
  RETURN QUERY SELECT true, NULL::text, v_ver, v_bid, v_time;
END $function$

CREATE OR REPLACE FUNCTION public.provision_verified_retailer(p_email text, p_store_name text, p_phone text DEFAULT NULL::text, p_contact_name text DEFAULT NULL::text, p_store_count integer DEFAULT NULL::integer)
 RETURNS TABLE(retailer_id uuid, slug text, session_id uuid, already boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text := lower(btrim(p_email));
  v_base  text;
  v_slug  text;
  v_rid   uuid;
  v_sid   uuid;
  v_try   int := 0;
  v_ex_id uuid;
  v_ex_slug text;
  -- clamp the store count to the same 1..999 range the signup stepper allows
  v_count int := CASE
                   WHEN p_store_count IS NULL THEN NULL
                   WHEN p_store_count < 1   THEN 1
                   WHEN p_store_count > 999 THEN 999
                   ELSE p_store_count
                 END;
BEGIN
  IF v_email IS NULL OR v_email = '' THEN RAISE EXCEPTION 'email required'; END IF;
  -- Idempotency: this email already owns a retailer -> return it (no session minted here)
  SELECT r.id, r.slug INTO v_ex_id, v_ex_slug
  FROM retailers r WHERE lower(btrim(r.billing_email)) = v_email LIMIT 1;
  IF FOUND THEN
    retailer_id := v_ex_id; slug := v_ex_slug; session_id := NULL; already := true; RETURN NEXT; RETURN;
  END IF;
  -- Unique slug
  v_base := regexp_replace(lower(coalesce(nullif(btrim(p_store_name), ''), split_part(v_email, '@', 1))), '[^a-z0-9]+', '-', 'g');
  v_base := trim(both '-' from v_base);
  IF v_base = '' THEN v_base := 'store'; END IF;
  v_slug := v_base;
  WHILE EXISTS (SELECT 1 FROM retailers WHERE retailers.slug = v_slug) AND v_try < 50 LOOP
    v_try := v_try + 1;
    v_slug := v_base || '-' || (floor(random() * 900) + 100)::int;
  END LOOP;
  INSERT INTO retailers (slug, name, billing_tier, billing_email, phone, expected_locations)
    VALUES (v_slug, coalesce(nullif(btrim(p_store_name), ''), v_slug), 'solo', v_email,
            nullif(btrim(coalesce(p_phone, '')), ''), v_count)
    RETURNING id INTO v_rid;
  INSERT INTO settings (retailer_id, demo_fee, demo_duration, advance_booking_days)
    VALUES (v_rid, 30, 180, 60);
  -- owner membership (canonical source of authority) — now carries the owner's name
  INSERT INTO retailer_admins (retailer_id, email, email_normalized, role, name)
    VALUES (v_rid, v_email, v_email, 'admin', nullif(btrim(coalesce(p_contact_name, '')), ''));
  v_sid := gen_random_uuid();
  INSERT INTO admin_sessions (session_id, retailer_id, email, expires_at)
    VALUES (v_sid, v_rid, v_email, now() + interval '30 days');
  retailer_id := v_rid; slug := v_slug; session_id := v_sid; already := false; RETURN NEXT;
END $function$

CREATE OR REPLACE FUNCTION public.record_fulfillment(p_booking_id uuid, p_owner text, p_generation integer, p_demo boolean, p_emails boolean, p_done boolean, p_err text, p_max_attempts integer DEFAULT 6)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v booking_fulfillments%ROWTYPE; v_case uuid; v_demo boolean; v_emails boolean; v_cap integer;
BEGIN
  IF p_booking_id IS NULL OR p_owner IS NULL OR p_generation IS NULL THEN
    RETURN jsonb_build_object('outcome', 'stale', 'reason', 'missing_claim');
  END IF;
  SELECT * INTO v FROM booking_fulfillments WHERE booking_id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'stale', 'reason', 'no_row'); END IF;
  -- The claim must still be the CURRENT one: same lease owner, same generation, still pending.
  IF v.lease_owner IS DISTINCT FROM p_owner OR v.generation IS DISTINCT FROM p_generation OR v.status <> 'pending' THEN
    RETURN jsonb_build_object('outcome', 'stale', 'reason',
      CASE WHEN v.status <> 'pending' THEN 'row_' || v.status
           WHEN v.generation IS DISTINCT FROM p_generation THEN 'generation_' || v.generation::text
           ELSE 'lease_' || coalesce(v.lease_owner, 'none') END,
      'generation', v.generation, 'status', v.status);
  END IF;
  v_demo := v.demo_created OR coalesce(p_demo, false);
  v_emails := v.emails_sent OR coalesce(p_emails, false);
  v_cap := greatest(1, coalesce(p_max_attempts, 6));
  IF coalesce(p_done, false) THEN
    UPDATE booking_fulfillments
       SET demo_created = v_demo, emails_sent = v_emails, status = 'done', completed_at = now(),
           last_error = coalesce(p_err, last_error), lease_owner = NULL, lease_expires_at = NULL
     WHERE booking_id = p_booking_id;
    RETURN jsonb_build_object('outcome', 'done', 'generation', v.generation, 'attempts', v.attempts);
  END IF;
  IF v.attempts >= v_cap THEN
    -- Legitimate exhaustion of THIS claim: park only this work and open its case, in this transaction.
    UPDATE booking_fulfillments
       SET demo_created = v_demo, emails_sent = v_emails, status = 'failed',
           last_error = coalesce(p_err, last_error, 'retry_cap_exhausted'), lease_owner = NULL, lease_expires_at = NULL
     WHERE booking_id = p_booking_id;
    v_case := _open_case('fulfillment_failed', 'fulfil:' || p_booking_id::text, coalesce(p_err, 'retry_cap_exhausted'),
                         v.payment_group_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                         jsonb_build_object('booking_id', p_booking_id, 'attempts', v.attempts, 'generation', v.generation,
                                            'demo_created', v_demo, 'emails_sent', v_emails));
    RETURN jsonb_build_object('outcome', 'exhausted', 'case_id', v_case, 'generation', v.generation, 'attempts', v.attempts);
  END IF;
  -- Progress on a still-live claim: keep what was done, release the lease for the next attempt.
  UPDATE booking_fulfillments
     SET demo_created = v_demo, emails_sent = v_emails, last_error = coalesce(p_err, last_error),
         lease_owner = NULL, lease_expires_at = NULL
   WHERE booking_id = p_booking_id;
  RETURN jsonb_build_object('outcome', 'progress', 'generation', v.generation, 'attempts', v.attempts);
END $function$

CREATE OR REPLACE FUNCTION public.record_payment_attempt_failure(p_session_id text, p_err text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_att record;
BEGIN
  SELECT * INTO v_att FROM payment_attempts WHERE stripe_checkout_session_id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_attempt'); END IF;
  UPDATE payment_attempts SET last_error = left(coalesce(p_err,'payment_failed'),300) WHERE id = v_att.id;
  RETURN jsonb_build_object('outcome','recorded');
END $function$

CREATE OR REPLACE FUNCTION public.record_settlement_leg(p_request_id uuid, p_leg text, p_stripe_id text, p_status text, p_amount integer, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_req record; v_cust text; v_tr text; v_fee text; v_done boolean; v_failed boolean; v_tr_ok boolean; v_fee_ok boolean;
BEGIN
  SELECT * INTO v_req FROM refund_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_request'); END IF;
  IF v_req.settlement_status = 'not_required' THEN RETURN jsonb_build_object('outcome','not_required'); END IF;
  IF p_status NOT IN ('succeeded','failed','not_required','pending') THEN RAISE EXCEPTION 'settlement_leg_bad_status %', p_status; END IF;
  IF p_leg = 'customer' THEN
    IF v_req.stripe_refund_id IS NOT NULL AND p_stripe_id IS NOT NULL AND v_req.stripe_refund_id <> p_stripe_id THEN RAISE EXCEPTION 'settlement_leg_conflict customer'; END IF;
    IF v_req.customer_refund_status = 'succeeded' AND p_status <> 'succeeded' THEN RAISE EXCEPTION 'settlement_leg_regress customer'; END IF;
    IF p_status = 'succeeded' AND (p_amount IS DISTINCT FROM v_req.amount OR lower(coalesce(p_currency,'')) <> lower(v_req.currency)) THEN RAISE EXCEPTION 'settlement_leg_mismatch customer'; END IF;
    UPDATE refund_requests SET customer_refund_status = p_status, stripe_refund_id = coalesce(stripe_refund_id, p_stripe_id) WHERE id = p_request_id;
  ELSIF p_leg = 'transfer_reversal' THEN
    IF v_req.stripe_transfer_reversal_id IS NOT NULL AND p_stripe_id IS NOT NULL AND v_req.stripe_transfer_reversal_id <> p_stripe_id THEN RAISE EXCEPTION 'settlement_leg_conflict transfer_reversal'; END IF;
    IF v_req.transfer_reversal_status = 'succeeded' AND p_status <> 'succeeded' THEN RAISE EXCEPTION 'settlement_leg_regress transfer_reversal'; END IF;
    IF p_status = 'succeeded' THEN
      IF p_stripe_id IS NULL THEN RAISE EXCEPTION 'settlement_leg_mismatch transfer_reversal id'; END IF;
      IF p_amount IS DISTINCT FROM v_req.expected_transfer_reversal_amount OR lower(coalesce(p_currency,'')) <> lower(v_req.currency) THEN RAISE EXCEPTION 'settlement_leg_mismatch transfer_reversal'; END IF;
    END IF;
    UPDATE refund_requests SET transfer_reversal_status = p_status, stripe_transfer_reversal_id = coalesce(stripe_transfer_reversal_id, p_stripe_id),
           transfer_reversal_amount = CASE WHEN p_status = 'succeeded' THEN p_amount ELSE transfer_reversal_amount END WHERE id = p_request_id;
  ELSIF p_leg = 'fee_refund' THEN
    IF v_req.stripe_fee_refund_id IS NOT NULL AND p_stripe_id IS NOT NULL AND v_req.stripe_fee_refund_id <> p_stripe_id THEN RAISE EXCEPTION 'settlement_leg_conflict fee_refund'; END IF;
    IF v_req.fee_refund_status IN ('succeeded','not_required') AND p_status NOT IN ('succeeded','not_required') THEN RAISE EXCEPTION 'settlement_leg_regress fee_refund'; END IF;
    IF p_status = 'not_required' AND coalesce(v_req.expected_fee_refund_amount,0) <> 0 THEN RAISE EXCEPTION 'settlement_leg_mismatch fee_refund not_required'; END IF;
    IF p_status = 'succeeded' THEN
      IF p_stripe_id IS NULL THEN RAISE EXCEPTION 'settlement_leg_mismatch fee_refund id'; END IF;
      IF p_amount IS DISTINCT FROM v_req.expected_fee_refund_amount OR lower(coalesce(p_currency,'')) <> lower(v_req.currency) THEN RAISE EXCEPTION 'settlement_leg_mismatch fee_refund'; END IF;
    END IF;
    UPDATE refund_requests SET fee_refund_status = p_status, stripe_fee_refund_id = coalesce(stripe_fee_refund_id, p_stripe_id),
           fee_refund_amount = CASE WHEN p_status = 'succeeded' THEN p_amount WHEN p_status = 'not_required' THEN 0 ELSE fee_refund_amount END WHERE id = p_request_id;
  ELSE
    RAISE EXCEPTION 'unknown_leg %', p_leg;
  END IF;
  SELECT * INTO v_req FROM refund_requests WHERE id = p_request_id;
  v_cust := v_req.customer_refund_status; v_tr := v_req.transfer_reversal_status; v_fee := v_req.fee_refund_status;
  v_failed := (v_cust = 'failed' OR v_tr = 'failed' OR v_fee = 'failed');
  v_tr_ok := (v_tr = 'succeeded' AND v_req.transfer_reversal_amount = v_req.expected_transfer_reversal_amount);
  v_fee_ok := (v_fee = 'succeeded' AND v_req.fee_refund_amount = v_req.expected_fee_refund_amount)
           OR (v_fee = 'not_required' AND coalesce(v_req.expected_fee_refund_amount,0) = 0);
  v_done := (v_cust = 'succeeded' AND v_tr_ok AND v_fee_ok);
  IF v_failed THEN
    UPDATE refund_requests SET settlement_status = 'exception' WHERE id = p_request_id;
    INSERT INTO reconciliation_cases(kind, refund_request_id, payment_group_id, reason, details)
      SELECT 'settlement_exception', p_request_id, a.payment_group_id, 'settlement_leg_failed',
             jsonb_build_object('customer',v_cust,'transfer_reversal',v_tr,'fee_refund',v_fee)
      FROM payment_allocations a WHERE a.id = v_req.payment_allocation_id;
    RETURN jsonb_build_object('outcome','settlement_exception');
  ELSIF v_done THEN
    UPDATE refund_requests SET settlement_status = 'complete', settlement_lease_owner = NULL, settlement_lease_expires_at = NULL,
           settlement_next_attempt_at = NULL, settlement_last_error = NULL WHERE id = p_request_id AND settlement_status <> 'complete';
    RETURN jsonb_build_object('outcome','settlement_complete');
  END IF;
  RETURN jsonb_build_object('outcome','leg_recorded','settlement_status',v_req.settlement_status,'transfer_reversal_status',v_tr,'fee_refund_status',v_fee);
END $function$

CREATE OR REPLACE FUNCTION public.redeem_brand_signup(p_email text, p_code_hash text, p_session_token text, p_session_days integer DEFAULT 30, p_max_attempts integer DEFAULT 6)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email    text := lower(btrim(p_email));
  v_ch       email_verifications;
  v_brand_id uuid;
  v_created  boolean := false;
  v_payload  jsonb;
  v_expires  timestamptz;
  v_m        brand_members%ROWTYPE;
BEGIN
  IF v_email = '' OR coalesce(p_code_hash,'') = '' OR coalesce(p_session_token,'') = '' THEN
    RETURN jsonb_build_object('outcome','invalid');
  END IF;
  SELECT * INTO v_ch FROM email_verifications
   WHERE lower(email) = v_email AND purpose = 'brand_signup' AND consumed_at IS NULL
   ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','already_used'); END IF;
  IF v_ch.expires_at <= now() THEN RETURN jsonb_build_object('outcome','expired'); END IF;
  IF v_ch.attempts >= p_max_attempts THEN RETURN jsonb_build_object('outcome','too_many_attempts'); END IF;
  IF v_ch.code_hash <> p_code_hash THEN
    UPDATE email_verifications SET attempts = attempts + 1 WHERE id = v_ch.id;
    RETURN jsonb_build_object('outcome','invalid');
  END IF;
  UPDATE email_verifications SET consumed_at = now() WHERE id = v_ch.id;
  v_payload := coalesce(v_ch.payload, '{}'::jsonb);
  SELECT id INTO v_brand_id FROM brands WHERE lower(email) = v_email LIMIT 1;
  IF v_brand_id IS NOT NULL THEN
    UPDATE brands SET
      company_name = CASE WHEN coalesce(btrim(company_name),'') = '' THEN coalesce(nullif(btrim(v_payload->>'company_name'),''), company_name) ELSE company_name END,
      contact_name = CASE WHEN coalesce(btrim(contact_name),'') = '' THEN coalesce(nullif(btrim(v_payload->>'contact_name'),''), contact_name) ELSE contact_name END,
      phone        = CASE WHEN coalesce(btrim(phone),'') = '' THEN coalesce(nullif(btrim(v_payload->>'phone'),''), phone) ELSE phone END,
      is_verified  = true,
      updated_at   = now()
    WHERE id = v_brand_id;
    UPDATE brand_members SET role = 'owner' WHERE brand_id = v_brand_id AND lower(email) = v_email AND role IS DISTINCT FROM 'owner';
    INSERT INTO brand_members (brand_id, email, name, role)
    VALUES (v_brand_id, v_email, nullif(btrim(v_payload->>'contact_name'), ''), 'owner')
    ON CONFLICT DO NOTHING;
  ELSE
    SELECT * INTO v_m FROM brand_members WHERE lower(email) = v_email AND status IN ('pending','accepted') ORDER BY created_at DESC LIMIT 1;
    IF FOUND AND v_m.status = 'pending' THEN
      -- BK-3: a pending invitation is accepted only through booker_accept, after the explicit acceptance step.
      RETURN jsonb_build_object('outcome','invite_pending', 'brand_id', v_m.brand_id);
    ELSIF FOUND AND v_m.status = 'accepted' AND v_m.role = 'booker' THEN
      v_brand_id := v_m.brand_id;    -- an accepted booker signs in to its brand; the brand itself is not touched
    ELSE
      INSERT INTO brands (email, company_name, contact_name, phone, is_verified)
      VALUES (v_email, coalesce(nullif(btrim(v_payload->>'company_name'), ''), v_email), nullif(btrim(v_payload->>'contact_name'), ''), nullif(btrim(v_payload->>'phone'), ''), true)
      RETURNING id INTO v_brand_id;
      v_created := true;
      BEGIN
        INSERT INTO brand_members (brand_id, email, name, role)
        VALUES (v_brand_id, v_email, nullif(btrim(v_payload->>'contact_name'), ''), 'owner');
      EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION 'email_in_use' USING errcode = 'unique_violation';
      END;
    END IF;
  END IF;
  v_expires := now() + make_interval(days => greatest(1, coalesce(p_session_days, 30)));
  INSERT INTO brand_account_sessions (brand_id, session_token, email, expires_at)
  VALUES (v_brand_id, p_session_token, v_email, v_expires);
  RETURN jsonb_build_object('outcome','ok', 'brand_id', v_brand_id, 'expires_at', v_expires, 'created', v_created);
END $function$

CREATE OR REPLACE FUNCTION public.refund_reserve_cas(p_booking_id uuid, p_op_key text, p_actor text, p_reason text, p_booking_expect text[] DEFAULT NULL::text[], p_booking_set text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alloc record; v_grp record; v_bk record; v_op record; v_req record;
  v_remaining int; v_fee_portion int; v_opid uuid; v_rid uuid; v_key text; v_keeps boolean; v_fee_prior int; v_strategy int;
BEGIN
  -- lock booking (for the optional source-status CAS) and allocation/group
  SELECT * INTO v_bk FROM bookings WHERE id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_booking'); END IF;
  SELECT a.*, g.stripe_payment_intent_id AS pi, g.stripe_charge_id AS charge_id,
         g.platform_keeps_all AS keeps, g.connect_account_id AS connect,
         g.stripe_transfer_id AS transfer_id, g.stripe_application_fee_id AS app_fee_id, g.currency AS gcur
    INTO v_alloc
    FROM payment_allocations a JOIN payment_groups g ON g.id = a.payment_group_id
    WHERE a.booking_id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_allocation','requires_review',true); END IF;
  v_keeps := v_alloc.keeps;
  -- idempotent: an existing non-terminal operation for this op_key returns its latest request
  SELECT * INTO v_op FROM refund_operations WHERE op_key = p_op_key FOR UPDATE;
  IF FOUND AND v_op.status IN ('open','requires_review') THEN
    SELECT * INTO v_req FROM refund_requests WHERE parent_operation_id = v_op.id ORDER BY attempt_version DESC LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object('outcome','existing','refund_request_id',v_req.id,'refund_operation_id',v_op.id,
        'idempotency_key',v_req.stripe_idempotency_key,'payment_intent',v_alloc.pi,'charge_id',v_alloc.charge_id,
        'keeps_all',v_keeps,'connect_account_id',v_alloc.connect,'amount',v_req.amount,
        'expected_customer_amount',v_req.expected_customer_amount,
        'expected_transfer_reversal_amount',v_req.expected_transfer_reversal_amount,
        'expected_fee_refund_amount',v_req.expected_fee_refund_amount,'settlement_status',v_req.settlement_status,
        'settlement_strategy',v_req.settlement_strategy,'fee_refund_idempotency_key',v_req.fee_refund_idempotency_key);
    END IF;
  END IF;
  IF v_alloc.pi IS NULL THEN RETURN jsonb_build_object('outcome','not_charged','requires_review',true); END IF;
  v_remaining := v_alloc.customer_amount - v_alloc.refunded_amount - v_alloc.reserved_refund_amount;
  IF v_remaining <= 0 THEN RETURN jsonb_build_object('outcome','nothing_refundable'); END IF;
  -- optional source-status CAS (P1-3): only transition the booking if it is in an expected state
  IF p_booking_expect IS NOT NULL THEN
    IF NOT (v_bk.status = ANY(p_booking_expect)) THEN
      RETURN jsonb_build_object('outcome','booking_state_conflict','status',v_bk.status);
    END IF;
    IF p_booking_set IS NOT NULL THEN UPDATE bookings SET status = p_booking_set WHERE id = p_booking_id; END IF;
  END IF;
  -- exact settlement legs (per THIS allocation; never proportional across the combined charge). 0117 (Codex CC-1):
  -- the fee portion is defined on CUMULATIVE entitlement, so repeated partial refunds of one allocation can never
  -- return more than the allocation's platform fee and the final remainder lands exactly: this request's fee refund
  -- is round(fee * (already refunded + reserved + this refund) / customer) minus the fee already expected by every
  -- live or succeeded request on this allocation. A zero result is a satisfied leg (no provider request).
  SELECT coalesce(sum(expected_fee_refund_amount),0) INTO v_fee_prior FROM refund_requests
    WHERE payment_allocation_id = v_alloc.id AND status NOT IN ('failed_terminal','failed','canceled');
  v_fee_portion := greatest(0, round(v_alloc.platform_fee_amount::numeric * (v_alloc.refunded_amount + v_alloc.reserved_refund_amount + v_remaining) / v_alloc.customer_amount)::int - v_fee_prior);
  -- 0117: new connected requests use settlement strategy 2 (explicit, allocation-derived application fee refund
  -- through the fee-refund API with its own durable idempotency key); keeps-all requests carry no strategy.
  v_strategy := CASE WHEN v_keeps THEN 1 ELSE 2 END;
  -- parent operation (stable) + reserve
  IF v_op.id IS NULL THEN
    INSERT INTO refund_operations(op_key, booking_id, payment_allocation_id, amount, currency, actor, reason, status)
      VALUES (p_op_key, p_booking_id, v_alloc.id, v_remaining, v_alloc.gcur, p_actor, p_reason, 'open')
      RETURNING id INTO v_opid;
  ELSE
    v_opid := v_op.id;
    UPDATE refund_operations SET status = 'open' WHERE id = v_opid AND status = 'requires_review';
  END IF;
  UPDATE payment_allocations SET reserved_refund_amount = reserved_refund_amount + v_remaining WHERE id = v_alloc.id;
  v_rid := gen_random_uuid();
  v_key := 'rf-' || v_rid::text;    -- unique per attempt; safe to replay at Stripe
  INSERT INTO refund_requests(
      id, parent_operation_id, attempt_version, payment_allocation_id, booking_id, amount, currency,
      actor, reason, op_key, status, stripe_idempotency_key, next_attempt_at,
      expected_customer_amount, expected_transfer_reversal_amount, expected_fee_refund_amount,
      customer_refund_status, settlement_status, canonical_request_hash, request_schema_version,
      settlement_strategy, fee_refund_idempotency_key)
    VALUES (
      v_rid, v_opid, 1, v_alloc.id, p_booking_id, v_remaining, v_alloc.gcur,
      p_actor, p_reason, p_op_key, 'reserved', v_key, now(),
      v_remaining, CASE WHEN v_keeps THEN NULL ELSE v_remaining END, CASE WHEN v_keeps THEN NULL ELSE v_fee_portion END,
      'pending', CASE WHEN v_keeps THEN 'not_required' ELSE 'pending' END,
      md5(coalesce(v_alloc.pi,'') || ':' || v_remaining || ':' || v_alloc.gcur || ':' || coalesce(v_alloc.connect,'keepsall')), 1,
      v_strategy, CASE WHEN v_keeps THEN NULL ELSE 'fr-' || v_rid::text END);
  RETURN jsonb_build_object('outcome','reserved','refund_request_id',v_rid,'refund_operation_id',v_opid,
    'idempotency_key',v_key,'payment_intent',v_alloc.pi,'charge_id',v_alloc.charge_id,
    'keeps_all',v_keeps,'connect_account_id',v_alloc.connect,'amount',v_remaining,
    'expected_customer_amount',v_remaining,
    'expected_transfer_reversal_amount', CASE WHEN v_keeps THEN NULL ELSE v_remaining END,
    'expected_fee_refund_amount', CASE WHEN v_keeps THEN NULL ELSE v_fee_portion END,
    'settlement_status', CASE WHEN v_keeps THEN 'not_required' ELSE 'pending' END,
    'settlement_strategy', v_strategy, 'fee_refund_idempotency_key', CASE WHEN v_keeps THEN NULL ELSE 'fr-' || v_rid::text END);
END $function$

CREATE OR REPLACE FUNCTION public.register_payment_attempt(p_group_id uuid, p_session_id text, p_payment_intent text, p_hash text, p_schema integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_open record; v_id uuid; v_gstatus text; v_sum int; v_total int;
BEGIN
  SELECT status, total_customer_amount INTO v_gstatus, v_total FROM payment_groups WHERE id = p_group_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'no_group %', p_group_id; END IF;
  IF v_gstatus NOT IN ('pending','session_created') THEN RAISE EXCEPTION 'group_not_attemptable %', v_gstatus; END IF;
  SELECT coalesce(sum(customer_amount),0) INTO v_sum FROM payment_allocations WHERE payment_group_id = p_group_id;
  IF v_sum <> v_total OR v_sum = 0 THEN RAISE EXCEPTION 'group_sum_mismatch % <> %', v_sum, v_total; END IF;
  SELECT * INTO v_open FROM payment_attempts WHERE payment_group_id = p_group_id AND status = 'open' FOR UPDATE;
  IF FOUND THEN
    IF v_open.stripe_checkout_session_id IS DISTINCT FROM p_session_id OR v_open.canonical_request_hash IS DISTINCT FROM p_hash THEN
      RAISE EXCEPTION 'attempt_in_progress';
    END IF;
    RETURN v_open.id;
  END IF;
  INSERT INTO payment_attempts(payment_group_id, stripe_checkout_session_id, stripe_payment_intent_id, canonical_request_hash, request_schema_version, status)
    VALUES (p_group_id, p_session_id, p_payment_intent, p_hash, coalesce(p_schema,1), 'open')
    RETURNING id INTO v_id;
  -- mirror the LATEST session on the group for display; attempts remain authoritative for binding
  UPDATE payment_groups SET status = 'session_created' WHERE id = p_group_id;
  UPDATE payment_groups SET stripe_checkout_session_id = p_session_id
    WHERE id = p_group_id AND stripe_checkout_session_id IS NULL;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.request_payment_receipt_resend(p_group_id uuid, p_brand_id uuid, p_requested_by text, p_cooldown_seconds integer DEFAULT 600)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_grp record;
  v_brand record;
  v_member record;
  v_recipient_id uuid;
  v_recipient_email text;
  v_last timestamptz;
  v_wait integer;
  v_now timestamptz := now();
  v_cooldown interval := make_interval(secs => greatest(coalesce(p_cooldown_seconds, 600), 1));
  v_event_id uuid;
  v_email text := lower(trim(coalesce(p_requested_by, '')));
BEGIN
  IF p_group_id IS NULL OR p_brand_id IS NULL THEN RETURN jsonb_build_object('outcome', 'invalid'); END IF;
  -- Serialize every request for this group. Transaction-scoped: released at commit/rollback.
  PERFORM pg_advisory_xact_lock(hashtext('payment_receipt_resend:' || p_group_id::text));
  SELECT id, brand_id, retailer_id, status INTO v_grp FROM payment_groups WHERE id = p_group_id AND brand_id = p_brand_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'not_found'); END IF;
  IF v_grp.status NOT IN ('paid', 'partially_refunded', 'refunded') THEN
    RETURN jsonb_build_object('outcome', 'not_settled', 'status', v_grp.status);
  END IF;
  -- The requester must be a current account contact of this brand: the account email, or a member.
  SELECT id, email INTO v_brand FROM brands WHERE id = p_brand_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome', 'not_found'); END IF;
  IF v_email <> '' AND lower(trim(coalesce(v_brand.email, ''))) = v_email THEN
    v_recipient_id := v_brand.id; v_recipient_email := v_brand.email;
  ELSE
    SELECT id, email INTO v_member FROM brand_members WHERE brand_id = p_brand_id AND lower(trim(email)) = v_email ORDER BY created_at ASC LIMIT 1;
    IF FOUND THEN v_recipient_id := v_member.id; v_recipient_email := v_member.email;
    ELSE RETURN jsonb_build_object('outcome', 'requester_not_a_contact'); END IF;
  END IF;
  -- Rolling cooldown on database time, resend events only (the automatic receipt never counts).
  SELECT max(created_at) INTO v_last FROM notification_events
   WHERE kind = 'payment_receipt' AND transition_id LIKE p_group_id::text || ':resend:%' AND created_at > v_now - v_cooldown;
  IF v_last IS NOT NULL THEN
    v_wait := greatest(1, ceil(extract(epoch FROM (v_last + v_cooldown - v_now)))::integer);
    RETURN jsonb_build_object('outcome', 'throttled', 'retry_after_seconds', v_wait);
  END IF;
  INSERT INTO notification_events (retailer_id, booking_id, brand_id, kind, transition_id, payload)
  VALUES (v_grp.retailer_id, NULL, v_grp.brand_id, 'payment_receipt',
          p_group_id::text || ':resend:' || (extract(epoch FROM clock_timestamp()) * 1000)::bigint::text,
          jsonb_build_object('payment_group_id', p_group_id, 'resend', true,
                             'requested_by', v_recipient_email, 'requested_recipient_id', v_recipient_id, 'requested_at', v_now))
  RETURNING id INTO v_event_id;
  RETURN jsonb_build_object('outcome', 'queued', 'event_id', v_event_id, 'to', v_recipient_email, 'recipient_id', v_recipient_id);
END $function$

CREATE OR REPLACE FUNCTION public.reserve_refund(p_booking_id uuid, p_amount integer, p_actor text, p_reason text, p_policy text, p_op_key text)
 RETURNS TABLE(refund_request_id uuid, idempotency_key text, stripe_payment_intent_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_alloc record; v_remaining int; v_rid uuid; v_key text; v_ex record;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'amount must be positive'; END IF;
  -- idempotent: same operation returns the existing request
  IF p_op_key IS NOT NULL THEN
    SELECT rr.id, rr.stripe_idempotency_key, g.stripe_payment_intent_id AS pi INTO v_ex
    FROM refund_requests rr JOIN payment_allocations a ON a.id = rr.payment_allocation_id JOIN payment_groups g ON g.id = a.payment_group_id
    WHERE rr.op_key = p_op_key AND rr.status NOT IN ('failed','canceled') LIMIT 1;
    IF FOUND THEN RETURN QUERY SELECT v_ex.id, v_ex.stripe_idempotency_key, v_ex.pi; RETURN; END IF;
  END IF;
  SELECT a.*, g.stripe_payment_intent_id AS pi, g.status AS gstatus
    INTO v_alloc FROM payment_allocations a JOIN payment_groups g ON g.id = a.payment_group_id
    WHERE a.booking_id = p_booking_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'no allocation for booking'; END IF;
  IF v_alloc.pi IS NULL OR v_alloc.gstatus NOT IN ('paid','partially_refunded') THEN RAISE EXCEPTION 'group not in a refundable state'; END IF;
  v_remaining := v_alloc.customer_amount - v_alloc.refunded_amount - v_alloc.reserved_refund_amount;
  IF p_amount > v_remaining THEN RAISE EXCEPTION 'amount exceeds refundable (% > %)', p_amount, v_remaining; END IF;
  UPDATE payment_allocations SET reserved_refund_amount = reserved_refund_amount + p_amount WHERE id = v_alloc.id;
  v_rid := gen_random_uuid(); v_key := 'demohub-refund-v1:' || v_rid::text;
  INSERT INTO refund_requests(id, payment_allocation_id, booking_id, amount, actor, reason, policy_decision, status, stripe_idempotency_key, op_key)
    VALUES (v_rid, v_alloc.id, p_booking_id, p_amount, p_actor, p_reason, p_policy, 'reserved', v_key, p_op_key);
  RETURN QUERY SELECT v_rid, v_key, v_alloc.pi;
END $function$

CREATE OR REPLACE FUNCTION public.resolve_calendar_token(p_token uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_brand uuid;
BEGIN
  SELECT brand_id INTO v_brand FROM brand_calendar_tokens
   WHERE token = p_token AND revoked_at IS NULL;
  IF v_brand IS NULL THEN RETURN NULL; END IF;
  UPDATE brand_calendar_tokens SET last_used_at = now() WHERE token = p_token;
  RETURN v_brand;
END $function$

CREATE OR REPLACE FUNCTION public.resolve_refund_adopt(p_op_key text, p_operator text, p_retailer_id uuid, p_refund_id text, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_op record; v_req record; v_alloc record;
BEGIN
  IF p_operator IS NULL OR p_refund_id IS NULL THEN RAISE EXCEPTION 'operator_and_refund_required'; END IF;
  SELECT * INTO v_op FROM refund_operations WHERE op_key = p_op_key FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_operation'); END IF;
  SELECT a.*, g.retailer_id AS rid INTO v_alloc
    FROM payment_allocations a JOIN payment_groups g ON g.id = a.payment_group_id
   WHERE a.id = v_op.payment_allocation_id;
  IF p_retailer_id IS NULL OR v_alloc.rid <> p_retailer_id THEN
    RETURN jsonb_build_object('outcome','forbidden','reason','operation_belongs_to_another_retailer');
  END IF;
  SELECT * INTO v_req FROM refund_requests
   WHERE parent_operation_id = v_op.id AND status NOT IN ('superseded','canceled')
   ORDER BY attempt_version DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_request'); END IF;
  IF v_req.stripe_refund_id IS NOT NULL AND v_req.stripe_refund_id <> p_refund_id THEN
    RETURN jsonb_build_object('outcome','conflict','reason','request_already_bound_to_other_refund');
  END IF;
  UPDATE refund_requests SET stripe_refund_id = p_refund_id,
         status = CASE WHEN status = 'requires_review' THEN 'submitted' ELSE status END,
         next_attempt_at = now()
   WHERE id = v_req.id;
  UPDATE refund_operations SET status = 'open' WHERE id = v_op.id AND status = 'requires_review';
  INSERT INTO refund_review_actions(refund_operation_id, refund_request_id, action, operator_email, retailer_id, stripe_evidence)
    VALUES (v_op.id, v_req.id, 'adopt', p_operator, p_retailer_id, p_evidence);
  UPDATE reconciliation_cases SET status = 'resolved', resolved_by = p_operator, resolved_at = now()
   WHERE refund_request_id = v_req.id AND status <> 'resolved';
  RETURN jsonb_build_object('outcome','adopted','refund_request_id',v_req.id,'stripe_refund_id',p_refund_id);
END $function$

CREATE OR REPLACE FUNCTION public.resolve_refund_replace(p_op_key text, p_operator text, p_retailer_id uuid, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_op record; v_old record; v_alloc record; v_ver int; v_rid uuid; v_key text; v_amount int; v_keeps boolean; v_fee int;
BEGIN
  IF p_operator IS NULL THEN RAISE EXCEPTION 'operator_required'; END IF;
  SELECT * INTO v_op FROM refund_operations WHERE op_key = p_op_key FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_operation'); END IF;
  IF v_op.status NOT IN ('failed','requires_review') THEN
    RETURN jsonb_build_object('outcome','not_replaceable','status',v_op.status);
  END IF;
  SELECT a.*, g.retailer_id AS rid, g.stripe_payment_intent_id AS pi, g.platform_keeps_all AS keeps,
         g.connect_account_id AS connect, g.currency AS gcur
    INTO v_alloc FROM payment_allocations a JOIN payment_groups g ON g.id = a.payment_group_id
   WHERE a.id = v_op.payment_allocation_id FOR UPDATE;
  IF p_retailer_id IS NULL OR v_alloc.rid <> p_retailer_id THEN
    RETURN jsonb_build_object('outcome','forbidden','reason','operation_belongs_to_another_retailer');
  END IF;
  v_keeps := v_alloc.keeps;
  -- the parked request whose reservation we are taking over
  SELECT * INTO v_old FROM refund_requests
   WHERE parent_operation_id = v_op.id AND status IN ('requires_review','failed_retryable','reserved','submitted','pending','requires_action')
   ORDER BY attempt_version DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_parked_request'); END IF;
  IF v_old.stripe_refund_id IS NOT NULL THEN
    RETURN jsonb_build_object('outcome','refused','reason','request_has_stripe_refund_adopt_instead','stripe_refund_id',v_old.stripe_refund_id);
  END IF;
  v_amount := v_old.amount;
  -- release EXACTLY the old reservation, asserting it is actually held (never clamp)
  IF v_alloc.reserved_refund_amount < v_amount THEN
    RETURN jsonb_build_object('outcome','contradiction','reason','reservation_underflow',
                              'reserved',v_alloc.reserved_refund_amount,'expected',v_amount);
  END IF;
  UPDATE payment_allocations SET reserved_refund_amount = reserved_refund_amount - v_amount WHERE id = v_alloc.id;
  UPDATE refund_requests SET status = 'superseded', last_error = 'superseded_by_operator_replacement' WHERE id = v_old.id;
  -- re-reserve for the replacement
  UPDATE payment_allocations SET reserved_refund_amount = reserved_refund_amount + v_amount WHERE id = v_alloc.id;
  SELECT coalesce(max(attempt_version),1) + 1 INTO v_ver FROM refund_requests WHERE parent_operation_id = v_op.id;
  v_fee := round(v_alloc.platform_fee_amount::numeric * v_amount / v_alloc.customer_amount)::int;
  v_rid := gen_random_uuid(); v_key := 'rf-' || v_rid::text;
  INSERT INTO refund_requests(
      id, parent_operation_id, attempt_version, payment_allocation_id, booking_id, amount, currency,
      actor, reason, op_key, status, stripe_idempotency_key, next_attempt_at,
      expected_customer_amount, expected_transfer_reversal_amount, expected_fee_refund_amount,
      customer_refund_status, settlement_status, canonical_request_hash, request_schema_version)
    VALUES (v_rid, v_op.id, v_ver, v_alloc.id, v_op.booking_id, v_amount, v_alloc.gcur,
      p_operator, 'operator_authorized_replacement', p_op_key, 'reserved', v_key, now(),
      v_amount, CASE WHEN v_keeps THEN NULL ELSE v_amount END, CASE WHEN v_keeps THEN NULL ELSE v_fee END,
      'pending', CASE WHEN v_keeps THEN 'not_required' ELSE 'pending' END,
      md5(coalesce(v_alloc.pi,'') || ':' || v_amount || ':' || v_alloc.gcur || ':' || coalesce(v_alloc.connect,'keepsall')), 1);
  UPDATE refund_operations SET status = 'open' WHERE id = v_op.id;
  INSERT INTO refund_review_actions(refund_operation_id, refund_request_id, action, operator_email, retailer_id, stripe_evidence)
    VALUES (v_op.id, v_rid, 'replace', p_operator, p_retailer_id, p_evidence);
  UPDATE reconciliation_cases SET status = 'resolved', resolved_by = p_operator, resolved_at = now()
   WHERE refund_request_id = v_old.id AND status <> 'resolved';
  RETURN jsonb_build_object('outcome','replacement_created','refund_request_id',v_rid,
    'attempt_version',v_ver,'idempotency_key',v_key,'amount',v_amount,'superseded_request_id',v_old.id);
END $function$

CREATE OR REPLACE FUNCTION public.respond_booking_move(p_move_id uuid, p_brand_id uuid, p_decision text, p_actor text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, reason text, booking_id uuid, retailer_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_m booking_moves%ROWTYPE;
  v_b bookings%ROWTYPE;
  v_now timestamptz;
BEGIN
  IF p_decision NOT IN ('confirm', 'decline') THEN
    RETURN QUERY SELECT false, 'invalid_decision'::text, NULL::uuid, NULL::uuid, NULL::text; RETURN;
  END IF;
  SELECT * INTO v_m FROM booking_moves m WHERE m.id = p_move_id;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found'::text, NULL::uuid, NULL::uuid, NULL::text; RETURN; END IF;
  SELECT * INTO v_b FROM bookings b WHERE b.id = v_m.booking_id FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found'::text, NULL::uuid, NULL::uuid, NULL::text; RETURN; END IF;
  SELECT * INTO v_m FROM booking_moves m WHERE m.id = p_move_id FOR UPDATE;
  v_now := clock_timestamp();   -- C4: the moment the locks are held, not the transaction's start
  IF p_brand_id IS NULL OR coalesce(v_b.brand_id, v_m.brand_id) IS DISTINCT FROM p_brand_id THEN
    RETURN QUERY SELECT false, 'forbidden'::text, v_m.booking_id, v_m.retailer_id, v_m.status; RETURN;
  END IF;
  IF v_m.status <> 'pending' THEN
    RETURN QUERY SELECT false, ('move_' || v_m.status)::text, v_m.booking_id, v_m.retailer_id, v_m.status; RETURN;
  END IF;
  IF coalesce(v_b.status, 'pending') NOT IN ('pending', 'confirmed') THEN
    RETURN QUERY SELECT false, 'booking_not_active'::text, v_m.booking_id, v_m.retailer_id, v_m.status; RETURN;
  END IF;
  IF v_b.schedule_revision IS DISTINCT FROM v_m.schedule_revision THEN
    UPDATE booking_moves SET status = 'superseded', updated_at = v_now WHERE id = p_move_id;
    RETURN QUERY SELECT false, 'move_superseded'::text, v_m.booking_id, v_m.retailer_id, 'superseded'::text; RETURN;
  END IF;
  IF v_now >= v_m.reconfirm_due_at THEN
    UPDATE booking_moves SET status = 'lapsed', lapsed_at = v_now, responded_at = v_now, responded_by = p_actor, updated_at = v_now WHERE id = p_move_id;
    UPDATE bookings SET pending_move_settlement = p_move_id WHERE id = v_m.booking_id AND pending_move_settlement IS NULL;
    IF p_decision = 'confirm' THEN
      RETURN QUERY SELECT false, 'move_lapsed'::text, v_m.booking_id, v_m.retailer_id, 'lapsed'::text; RETURN;
    END IF;
    RETURN QUERY SELECT true, NULL::text, v_m.booking_id, v_m.retailer_id, 'lapsed'::text; RETURN;
  END IF;
  IF p_decision = 'confirm' THEN
    UPDATE booking_moves SET status = 'confirmed', responded_at = v_now, responded_by = p_actor, updated_at = v_now WHERE id = p_move_id;
    RETURN QUERY SELECT true, NULL::text, v_m.booking_id, v_m.retailer_id, 'confirmed'::text; RETURN;
  END IF;
  UPDATE booking_moves SET status = 'declined', responded_at = v_now, responded_by = p_actor, updated_at = v_now WHERE id = p_move_id;
  UPDATE bookings SET pending_move_settlement = p_move_id WHERE id = v_m.booking_id AND pending_move_settlement IS NULL;
  RETURN QUERY SELECT true, NULL::text, v_m.booking_id, v_m.retailer_id, 'declined'::text;
END $function$

CREATE OR REPLACE FUNCTION public.retailer_admins_normalize_email()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.email_normalized := lower(btrim(NEW.email));
  IF NEW.role IS NOT NULL THEN NEW.role := lower(btrim(NEW.role)); END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.review_coi_verification(p_verification_id uuid, p_decision text, p_reviewer text, p_notes text DEFAULT NULL::text, p_expiry date DEFAULT NULL::date, p_brand_note text DEFAULT NULL::text)
 RETURNS coi_verifications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row        public.coi_verifications;
  v_brand      public.brands;
  v_brand_note text;
begin
  if p_decision is null or p_decision not in ('approved','rejected') then
    raise exception 'decision must be approved or rejected' using errcode = 'check_violation';
  end if;
  if p_reviewer is null or btrim(p_reviewer) = '' then
    raise exception 'reviewer is required' using errcode = 'check_violation';
  end if;
  if p_notes is not null and length(p_notes) > 2000 then
    raise exception 'review notes are limited to 2000 characters' using errcode = 'check_violation';
  end if;
  -- Release A §6: the note to the brand is emailed verbatim. Trim, normalise CRLF, and refuse
  -- (never strip) control characters other than newline so nothing is silently rewritten.
  v_brand_note := nullif(btrim(regexp_replace(p_brand_note, E'\r\n?', E'\n', 'g')), '');
  if v_brand_note is not null then
    if length(v_brand_note) > 1000 then
      raise exception 'brand_note_too_long: the note to the brand is limited to 1000 characters'
        using errcode = 'check_violation';
    end if;
    if v_brand_note ~ '[\x01-\x09\x0B\x0C\x0E-\x1F\x7F]' then
      raise exception 'brand_note_invalid: the note to the brand may only contain plain text and line breaks'
        using errcode = 'check_violation';
    end if;
  end if;
  -- P0-4: the reviewer-confirmed expiry is REQUIRED for an approval and must be in the future.
  -- Without it a brand could be approved-but-never-covered (coiCovered needs a date). The API also
  -- validates, but the RPC is the authority: no approval commits without a usable coverage date.
  if p_decision = 'approved' then
    if p_expiry is null then
      raise exception 'expiry_required: an approval must carry the certificate policy expiry'
        using errcode = 'check_violation';
    end if;
    if p_expiry <= current_date then
      raise exception 'expiry_in_past: the certificate expiry must be in the future'
        using errcode = 'check_violation';
    end if;
  end if;
  select * into v_row from coi_verifications where id = p_verification_id for update;
  if not found then
    raise exception 'verification record not found' using errcode = 'no_data_found';
  end if;
  if v_row.brand_id is null then
    raise exception 'verification record has no brand' using errcode = 'check_violation';
  end if;
  -- IMMUTABLE REVIEWS (0060). A decided record is history; a new decision requires a new upload.
  if v_row.review_decision is not null then
    raise exception 'already decided: this record was % and cannot be re-decided', v_row.review_decision
      using errcode = 'check_violation';
  end if;
  if v_row.removed_at is not null then
    raise exception 'removed record cannot be reviewed' using errcode = 'check_violation';
  end if;
  select * into v_brand from brands where id = v_row.brand_id for update;
  if not found then
    raise exception 'brand not found for this verification' using errcode = 'no_data_found';
  end if;
  if p_decision = 'approved' then
    -- STALE IS AN IDENTITY QUESTION (0060): approval is permitted only for the brand's CURRENT version.
    if v_row.superseded_at is not null then
      raise exception 'stale review: this version was superseded by a later upload'
        using errcode = 'check_violation';
    end if;
    if v_brand.current_coi_verification_id is distinct from v_row.id then
      raise exception 'stale review: this record is not the brand''s current certificate'
        using errcode = 'check_violation';
    end if;
    if v_row.storage_path is distinct from v_brand.default_coi_url then
      raise exception 'stale review: this record''s document is not the brand''s current document'
        using errcode = 'check_violation';
    end if;
  end if;
  update coi_verifications
     set review_decision = p_decision,
         reviewed_at     = now(),
         reviewed_by     = btrim(p_reviewer),
         review_notes    = p_notes,
         -- Release A §6: brand-facing note, committed with the status it explains. The 0074
         -- status trigger reads NEW.brand_note from this same row version.
         brand_note      = v_brand_note,
         status          = case when p_decision = 'approved' then 'approved' else 'rejected' end,
         -- P0-4: record the coverage expiry the owner actually confirmed on THIS record. On a
         -- rejection we leave whatever was parsed at upload; it does not gate anything.
         policy_expiry   = case when p_decision = 'approved' then p_expiry else policy_expiry end
   where id = p_verification_id
  returning * into v_row;
  -- Only the current version may move the brand's entitlement. Rejecting a superseded record is
  -- allowed for housekeeping but must not change what the brand is entitled to.
  if v_brand.current_coi_verification_id is not distinct from v_row.id then
    update brands
       set coi_verification_status = case when p_decision = 'approved' then 'approved' else 'rejected' end,
           -- P0-4: the reviewer-confirmed expiry commits in the SAME transaction as the decision.
           -- On approval it overwrites any brand-entered / AI-derived date; on rejection it is
           -- untouched (the brand is not covered anyway).
           default_coi_expires = case when p_decision = 'approved' then p_expiry else default_coi_expires end
     where id = v_row.brand_id;
  end if;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.schedule_group_ids_check(p_group_id uuid, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_g record; v_fee_sum int; v_next timestamptz; v_res text;
BEGIN
  IF p_group_id IS NULL THEN RAISE EXCEPTION 'group_required'; END IF;
  SELECT * INTO v_g FROM payment_groups WHERE id = p_group_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_group'); END IF;
  IF v_g.platform_keeps_all THEN RETURN jsonb_build_object('outcome','keeps_all_group'); END IF;
  IF p_outcome = 'zero_fee_complete' THEN
    SELECT coalesce(sum(platform_fee_amount),0) INTO v_fee_sum FROM payment_allocations WHERE payment_group_id = p_group_id;
    IF v_g.stripe_transfer_id IS NULL OR v_g.stripe_application_fee_id IS NOT NULL OR v_fee_sum <> 0 THEN
      RETURN jsonb_build_object('outcome','refused','reason','not_a_complete_zero_fee_group','transfer', v_g.stripe_transfer_id, 'fee_id', v_g.stripe_application_fee_id, 'fee_sum', v_fee_sum);
    END IF;
    v_res := 'zero_fee_complete'; v_next := NULL;
  ELSIF p_outcome = 'waiting' THEN v_next := now() + interval '5 minutes';
  ELSIF p_outcome = 'unresolved' THEN v_next := now() + interval '6 hours';
  ELSIF p_outcome = 'mismatch' THEN v_next := now() + interval '24 hours';
  ELSIF p_outcome = 'error' THEN v_next := now() + interval '5 minutes';
  ELSIF p_outcome = 'due_now' THEN v_next := NULL;
  ELSE RAISE EXCEPTION 'unknown_outcome %', p_outcome;
  END IF;
  UPDATE payment_groups SET settlement_ids_next_check_at = v_next, settlement_ids_resolution = v_res WHERE id = p_group_id;
  RETURN jsonb_build_object('outcome','scheduled','payment_group_id',p_group_id,'resolution',v_res,'next_check_at',v_next);
END $function$

CREATE OR REPLACE FUNCTION public.settlement_mark_exception(p_request_id uuid, p_reason text, p_details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_req record; v_case uuid; v_gid uuid;
BEGIN
  SELECT * INTO v_req FROM refund_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_request'); END IF;
  SELECT payment_group_id INTO v_gid FROM payment_allocations WHERE id = v_req.payment_allocation_id;
  UPDATE refund_requests SET settlement_status = 'exception', settlement_last_error = left(coalesce(p_reason,'settlement_exception'), 200),
         settlement_lease_owner = NULL, settlement_lease_expires_at = NULL WHERE id = p_request_id;
  v_case := _open_case('settlement_exception', 'settlement:' || p_request_id::text, coalesce(p_reason,'settlement_exception'),
                       v_gid, p_request_id, v_req.parent_operation_id, NULL, NULL, NULL, v_req.stripe_refund_id,
                       v_req.amount, v_req.currency, coalesce(p_details, '{}'::jsonb));
  RETURN jsonb_build_object('outcome','exception','case_id',v_case,'refund_request_id',p_request_id);
END $function$

CREATE OR REPLACE FUNCTION public.settlement_mark_fee_intent(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_req record;
BEGIN
  SELECT * INTO v_req FROM refund_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','no_request'); END IF;
  IF v_req.fee_refund_idempotency_key IS NULL THEN RETURN jsonb_build_object('outcome','no_key'); END IF;
  IF v_req.fee_refund_intent_at IS NULL THEN
    UPDATE refund_requests SET fee_refund_intent_at = now() WHERE id = p_request_id;
    RETURN jsonb_build_object('outcome','intent_recorded','first',true,'key',v_req.fee_refund_idempotency_key);
  END IF;
  RETURN jsonb_build_object('outcome','intent_recorded','first',false,'key',v_req.fee_refund_idempotency_key,'intent_at',v_req.fee_refund_intent_at);
END $function$

CREATE OR REPLACE FUNCTION public.signup_budget_take(p_bucket_key text, p_window_start timestamp with time zone, p_max integer)
 RETURNS TABLE(admitted boolean, count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  IF p_max IS NULL OR p_max < 1 THEN RAISE EXCEPTION 'signup_budget_take: p_max must be >= 1'; END IF;
  IF p_bucket_key IS NULL OR length(p_bucket_key) < 1 OR length(p_bucket_key) > 200 THEN RAISE EXCEPTION 'signup_budget_take: bad bucket key'; END IF;
  IF p_window_start IS NULL THEN RAISE EXCEPTION 'signup_budget_take: window required'; END IF;
  -- First hit inserts count = 1. Later hits increment only while under the cap. One statement, one row
  -- lock, so a parallel batch on the same bucket is admitted exactly up to p_max and no further.
  INSERT INTO public.signup_budgets AS b (bucket_key, window_start, count)
  VALUES (p_bucket_key, p_window_start, 1)
  ON CONFLICT (bucket_key, window_start) DO UPDATE
    SET count = b.count + 1, updated_at = now()
    WHERE b.count < p_max
  RETURNING b.count INTO v_count;
  IF v_count IS NULL THEN
    SELECT b.count INTO v_count FROM public.signup_budgets b WHERE b.bucket_key = p_bucket_key AND b.window_start = p_window_start;
    admitted := false; count := coalesce(v_count, p_max);
  ELSE
    admitted := true; count := v_count;
  END IF;
  RETURN NEXT;
  IF random() < 0.05 THEN
    DELETE FROM public.signup_budgets WHERE window_start < now() - interval '2 days';
  END IF;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.slot_minutes(p_time text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE m text[]; v_h integer; v_min integer; v_ampm text;
BEGIN
  m := regexp_match(coalesce(p_time, ''), '^\s*(\d{1,2})(?::(\d{2}))?\s*([AaPp]\.?[Mm]\.?)?\s*$');
  IF m IS NULL THEN RETURN NULL; END IF;
  v_h    := m[1]::integer;
  v_min  := coalesce(m[2]::integer, 0);
  v_ampm := lower(replace(coalesce(m[3], ''), '.', ''));
  IF v_min > 59 THEN RETURN NULL; END IF;
  IF v_ampm <> '' THEN
    IF v_h < 1 OR v_h > 12 THEN RETURN NULL; END IF;
    IF v_ampm = 'pm' AND v_h <> 12 THEN v_h := v_h + 12; END IF;
    IF v_ampm = 'am' AND v_h = 12 THEN v_h := 0; END IF;
  ELSIF v_h > 23 THEN
    RETURN NULL;
  END IF;
  RETURN v_h * 60 + v_min;
END $function$

CREATE OR REPLACE FUNCTION public.store_calendar_link_ensure(p_retailer_id uuid, p_venue_id uuid, p_token_hash text, p_token_enc text, p_email text)
 RETURNS TABLE(outcome text, id uuid, retailer_id uuid, venue_id uuid, token_hash text, token_enc text, issued_at timestamp with time zone, issued_by_email text, last_used_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_scope uuid; v_row public.store_calendar_links;
BEGIN
  IF p_retailer_id IS NULL THEN RAISE EXCEPTION 'retailer_required'; END IF;
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'token_hash_shape'; END IF;
  IF p_token_enc IS NULL OR p_token_enc !~ '^v1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$' THEN RAISE EXCEPTION 'token_enc_shape'; END IF;
  IF p_venue_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.venues v WHERE v.id = p_venue_id AND v.retailer_id = p_retailer_id) THEN
    RAISE EXCEPTION 'venue_not_in_retailer';
  END IF;
  v_scope := coalesce(p_venue_id, '00000000-0000-0000-0000-000000000000'::uuid);
  PERFORM pg_advisory_xact_lock(hashtext('store_calendar_link:' || p_retailer_id::text || ':' || v_scope::text));
  IF EXISTS (SELECT 1 FROM public.store_calendar_scope_state s WHERE s.retailer_id = p_retailer_id AND s.scope_key = v_scope AND s.disabled_at IS NOT NULL) THEN
    RETURN QUERY SELECT 'disabled'::text, NULL::uuid, p_retailer_id, p_venue_id, NULL::text, NULL::text, NULL::timestamptz, NULL::text, NULL::timestamptz;
    RETURN;
  END IF;
  SELECT l.* INTO v_row FROM public.store_calendar_links l
   WHERE l.retailer_id = p_retailer_id AND l.revoked_at IS NULL
     AND coalesce(l.venue_id, '00000000-0000-0000-0000-000000000000'::uuid) = v_scope
   LIMIT 1;
  IF FOUND THEN
    RETURN QUERY SELECT 'existing'::text, v_row.id, v_row.retailer_id, v_row.venue_id, v_row.token_hash, v_row.token_enc, v_row.issued_at, v_row.issued_by_email, v_row.last_used_at;
    RETURN;
  END IF;
  INSERT INTO public.store_calendar_links (retailer_id, venue_id, token_hash, token_enc, issued_by_email)
  VALUES (p_retailer_id, p_venue_id, p_token_hash, p_token_enc, p_email) RETURNING * INTO v_row;
  RETURN QUERY SELECT 'created'::text, v_row.id, v_row.retailer_id, v_row.venue_id, v_row.token_hash, v_row.token_enc, v_row.issued_at, v_row.issued_by_email, v_row.last_used_at;
END $function$

CREATE OR REPLACE FUNCTION public.store_calendar_link_issue(p_retailer_id uuid, p_venue_id uuid, p_token_hash text, p_token_enc text, p_email text)
 RETURNS store_calendar_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.store_calendar_links; v_scope uuid;
BEGIN
  IF p_retailer_id IS NULL THEN RAISE EXCEPTION 'retailer_required'; END IF;
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'token_hash_shape'; END IF;
  IF p_token_enc IS NULL OR p_token_enc !~ '^v1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$' THEN RAISE EXCEPTION 'token_enc_shape'; END IF;
  IF p_venue_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.venues WHERE id = p_venue_id AND retailer_id = p_retailer_id) THEN
    RAISE EXCEPTION 'venue_not_in_retailer';
  END IF;
  v_scope := coalesce(p_venue_id, '00000000-0000-0000-0000-000000000000'::uuid);
  PERFORM pg_advisory_xact_lock(hashtext('store_calendar_link:' || p_retailer_id::text || ':' || v_scope::text));
  IF EXISTS (SELECT 1 FROM public.store_calendar_scope_state s WHERE s.retailer_id = p_retailer_id AND s.scope_key = v_scope AND s.disabled_at IS NOT NULL) THEN
    RAISE EXCEPTION 'scope_disabled';
  END IF;
  UPDATE public.store_calendar_links SET revoked_at = now(), revoked_by_email = p_email
   WHERE retailer_id = p_retailer_id AND revoked_at IS NULL
     AND coalesce(venue_id, '00000000-0000-0000-0000-000000000000'::uuid) = v_scope;
  INSERT INTO public.store_calendar_links (retailer_id, venue_id, token_hash, token_enc, issued_by_email)
  VALUES (p_retailer_id, p_venue_id, p_token_hash, p_token_enc, p_email) RETURNING * INTO v_row;
  RETURN v_row;
END $function$

CREATE OR REPLACE FUNCTION public.store_calendar_link_revoke(p_retailer_id uuid, p_venue_id uuid, p_email text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int; v_scope uuid;
BEGIN
  IF p_retailer_id IS NULL THEN RAISE EXCEPTION 'retailer_required'; END IF;
  v_scope := coalesce(p_venue_id, '00000000-0000-0000-0000-000000000000'::uuid);
  PERFORM pg_advisory_xact_lock(hashtext('store_calendar_link:' || p_retailer_id::text || ':' || v_scope::text));
  UPDATE public.store_calendar_links SET revoked_at = now(), revoked_by_email = p_email
   WHERE retailer_id = p_retailer_id AND revoked_at IS NULL
     AND coalesce(venue_id, '00000000-0000-0000-0000-000000000000'::uuid) = v_scope;
  GET DIAGNOSTICS n = ROW_COUNT;
  INSERT INTO public.store_calendar_scope_state (retailer_id, scope_key, disabled_at, disabled_by_email)
  VALUES (p_retailer_id, v_scope, now(), p_email)
  ON CONFLICT (retailer_id, scope_key) DO UPDATE SET disabled_at = now(), disabled_by_email = EXCLUDED.disabled_by_email;
  RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.store_calendar_scope_enable(p_retailer_id uuid, p_venue_id uuid, p_email text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_scope uuid; n int;
BEGIN
  IF p_retailer_id IS NULL THEN RAISE EXCEPTION 'retailer_required'; END IF;
  v_scope := coalesce(p_venue_id, '00000000-0000-0000-0000-000000000000'::uuid);
  PERFORM pg_advisory_xact_lock(hashtext('store_calendar_link:' || p_retailer_id::text || ':' || v_scope::text));
  UPDATE public.store_calendar_scope_state SET disabled_at = NULL, enabled_at = now(), enabled_by_email = p_email
   WHERE retailer_id = p_retailer_id AND scope_key = v_scope AND disabled_at IS NOT NULL;
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.venue_availability_apply_all(p_retailer_id uuid, p_source_venue_id uuid, p_expected_version integer, p_schedule jsonb DEFAULT NULL::jsonb, p_slots jsonb DEFAULT NULL::jsonb, p_reset_slots boolean DEFAULT false, p_max_demos_per_slot integer DEFAULT NULL::integer, p_copy_slots boolean DEFAULT false)
 RETURNS TABLE(ok boolean, reason text, detail jsonb, venue_id uuid, venue_name text, availability jsonb, availability_version integer, max_demos_per_slot integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_locked venues[]; src venues%ROWTYPE; v venues%ROWTYPE; v_av jsonb; v_src_av jsonb;
  v_msg text; v_detail text; v_reason text; v_rows jsonb := '[]'::jsonb; i integer;
BEGIN
  IF p_retailer_id IS NULL OR p_source_venue_id IS NULL THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::jsonb, NULL::uuid, NULL::text, NULL::jsonb, NULL::integer, NULL::integer; RETURN;
  END IF;
  IF NOT p_copy_slots AND (p_slots IS NOT NULL OR p_reset_slots) THEN
    RAISE EXCEPTION 'slot_editing_disabled: slot lists cannot change in hours-only mode' USING errcode = 'check_violation';
  END IF;
  v_locked := '{}';
  FOR v IN SELECT * FROM venues WHERE retailer_id = p_retailer_id ORDER BY id FOR UPDATE LOOP v_locked := v_locked || v; END LOOP;
  IF cardinality(v_locked) = 0 THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::jsonb, NULL::uuid, NULL::text, NULL::jsonb, NULL::integer, NULL::integer; RETURN;
  END IF;
  src := NULL;
  FOR i IN 1..cardinality(v_locked) LOOP IF v_locked[i].id = p_source_venue_id THEN src := v_locked[i]; END IF; END LOOP;
  IF src.id IS NULL THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::jsonb, NULL::uuid, NULL::text, NULL::jsonb, NULL::integer, NULL::integer; RETURN;
  END IF;
  IF p_expected_version IS NULL OR p_expected_version <> src.availability_version THEN
    RETURN QUERY SELECT false, 'stale_version'::text, jsonb_build_object('current_version', src.availability_version), src.id, src.name, src.availability, src.availability_version, src.max_demos_per_slot; RETURN;
  END IF;
  IF p_max_demos_per_slot IS NOT NULL AND p_max_demos_per_slot < 1 THEN
    RETURN QUERY SELECT false, 'invalid_capacity'::text, NULL::jsonb, src.id, src.name, src.availability, src.availability_version, src.max_demos_per_slot; RETURN;
  END IF;
  v_src_av := CASE WHEN src.availability IS NULL OR jsonb_typeof(src.availability) <> 'object' THEN '{}'::jsonb ELSE src.availability END;
  IF p_schedule IS NOT NULL THEN v_src_av := jsonb_set(v_src_av, '{schedule}', p_schedule, true); END IF;
  IF p_reset_slots THEN v_src_av := v_src_av - 'slots';
  ELSIF p_slots IS NOT NULL THEN v_src_av := jsonb_set(v_src_av, '{slots}', p_slots, true); END IF;
  IF NOT (v_src_av ? 'blackouts') THEN v_src_av := jsonb_set(v_src_av, '{blackouts}', '[]'::jsonb, true); END IF;
  BEGIN
    FOR i IN 1..cardinality(v_locked) LOOP
      v := v_locked[i];
      IF v.id = src.id THEN
        v_av := v_src_av;
      ELSE
        v_av := CASE WHEN v.availability IS NULL OR jsonb_typeof(v.availability) <> 'object' THEN '{}'::jsonb ELSE v.availability END;
        IF v_src_av ? 'schedule' THEN v_av := jsonb_set(v_av, '{schedule}', v_src_av->'schedule', true); ELSE v_av := v_av - 'schedule'; END IF;
        IF p_copy_slots THEN
          IF v_src_av ? 'slots' THEN v_av := jsonb_set(v_av, '{slots}', v_src_av->'slots', true); ELSE v_av := v_av - 'slots'; END IF;
        END IF;
        IF NOT (v_av ? 'blackouts') THEN v_av := jsonb_set(v_av, '{blackouts}', '[]'::jsonb, true); END IF;
      END IF;
      BEGIN
        UPDATE venues
           SET availability = v_av,
               availability_version = venues.availability_version + 1,
               max_demos_per_slot = coalesce(p_max_demos_per_slot, src.max_demos_per_slot)
         WHERE id = v.id
        RETURNING * INTO v;
      EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL;
        v_reason := split_part(v_msg, ':', 1);
        IF v_reason NOT IN ('slot_in_use', 'availability_invalid', 'slot_config_invalid', 'capacity_below_active_reservations') THEN RAISE; END IF;
        RAISE EXCEPTION 'apply_all_refused' USING errcode = 'check_violation',
          detail = jsonb_build_object('reason', v_reason, 'venue_id', v.id, 'venue_name', v.name, 'message', v_msg,
                                      'affected', CASE WHEN coalesce(v_detail,'') <> '' THEN v_detail::jsonb ELSE NULL END)::text;
      END;
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('venue_id', v.id, 'venue_name', v.name, 'availability', v.availability,
                                                               'availability_version', v.availability_version, 'max_demos_per_slot', v.max_demos_per_slot));
    END LOOP;
  EXCEPTION WHEN check_violation THEN
    GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL;
    IF v_msg <> 'apply_all_refused' THEN RAISE; END IF;
    RETURN QUERY SELECT false, (v_detail::jsonb)->>'reason', v_detail::jsonb,
                        ((v_detail::jsonb)->>'venue_id')::uuid, (v_detail::jsonb)->>'venue_name', NULL::jsonb, NULL::integer, NULL::integer;
    RETURN;
  END;
  RETURN QUERY SELECT true, NULL::text, NULL::jsonb, (e->>'venue_id')::uuid, e->>'venue_name', e->'availability',
                      (e->>'availability_version')::integer, (e->>'max_demos_per_slot')::integer
    FROM jsonb_array_elements(v_rows) e;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.venue_availability_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_old_slots text; v_new_slots text; v_tz text; v_today date; v_affected jsonb; v_n integer;
BEGIN
  PERFORM venue_availability_validate(NEW.availability);
  IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
  SELECT string_agg(sc.start_min::text || ':' || sc.hours::text, ',' ORDER BY sc.start_min) INTO v_old_slots FROM venue_slots_config(OLD.availability) sc;
  SELECT string_agg(sc.start_min::text || ':' || sc.hours::text, ',' ORDER BY sc.start_min) INTO v_new_slots FROM venue_slots_config(NEW.availability) sc;
  IF v_old_slots IS NOT DISTINCT FROM v_new_slots THEN RETURN NEW; END IF;   -- hours/blackout-only edit
  SELECT r.timezone INTO v_tz FROM retailers r WHERE r.id = NEW.retailer_id;
  v_today := (now() AT TIME ZONE coalesce(nullif(btrim(v_tz), ''), 'America/Los_Angeles'))::date;
  -- Every future active reservation must still map to an offered slot of the same length.
  SELECT count(*), jsonb_agg(jsonb_build_object('booking_id', x.id, 'demo_date', x.demo_date, 'demo_time', x.demo_time,
                                                'status', x.status, 'brand_name', x.brand_name) ORDER BY x.demo_date, x.demo_time)
    INTO v_n, v_affected
    FROM (
      SELECT b.id, b.demo_date, b.demo_time, b.status, b.brand_name
        FROM bookings b
       WHERE b.venue_id = NEW.id
         AND b.demo_date >= v_today
         AND coalesce(b.status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled')
         AND NOT EXISTS (
               SELECT 1 FROM venue_slots_config(NEW.availability) sc
                WHERE sc.start_min = slot_minutes(b.demo_time)
                  AND sc.hours = coalesce(b.duration_hours, 3))
       ORDER BY b.demo_date, b.demo_time
       LIMIT 50
    ) x;
  IF coalesce(v_n, 0) > 0 THEN
    RAISE EXCEPTION 'slot_in_use: % upcoming reservation(s) sit on a slot this change removes or shortens', v_n
      USING errcode = 'check_violation',
            detail  = v_affected::text,
            hint    = 'Keep those slots (same start and length) or wait until the demos have run. Nothing was changed.';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.venue_availability_set(p_retailer_id uuid, p_venue_id uuid, p_expected_version integer, p_schedule jsonb DEFAULT NULL::jsonb, p_slots jsonb DEFAULT NULL::jsonb, p_reset_slots boolean DEFAULT false, p_max_demos_per_slot integer DEFAULT NULL::integer)
 RETURNS TABLE(ok boolean, reason text, detail jsonb, availability jsonb, availability_version integer, max_demos_per_slot integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v venues%ROWTYPE; v_av jsonb; v_msg text; v_detail text; v_reason text;
BEGIN
  IF p_retailer_id IS NULL OR p_venue_id IS NULL THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::jsonb, NULL::jsonb, NULL::integer, NULL::integer; RETURN;
  END IF;
  SELECT * INTO v FROM venues WHERE id = p_venue_id AND retailer_id = p_retailer_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'not_found'::text, NULL::jsonb, NULL::jsonb, NULL::integer, NULL::integer; RETURN;
  END IF;
  IF p_expected_version IS NULL OR p_expected_version <> v.availability_version THEN
    RETURN QUERY SELECT false, 'stale_version'::text, jsonb_build_object('current_version', v.availability_version),
                        v.availability, v.availability_version, v.max_demos_per_slot; RETURN;
  END IF;
  IF p_max_demos_per_slot IS NOT NULL AND p_max_demos_per_slot < 1 THEN
    RETURN QUERY SELECT false, 'invalid_capacity'::text, NULL::jsonb, v.availability, v.availability_version, v.max_demos_per_slot; RETURN;
  END IF;
  v_av := coalesce(v.availability, '{}'::jsonb);
  IF jsonb_typeof(v_av) <> 'object' THEN v_av := '{}'::jsonb; END IF;
  IF p_schedule IS NOT NULL THEN v_av := jsonb_set(v_av, '{schedule}', p_schedule, true); END IF;
  IF p_reset_slots THEN v_av := v_av - 'slots';
  ELSIF p_slots IS NOT NULL THEN v_av := jsonb_set(v_av, '{slots}', p_slots, true); END IF;
  IF NOT (v_av ? 'blackouts') THEN v_av := jsonb_set(v_av, '{blackouts}', '[]'::jsonb, true); END IF;
  BEGIN
    UPDATE venues
       SET availability = v_av,
           availability_version = venues.availability_version + 1,
           max_demos_per_slot = coalesce(p_max_demos_per_slot, venues.max_demos_per_slot)
     WHERE id = p_venue_id
    RETURNING * INTO v;
  EXCEPTION WHEN check_violation THEN
    GET STACKED DIAGNOSTICS v_msg = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL;
    v_reason := split_part(v_msg, ':', 1);
    IF v_reason NOT IN ('slot_in_use', 'availability_invalid', 'slot_config_invalid', 'capacity_below_active_reservations') THEN RAISE; END IF;
    RETURN QUERY SELECT false, v_reason,
      CASE WHEN v_reason = 'slot_in_use' AND coalesce(v_detail, '') <> '' THEN jsonb_build_object('message', v_msg, 'affected', v_detail::jsonb)
           ELSE jsonb_build_object('message', v_msg) END,
      v.availability, v.availability_version, v.max_demos_per_slot;
    RETURN;
  END;
  RETURN QUERY SELECT true, NULL::text, NULL::jsonb, v.availability, v.availability_version, v.max_demos_per_slot;
END $function$

CREATE OR REPLACE FUNCTION public.venue_availability_validate(p_availability jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_dow integer;
BEGIN
  IF p_availability IS NULL THEN RETURN; END IF;
  IF jsonb_typeof(p_availability) <> 'object' THEN
    RAISE EXCEPTION 'availability_invalid: availability must be an object' USING errcode = 'check_violation';
  END IF;
  PERFORM * FROM venue_slots_config(p_availability);
  FOR v_dow IN 0..6 LOOP PERFORM * FROM venue_day_windows(p_availability, v_dow); END LOOP;
  PERFORM * FROM venue_blackout_dates(p_availability);
END $function$

CREATE OR REPLACE FUNCTION public.venue_blackout_dates(p_availability jsonb)
 RETURNS TABLE(blackout_date date, reason text, group_id text, entry_id text)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_arr jsonb; v_el jsonb; v_d date; v_seen text[] := '{}'; v_id text; v_g text;
BEGIN
  IF p_availability IS NULL OR jsonb_typeof(p_availability) <> 'object' OR NOT (p_availability ? 'blackouts') THEN RETURN; END IF;
  v_arr := p_availability->'blackouts';
  IF jsonb_typeof(v_arr) = 'null' THEN RETURN; END IF;
  IF jsonb_typeof(v_arr) <> 'array' THEN
    RAISE EXCEPTION 'availability_invalid: blackouts must be a list' USING errcode = 'check_violation';
  END IF;
  FOR v_el IN SELECT value FROM jsonb_array_elements(v_arr) LOOP
    IF jsonb_typeof(v_el) <> 'object' OR coalesce(v_el->>'date', '') !~ '^\d{4}-\d{2}-\d{2}$' THEN
      RAISE EXCEPTION 'availability_invalid: each blackout needs a date (YYYY-MM-DD)' USING errcode = 'check_violation';
    END IF;
    BEGIN v_d := (v_el->>'date')::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'availability_invalid: blackout date % is not a real date', v_el->>'date' USING errcode = 'check_violation';
    END;
    v_id := v_el->>'id';
    IF v_id IS NULL OR jsonb_typeof(v_el->'id') <> 'string' OR v_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'availability_invalid: blackout % has no valid entry id', v_d USING errcode = 'check_violation';
    END IF;
    IF lower(v_id) = ANY (v_seen) THEN
      RAISE EXCEPTION 'availability_invalid: blackout entry id % listed twice', v_id USING errcode = 'check_violation';
    END IF;
    v_seen := v_seen || lower(v_id);
    v_g := v_el->>'group_id';
    IF v_el ? 'group_id' AND (jsonb_typeof(v_el->'group_id') <> 'string' OR v_g !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') THEN
      RAISE EXCEPTION 'availability_invalid: blackout % has an invalid group id', v_d USING errcode = 'check_violation';
    END IF;
    IF v_el ? 'reason' AND jsonb_typeof(v_el->'reason') NOT IN ('string', 'null') THEN
      RAISE EXCEPTION 'availability_invalid: blackout reason must be text (%)', v_d USING errcode = 'check_violation';
    END IF;
    IF length(coalesce(v_el->>'reason', '')) > 200 THEN
      RAISE EXCEPTION 'availability_invalid: blackout reason too long (%)', v_d USING errcode = 'check_violation';
    END IF;
    blackout_date := v_d; reason := v_el->>'reason'; group_id := v_g; entry_id := v_id;
    RETURN NEXT;
  END LOOP;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.venue_blackouts_set(p_retailer_id uuid, p_op text, p_dates date[] DEFAULT NULL::date[], p_venue_ids uuid[] DEFAULT NULL::uuid[], p_reason text DEFAULT NULL::text, p_group_id uuid DEFAULT NULL::uuid, p_entry_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(venue_id uuid, venue_name text, availability_version integer, group_id uuid, blackouts jsonb, affected jsonb, added integer, removed integer, availability jsonb, max_demos_per_slot integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v venues%ROWTYPE; v_ids uuid[]; v_group uuid; v_arr jsonb; v_new jsonb; v_d date; v_reason text;
  v_affected jsonb; v_added integer; v_removed integer; v_has_local boolean; v_all boolean;
  v_entry_txt text[]; v_dates date[];
BEGIN
  IF p_retailer_id IS NULL THEN RAISE EXCEPTION 'not_found' USING errcode = 'no_data_found'; END IF;
  IF p_op NOT IN ('add', 'remove') THEN RAISE EXCEPTION 'invalid_op: % (add|remove)', p_op USING errcode = 'check_violation'; END IF;
  v_reason := nullif(btrim(coalesce(p_reason, '')), '');
  IF length(coalesce(v_reason, '')) > 200 THEN RAISE EXCEPTION 'invalid_reason: too long' USING errcode = 'check_violation'; END IF;
  IF p_op = 'add' THEN
    IF p_dates IS NULL OR cardinality(p_dates) = 0 OR cardinality(p_dates) > 366 THEN
      RAISE EXCEPTION 'invalid_dates: 1-366 dates required' USING errcode = 'check_violation';
    END IF;
    v_all := p_venue_ids IS NULL;
    IF v_all THEN
      SELECT array_agg(x.id ORDER BY x.id) INTO v_ids FROM venues x WHERE x.retailer_id = p_retailer_id;
    ELSE
      SELECT array_agg(x.id ORDER BY x.id) INTO v_ids FROM venues x WHERE x.retailer_id = p_retailer_id AND x.id = ANY (p_venue_ids);
      IF v_ids IS NULL OR cardinality(v_ids) <> cardinality(ARRAY(SELECT DISTINCT unnest(p_venue_ids))) THEN
        RAISE EXCEPTION 'not_found: a venue is not yours or does not exist' USING errcode = 'no_data_found';
      END IF;
    END IF;
    v_group := CASE WHEN v_all THEN gen_random_uuid() ELSE NULL END;
  ELSE
    IF (p_entry_ids IS NULL OR cardinality(p_entry_ids) = 0) AND p_group_id IS NULL THEN
      RAISE EXCEPTION 'invalid_target: entry ids or a group id are required to remove' USING errcode = 'check_violation';
    END IF;
    SELECT array_agg(x.id ORDER BY x.id) INTO v_ids FROM venues x WHERE x.retailer_id = p_retailer_id;
    v_group := p_group_id;
    SELECT coalesce(array_agg(lower(e::text)), '{}') INTO v_entry_txt FROM unnest(coalesce(p_entry_ids, '{}'::uuid[])) e;
  END IF;
  IF v_ids IS NULL OR cardinality(v_ids) = 0 THEN RETURN; END IF;
  SELECT array_agg(DISTINCT d ORDER BY d) INTO v_dates FROM unnest(coalesce(p_dates, '{}'::date[])) d;
  FOR v IN SELECT * FROM venues x WHERE x.id = ANY (v_ids) ORDER BY x.id FOR UPDATE LOOP
    v_arr := CASE WHEN v.availability IS NOT NULL AND jsonb_typeof(v.availability) = 'object'
                   AND jsonb_typeof(v.availability->'blackouts') = 'array' THEN v.availability->'blackouts' ELSE '[]'::jsonb END;
    v_added := 0; v_removed := 0;
    IF p_op = 'add' THEN
      v_new := v_arr;
      FOREACH v_d IN ARRAY v_dates LOOP
        IF NOT v_all THEN
          SELECT EXISTS (SELECT 1 FROM venue_blackout_dates(v.availability) bd WHERE bd.blackout_date = v_d AND bd.group_id IS NULL) INTO v_has_local;
          IF v_has_local THEN CONTINUE; END IF;
        END IF;
        v_new := v_new || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
                   'id', gen_random_uuid()::text, 'date', to_char(v_d, 'YYYY-MM-DD'), 'reason', v_reason,
                   'group_id', v_group::text, 'created_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))));
        v_added := v_added + 1;
      END LOOP;
    ELSE
      SELECT coalesce(jsonb_agg(e.value), '[]'::jsonb) INTO v_new
        FROM jsonb_array_elements(v_arr) e
       WHERE NOT ( lower(coalesce(e.value->>'id', '')) = ANY (v_entry_txt)
                   OR (p_group_id IS NOT NULL AND lower(coalesce(e.value->>'group_id', '')) = lower(p_group_id::text)) );
      v_removed := jsonb_array_length(v_arr) - jsonb_array_length(v_new);
    END IF;
    IF v_added > 0 OR v_removed > 0 THEN
      UPDATE venues
         SET availability = jsonb_set(CASE WHEN v.availability IS NULL OR jsonb_typeof(v.availability) <> 'object' THEN '{}'::jsonb ELSE v.availability END,
                                      '{blackouts}', v_new, true),
             availability_version = venues.availability_version + 1
       WHERE id = v.id
      RETURNING venues.availability, venues.availability_version INTO v.availability, v.availability_version;
    END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('booking_id', b.id, 'demo_date', b.demo_date, 'demo_time', b.demo_time,
                                                 'status', b.status, 'brand_name', b.brand_name) ORDER BY b.demo_date, b.demo_time), '[]'::jsonb)
      INTO v_affected
      FROM bookings b
     WHERE b.venue_id = v.id AND p_op = 'add' AND b.demo_date = ANY (v_dates)
       AND coalesce(b.status,'pending') NOT IN ('cancelled','declined','expired','auth_canceled');
    venue_id := v.id; venue_name := v.name; availability_version := v.availability_version;
    group_id := v_group; blackouts := v_new; affected := v_affected; added := v_added; removed := v_removed;
    availability := v.availability; max_demos_per_slot := v.max_demos_per_slot;
    RETURN NEXT;
  END LOOP;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.venue_day_windows(p_availability jsonb, p_dow integer)
 RETURNS TABLE(open_min integer, close_min integer)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_day jsonb; v_el jsonb; v_o integer; v_c integer;
BEGIN
  IF p_availability IS NULL OR jsonb_typeof(p_availability) <> 'object' OR NOT (p_availability ? 'schedule') THEN RETURN; END IF;
  IF jsonb_typeof(p_availability->'schedule') <> 'object' THEN
    RAISE EXCEPTION 'availability_invalid: schedule must be an object' USING errcode = 'check_violation';
  END IF;
  v_day := p_availability->'schedule'->(p_dow::text);
  IF v_day IS NULL OR jsonb_typeof(v_day) = 'null' THEN RETURN; END IF;
  IF jsonb_typeof(v_day) = 'object' THEN v_day := jsonb_build_array(v_day); END IF;
  IF jsonb_typeof(v_day) <> 'array' THEN
    RAISE EXCEPTION 'availability_invalid: schedule day % must be a list of windows', p_dow USING errcode = 'check_violation';
  END IF;
  FOR v_el IN SELECT value FROM jsonb_array_elements(v_day) LOOP
    IF jsonb_typeof(v_el) <> 'object' THEN
      RAISE EXCEPTION 'availability_invalid: window on day % must be an object', p_dow USING errcode = 'check_violation';
    END IF;
    IF coalesce(v_el->>'open', '') = '' AND coalesce(v_el->>'close', '') = '' THEN CONTINUE; END IF;
    v_o := slot_minutes(v_el->>'open'); v_c := slot_minutes(v_el->>'close');
    IF v_o IS NULL OR v_c IS NULL OR v_c <= v_o THEN
      RAISE EXCEPTION 'availability_invalid: window %-% on day % is not a valid open/close pair',
        coalesce(v_el->>'open','?'), coalesce(v_el->>'close','?'), p_dow USING errcode = 'check_violation';
    END IF;
    open_min := v_o; close_min := v_c; RETURN NEXT;
  END LOOP;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.venue_slot_offered(p_availability jsonb, p_date date, p_minutes integer)
 RETURNS TABLE(ok boolean, reason text, hours integer)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_hours integer; v_dow integer; v_fits boolean; v_has_windows boolean;
BEGIN
  IF EXISTS (SELECT 1 FROM venue_blackout_dates(p_availability) bd WHERE bd.blackout_date = p_date) THEN
    RETURN QUERY SELECT false, 'date_blackout'::text, NULL::integer; RETURN;
  END IF;
  IF NOT venue_schedule_present(p_availability) THEN
    RETURN QUERY SELECT false, 'venue_hours_not_set'::text, NULL::integer; RETURN;
  END IF;
  SELECT sc.hours INTO v_hours FROM venue_slots_config(p_availability) sc WHERE sc.start_min = p_minutes;
  IF v_hours IS NULL THEN RETURN QUERY SELECT false, 'slot_not_offered'::text, NULL::integer; RETURN; END IF;
  v_dow := extract(dow FROM p_date)::integer;
  SELECT count(*) > 0, bool_or(p_minutes >= w.open_min AND p_minutes + v_hours * 60 <= w.close_min)
    INTO v_has_windows, v_fits FROM venue_day_windows(p_availability, v_dow) w;
  IF NOT coalesce(v_has_windows, false) THEN RETURN QUERY SELECT false, 'venue_closed'::text, NULL::integer; RETURN; END IF;
  IF NOT coalesce(v_fits, false) THEN RETURN QUERY SELECT false, 'slot_outside_hours'::text, NULL::integer; RETURN; END IF;
  RETURN QUERY SELECT true, NULL::text, v_hours;
END $function$

CREATE OR REPLACE FUNCTION public.venue_slots_config(p_availability jsonb)
 RETURNS TABLE(start_min integer, hours integer)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_slots jsonb; v_el jsonb; v_start text; v_hours jsonb; v_min integer; v_h integer;
  v_prev_end integer := -1; v_starts integer[] := '{}'; v_hrs integer[] := '{}'; v_seen integer[] := '{}'; r record;
BEGIN
  IF p_availability IS NULL OR jsonb_typeof(p_availability) <> 'object' OR NOT (p_availability ? 'slots') THEN
    RETURN QUERY SELECT 660, 3 UNION ALL SELECT 900, 3;   -- 11:00 / 3h, 3:00 PM / 3h
    RETURN;
  END IF;
  v_slots := p_availability->'slots';
  IF jsonb_typeof(v_slots) <> 'array' THEN
    RAISE EXCEPTION 'slot_config_invalid: slots must be a list' USING errcode = 'check_violation';
  END IF;
  IF jsonb_array_length(v_slots) > 24 THEN
    RAISE EXCEPTION 'slot_config_invalid: at most 24 slots' USING errcode = 'check_violation';
  END IF;
  FOR v_el IN SELECT value FROM jsonb_array_elements(v_slots) LOOP
    IF jsonb_typeof(v_el) <> 'object' THEN
      RAISE EXCEPTION 'slot_config_invalid: each slot must be an object' USING errcode = 'check_violation';
    END IF;
    v_start := v_el->>'start'; v_hours := v_el->'hours';
    IF v_start IS NULL OR v_start !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
      RAISE EXCEPTION 'slot_config_invalid: start must be HH:MM (got %)', coalesce(v_start, 'null') USING errcode = 'check_violation';
    END IF;
    IF v_hours IS NULL OR jsonb_typeof(v_hours) <> 'number' OR (v_hours::text) !~ '^\d+$' THEN
      RAISE EXCEPTION 'slot_config_invalid: hours must be a whole number (slot %)', v_start USING errcode = 'check_violation';
    END IF;
    v_h := (v_hours::text)::integer;
    IF v_h < 1 OR v_h > 12 THEN
      RAISE EXCEPTION 'slot_config_invalid: hours must be 1-12 (slot %)', v_start USING errcode = 'check_violation';
    END IF;
    v_min := substr(v_start, 1, 2)::integer * 60 + substr(v_start, 4, 2)::integer;
    -- B-08: a slot must END before midnight (24:00 is refused for this bounded release).
    IF v_min + v_h * 60 >= 1440 THEN
      RAISE EXCEPTION 'slot_config_invalid: slot % must end before midnight', v_start USING errcode = 'check_violation';
    END IF;
    IF v_min = ANY (v_seen) THEN
      RAISE EXCEPTION 'slot_config_invalid: duplicate start %', v_start USING errcode = 'check_violation';
    END IF;
    v_seen := v_seen || v_min; v_starts := v_starts || v_min; v_hrs := v_hrs || v_h;
  END LOOP;
  FOR r IN SELECT t.s, t.h FROM unnest(v_starts, v_hrs) AS t(s, h) ORDER BY t.s LOOP
    IF r.s < v_prev_end THEN
      RAISE EXCEPTION 'slot_config_invalid: slot % overlaps the previous slot', slot_label(r.s) USING errcode = 'check_violation';
    END IF;
    v_prev_end := r.s + r.h * 60;
    start_min := r.s; hours := r.h; RETURN NEXT;
  END LOOP;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.verification_throttle_hit(p_scope text, p_key text, p_purpose text, p_limit integer, p_window_minutes integer DEFAULT 60, p_block_minutes integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_key    text := lower(btrim(p_key));
  v_window timestamptz := date_trunc('hour', now())
                          + (floor(extract(minute from now()) / greatest(1, p_window_minutes))
                             * make_interval(mins => greatest(1, p_window_minutes)));
  v_row    public.verification_throttle;
begin
  if v_key = '' then return jsonb_build_object('allowed', false, 'reason', 'no_key'); end if;
  insert into public.verification_throttle (scope, key, purpose, window_start, attempts)
  values (p_scope, v_key, p_purpose, v_window, 0)
  on conflict (scope, key, purpose, window_start) do nothing;
  select * into v_row from public.verification_throttle
  where scope = p_scope and key = v_key and purpose = p_purpose and window_start = v_window
  for update;
  if v_row.blocked_until is not null and v_row.blocked_until > now() then
    return jsonb_build_object('allowed', false, 'reason', 'blocked', 'until', v_row.blocked_until);
  end if;
  if v_row.attempts + 1 > p_limit then
    update public.verification_throttle
      set attempts = attempts + 1,
          blocked_until = now() + make_interval(mins => greatest(1, p_block_minutes))
      where id = v_row.id;
    return jsonb_build_object('allowed', false, 'reason', 'limit_exceeded');
  end if;
  update public.verification_throttle set attempts = attempts + 1 where id = v_row.id;
  return jsonb_build_object('allowed', true, 'attempts', v_row.attempts + 1, 'limit', p_limit);
end $function$
